var e={"tool.look":`Patrz`,"tool.build":`Buduj`,"tool.remove":`Wyburz`,"action.rotate":`Obróć`,"action.undo":`Cofnij`,"action.redo":`Ponów`,"action.inventory":`Ekwipunek`,"action.alt":`Szczegóły`,"action.close":`Zamknij`,"action.save":`Zapisz`,"key.hint":`{key}`,"status.0":`Czeka`,"status.1":`Pracuje`,"status.2":`Brak wejścia`,"status.3":`Wyjście pełne`,"status.4":`Brak pasa w zasięgu`,"status.5":`Brak receptury`,"status.6":`Brak celu`,"status.2.hint":`Podaj składniki chwytakiem albo włóż je ręcznie.`,"status.3.hint":`Odbierz produkt chwytakiem lub przyciskiem „Weź”. Płyn — poprowadź rury lub postaw zbiornik.`,"status.4.hint":`Wydobywarka nie sięga pasa — przestaw ją bliżej pasma skał: widmo budynku w ręce czerwienieje, gdy pas jest poza zasięgiem.`,"status.5.hint":`Wybierz recepturę poniżej.`,"status.6.hint":`Chwytak potrzebuje maszyny lub grawitaśmy z przodu i z tyłu.`,"machine.recipe":`Receptura`,"machine.input":`Wejście`,"machine.output":`Wyjście`,"machine.contents":`Zawartość`,"machine.empty":`Pusto`,"machine.held":`W ręce`,"machine.take":`Weź`,"machine.put":`Włóż: {item}`,"machine.remove":`Wyburz`,"machine.time":`{s} s`,"inv.title":`Ekwipunek`,"inv.craft":`Ręczne wytwarzanie`,"inv.queue":`Kolejka`,"inv.missing":`Brakuje`,"inv.craftOne":`×1`,"inv.craftFive":`×5`,"inv.cancel":`Anuluj`,"inv.empty":`Pusto`,"goal.title":`Cel`,"goal.skip":`Zwiń cel`,"goal.ask.go":`Pokaż`,"goal.show":`Pokaż cele`,"goal.done":`Wszystkie cele wykonane! Dalej — twoja własna fabryka wokół żywej gwiazdy.`,"goal.mine":`Wydobądź ręcznie kwarc: {n}`,"goal.mine.hint":`{touch, select, yes {Stuknij niebieską skałę w pasie przy znaczniku — wiązka kutra sama będzie wydobywać kwarc; ponowne stuknięcie tej samej skały ją zatrzyma.} other {Kliknij niebieską skałę w pasie przy znaczniku — wiązka kutra sama będzie wydobywać kwarc; ponowne kliknięcie tej samej skały ją zatrzyma.}}`,"goal.grinder":`Postaw szlifiernię obok odbiornika promieni`,"goal.grinder.hint":`Pasek budynków → szlifiernia → miejsce obok odbiornika promieni. Potem „Patrz”, {touch, select, yes {stuknij} other {kliknij}} ją i wybierz „Soczewka”.`,"goal.grabber":`Połącz linię chwytakami: pierwsza soczewka`,"goal.grabber.hint":`Chwytak bierze z tyłu i kładzie do przodu, zgodnie ze strzałką. Pierwszy: grawitaśma → szlifiernia. Drugi: szlifiernia → magazyn (skrzynia).`,"goal.lenses":`Poczekaj na {n, plural, one {# soczewkę} few {# soczewki} many {# soczewek} other {# soczewki}} z linii`,"goal.lenses.hint":`Nic do roboty: linia robi soczewkę co {sec} s. Stanęła — {touch, select, yes {stuknij} other {kliknij}} maszynę z plakietką, w jej oknie jest powód.`,"goal.obsidian":`Harpun na pomarańczowe skały, potem {n, plural, one {# płytę} few {# płyty} many {# płyt} other {# płyty}} z linii`,"goal.obsidian.hint":`Trzeci harpun idzie w ramkę między pasem a szlifiernią płyt, wyjściem (jasny punkt) prosto do niej: sam ładuje szlifiernię, grawitaśma niepotrzebna. Gdy złowi skałę, ramka gaśnie, a linia sama robi płyty: poczekaj na {n}. Światło: jeszcze jeden łuk i światłowód.`,"goal.expand":`Druga szlifiernia — na płyty, przy pomarańczowych skałach`,"goal.expand.hint":`Wytwórz szlifiernię w oknie „Ekwipunek” ({plates} płyt, {quartz} kwarcu) i postaw ją w ramce przy pomarańczowym pasie — od strony bazy. Receptura: „Płyta obsydianowa”. Harpun idzie między nią a pas: grawitaśmy nie przechodzą przez pas.`,"goal.progress":`{have} / {need}`,"toast.saved":`Zapisano`,"toast.loaded":`Świat wczytany`,"toast.noItem":`Brak „{item}” w ekwipunku — wytwórz to w ekwipunku`,"toast.newWorld":`Nowy świat`,"hud.mining":`Wydobycie`,"hud.debug":`FPS {fps} · UPS {ups} · tyk {tick} · maszyny {entities} · hasz {hash}`,"hotbar.label":`Budynki`,"a11y.game":`Pole gry Heliohold`,"machine.rate":`Zużywa {rate} {item}/s`,"machine.drills":`≈ harpuny na wejściu: {n}`,"action.pause":`Pauza`,"action.resume":`Wznów`,"hud.paused":`Pauza`,"toast.recipeCopied":`Receptura skopiowana — Shift+klik na montowni, by ją wkleić`,"goal.light":`Doprowadź światło z odbiornika do szlifierni`,"goal.light.hint":`Przeciągnij światłowód od talerza odbiornika do boku szlifierni — albo postaw szlifiernię tuż przy odbiorniku: światło popłynie i bez światłowodu. Rozświetlona — światło dotarło. Jeden Łuk I daje {arc} ph/s (fotonów na sekundę) — dokładnie jedną szlifiernię.`,"goal.collectors":`Światło dla bazy: {n} ph/s ({arcs, plural, one {# łuk} few {# łuki} many {# łuków} other {# łuku}})`,"goal.collectors.hint":`Wytwórz „Łuk I” w „Ekwipunku” i rzuć na pierścień przy gwieździe. Każdy łuk daje {arc} ph/s; jeden odbiornik przyjmuje do {cap}.`,"goal.mix":`Zmieszaj bursztyn`,"goal.mix.hint":`Mieszalnik: różne barwy na boczne wejścia → bursztyn do przodu. To samo światło z obu stron się pali. Nie łącz barw w jednym światłowodzie — zaczną interferować.`,"goal.focus":`Zrób rezonatory`,"goal.focus.hint":`Rezonator potrzebuje białego światła o jasności {b}: skupiacz podnosi jasność o 1. Długi światłowód słabnie co {fade} pól.`,"machine.light":`Światło: {amount} ph, kolor: {color}, jasność ≥ {b}`,"machine.flux":`Strumień: {n} ph/s`,"machine.lightBuf":`W buforze: {n} ph`,"color.1":`szkarłatny`,"color.2":`szmaragdowy`,"color.4":`lazurowy`,"color.3":`bursztynowy`,"color.6":`turkusowy`,"color.5":`purpurowy`,"color.7":`biały`,"status.7":`Brak światła`,"status.8":`Słabe światło`,"status.9":`Zakłócenia`,"status.10":`Zły kolor`,"status.7.hint":`Poprowadź światłowód od odbiornika albo postaw maszynę tuż przy jego wyjściu. Światło gromadzi się porcjami na cykl.`,"status.8.hint":`Za mało jasne: sieci dłuższe niż {fade} pól ciemnieją — skróć ją albo dodaj skupiacz.`,"status.9.hint":`Jedna barwa — jedna sieć: stykające się światłowody łączą się. Oddziel sieci różnych barw pustym polem; trzymany światłowód podświetla to, z czym się połączy.`,"status.10.hint":`Receptura potrzebuje innej barwy — podłącz właściwe wyjście pryzmatu lub mieszalnika.`,"goal.beam":`Wyślij światło wiązką`,"goal.beam.hint":`Port na światłowodzie zamienia światło w wiązkę, lustro ją skręca, port naprzeciw ją przyjmuje. Port bez odbiorcy marnuje światło.`,"goal.plates":`Jeszcze jeden harpun na linię płyt: {n, plural, one {# płytę} few {# płyty} many {# płyt} other {# płyty}}`,"goal.plates.hint":`Harpun kosztuje {lenses} soczewek i {plates} płyt: soczewki leżą w skrzyni linii — „Weź” w jej oknie. Wytwórz harpun w ekwipunku i postaw w ramce obok szlifierni płyt, wyjściem do niej. Gdy stanie, ramka gaśnie, a linia rusza pełną parą: poczekaj na {n} płyt. Szlifiernia potrzebuje {light} ph/s światła: brakuje — rzuć jeszcze jeden łuk.`,"action.sound":`Dźwięk`,"action.soundOn":`Włącz dźwięk`,"action.soundOff":`Wyłącz dźwięk`,"stats.title":`Statystyki`,"stats.min1":`1 min`,"stats.min10":`10 min`,"stats.perMin":`{n}/min`,"stats.empty":`Na razie nic nie wyprodukowano.`,"goal.completed":`Cel osiągnięty`,"goal.mine.why":`Śpiący na zasilaniu awaryjnym. Uratuje ich fabryka, a ta zaczyna się od kwarcu.`,"goal.grinder.why":`Dowódco, bez soczewek żadna maszyna z archiwum się nie złoży. Szlifiernia wycina je z kwarcu.`,"goal.light.why":`Światło łuku trzeba doprowadzić do maszyn. Światłowód to pierwsza żyła — przez nią popłynie też do śpiących.`,"goal.grabber.why":`Fabryka, która czeka na twoje ręce, śpiących nie uratuje. Chwytaki — i linia ruszy sama.`,"goal.lenses.why":`Zapas soczewek to czas, który zyskujesz dla śpiących.`,"goal.expand.why":`Moduł trzeba łatać, a potem — wrota do domu. Jedno i drugie powstaje z płyt.`,"goal.obsidian.why":`Płyty ręcznie — do emerytury. Linia zrobi je sama, a przed nami jeszcze wrota.`,"goal.plates.why":`Płyty idą na wszystko: na maszyny, łaty, przyszłe wrota. Pełne światło — pełna prędkość.`,"goal.collectors.why":`Wrota pochłoną mnóstwo światła. Każdy łuk to kawałek przyszłej sfery wokół Kolebki.`,"goal.mix.why":`Po nalocie jasne: baza potrzebuje obrony. Bursztyn to ładunek Włóczni, po {n} na każdą. Zmieszamy go sami.`,"goal.focus.why":`Rezonator utrzymuje światło równym. Buduje się z niego Włócznię i nowsze maszyny — a równe światło mniej oślepia Rój.`,"goal.beam.why":`Kolonia potrzebuje światła za pasami — tam są nowe skały i miejsce na maszyny. Wiązka niesie światło daleko, nie słabnie i przelatuje nad pasami.`,"goal.spectrum_m.why":`Spektrum to próbka światła jednej klasy gwiazd. Archiwum odblokowuje plany według odczytanych klas: pierwsza, M, otworzy Rezonans.`,"goal.spectrum_m.hint":`Montownia: receptura „Spektrum M” — rubinowa soczewka, płyta i czerwone światło. Dostarcz je do Centrum grawitaśmą i chwytakiem albo ręcznie.`,"goal.spectrum_m":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} M do Centrum`,"goal.resonance.why":`Rezonans przyspiesza wydobywarki dwukrotnie: fabryka rośnie szybciej — i światło szybciej dociera do śpiących.`,"goal.resonance.hint":`Zbadaj „Rezonans”. Żagiel na światłowodzie przyspiesza pobliskie wydobywarki; pylony niosą wzmocnienie dalej (do {link} pól). Harpuny muszą stać w strefie {zone}×{zone}.`,"goal.resonance":`Zbadaj Rezonans i wzmocnij {n, plural, one {# harpun} few {# harpuny} many {# harpunów} other {# harpuna}}`,"goal.spectrum_k.why":`Druga klasa gwiazd — K, pomarańczowa. Każda odczytana klasa odblokowuje w archiwum nowe plany — i przybliża wrota.`,"goal.spectrum_k.hint":`Zbadaj „Spektroskopię” i dodaj drugą montownię. K: bursztynowa soczewka, chwytak i bursztynowe światło mieszalnika (czerwień + szmaragd). Jeśli chwytak nie nadąża za montownią, wstaw szybki chwytak (Logistyka). Nie trzeba nosić ręcznie: chwytak ze stołu do skrzyni, grawitaśma ze skrzyni do montowni; skrzynię chwytaków obok uzupełniaj przyciskiem „Włóż wszystko”.`,"goal.spectrum_k":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} K do Centrum`,"goal.liquid.why":`Skondensowane światło to następny krok ku klasie G — klasie samej Kolebki. Bez płynnego światła nie odczyta się jej spektrum.`,"goal.liquid.hint":`Zbadaj „Płynne światło”. Lód bierze się z meteorytów: {touch, select, yes {stuknij meteoryt} other {kliknij meteoryt}} i przeleć przez odłamki. Postaw kondensator na lazurowym świetle pryzmatu i podaj mu lód. Płyn musi mieć dokąd płynąć: rura mieści {cap} j. — poprowadź {pipes} rur od kondensatora (potem zbiornik lub montownia spektrum G).`,"goal.liquid":`Wytwórz {n} j. płynnego światła`,"goal.spectrum_g.why":`Klasa G — jak sama Kolebka. Trzy odczytane klasy i Centrum rozłoży jej światło aż do najsłabszych linii.`,"goal.spectrum_g.hint":`Zbadaj „Klasa G”. Receptura: rezonator, płynne światło i bursztyn o jasności {b} (po skupiaczu).`,"goal.spectrum_g":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} G do Centrum`,"goal.mine.done":`Kwarc w ładowni. Pierwszy kamień kolonii, której nie było w planie. Zapisałam czas.`,"goal.grinder.done":`Szlifiernia! Na takiej zdawałem egzamin w szkółce. Wybierz jej recepturę „Soczewka” i daj światło oraz kamień.`,"goal.light.done":`Świeci! Skoro światło dotarło do szlifierni, dotrze i do śpiących. Nie od razu, ale dotrze.`,"goal.grabber.done":`Pierwsza soczewka z linii. Fabryka ożyła: pracuje, nawet gdy patrzysz w drugą stronę.`,"goal.lenses.done":`{n, plural, one {# soczewka} few {# soczewki} many {# soczewek} other {# soczewki}} — linia pracuje bez ciebie.`,"goal.expand.done":`Druga szlifiernia — na płyty, nimi załatamy moduł. Postaw przy niej harpun, wyjściem prosto do niej.`,"goal.obsidian.done":`Płyty ruszyły. Jest czym łatać moduł — i na czym budować kolonię.`,"goal.plates.done":`Ale tempo! Z taką linią i mnie niedługo wyciągną spod grodzi. Żartuję: śpiący najpierw.`,"goal.collectors.done":`{n} fotonów na sekundę — wystarczy na {grinders, plural, one {# szlifiernię} few {# szlifiernie} many {# szlifierni} other {# szlifierni}}.`,"goal.mix.done":`Bursztyn — kolor, którego pryzmat nie daje. To twoje dzieło.`,"goal.focus.done":`Rezonatory gotowe — światło schwytane w czystym drganiu.`,"goal.beam.done":`Wiązka dotarła. Światło nie jest już przywiązane do światłowodów.`,"goal.spectrum_m.done":`Centrum odczytało pierwsze spektrum! Brakuje jeszcze spektrów M: {n} — potem zbada Rezonans.`,"goal.resonance.done":`Harpuny w rezonansie — dwa razy szybciej.`,"goal.spectrum_k.done":`Druga klasa odczytana. Centrum zyskuje drugi pierścień i promienie.`,"goal.liquid.done":`Światło płynie rurami jak miód. Mama by nie uwierzyła.`,"goal.spectrum_g.done":`Trzy spektra odczytane. Centrum jest gotowe na Głęboki sygnał.`,"intro.title":`Siewnik „Jaskółka”`,"intro.p1":`Dowodzisz siewnikiem „Jaskółka”: czterdziestu śpiących, stary inżynier i SI o imieniu ORA. Trzeba znaleźć żywą gwiazdę i zbudować przy niej wrota do domu.`,"intro.start":`Leć`,"card.pick":`Wybierz przedmiot lub recepturę — zobaczysz, czym jest i do czego służy.`,"card.byHand":`Ręcznie`,"card.cat.ore":`Kamień`,"card.cat.intermediate":`Materiał`,"card.cat.building":`Budynek`,"card.cat.ship":`Moduł statku`,"card.have":`masz: {n}`,"card.made":`Jak zdobyć`,"card.used":`Potrzebne do`,"lock.lab":`Odblokuje Centrum: {tech}`,"toast.locked":`{item}: zablokowane — odblokuje Centrum: {tech}`,"inv.items":`Przedmioty`,"inv.craftHint":`kliknij — opis i wytwarzanie; prawy klik — wytwórz jedną sztukę`,"lab.title":`Centrum Badawcze`,"lab.tier":`stopień {n}`,"lab.lore":`Centra buduje się według planu z archiwum statku. Każde odczytuje spektra w świetle — światłowód do dowolnego boku. Kolejka i postęp są wspólne, ale każde Centrum ma własną naukę i odczytuje własną jednostkę, więc więcej Centrów to szybsze badania. Każda odczytana klasa spektralna odblokowuje technologie i zapala pierścień swojego koloru.`,"lab.spectra":`Nauka we wszystkich Centrach`,"lab.delivered":`łącznie {n}`,"lab.putSpectra":`Oddaj naukę Centrom (najbliższe najpierw)`,"lab.current":`Teraz w badaniu`,"lab.idle":`Wybierz technologię: „Na czoło” lub „Do kolejki” na liście poniżej albo w drzewie. Centrum samo niczego nie zaczyna — nauka czeka w slotach.`,"lab.tree":`Drzewo technologii`,"lab.request":`{spectra} {have}/{need} → {tech}`,"tech.queued":`w kolejce · {n}`,"tech.state.done":`zbadane`,"tech.state.current":`w badaniu`,"tech.state.queued":`w kolejce`,"tech.state.available":`dostępne`,"tech.state.locked":`zablokowane`,"tech.cost":`Koszt: jednostki × po jednej sztuce z każdego etapu`,"tech.requires":`Najpierw: {list}`,"tech.enqueue":`Do kolejki`,"tech.dequeue":`Usuń`,"tech.first":`Na czoło`,"fluid.amount":`{name}: {n} j.`,"machine.fluid":`{name}: {n} j.`,"machine.net":`{name} w sieci: {n} / {cap} j.`,"machine.boost":`rezonans +{n}%`,"machine.resonance":`Sieć rezonansu: pokryto {n}% zapotrzebowania`,"etude.title":`Eksperymenty`,"etude.lore":`Krótkie łamigłówki na znanym świetle: ograniczony zestaw części, jedno zadanie. Im szybciej, taniej i zwięźlej, tym lepiej.`,"etude.parts":`{n, plural, one {# część} few {# części} many {# części} other {# części}}`,"etude.area":`obszar {n}`,"etude.best":`Najlepszy wynik:`,"etude.start":`Uruchom eksperyment`,"etude.solved":`Eksperyment udany!`,"etude.goal":`Wytwórz maszynami: {item} × {n}`,"etude.again":`Jeszcze raz`,"etude.pure_tone.name":`Czysty kolor`,"etude.pure_tone.task":`Trzy źródła bieli, pryzmat i stół: daj stołowi sam szkarłat i wykonaj {n} rubinowych soczewek. Wynik — części, powierzchnia, czas. Wiązki pomogą oszczędzić światłowody.`,"lab.waiting":`Jednostka to po jednej sztuce z każdego stopnia. Czekamy na: {spectra}. Nadmiar spektrów innych klas nie przyspieszy badań.`,"hint.prism.3":`Maszyny na wyjściach nie przyjmują teraz światła: ich produkty nie mają dokąd trafić albo brakuje im innego wejścia. Daj im pracę — pryzmat sam wznowi działanie.`,"hint.drill.6":`Wyjście harpuna nigdzie nie prowadzi — obróć go (R) w stronę grawitaśmy, maszyny lub magazynu.`,"hint.crafter.7":`Za mało światła: sieć dzieli je między wszystkich odbiorców (żagle też piją). Dodaj łuki na powłoce, drugi odbiornik albo wydziel osobną sieć.`,"menu.title":`Menu`,"menu.tagline":`Fabryka wokół żywej gwiazdy`,"menu.continue":`Kontynuuj`,"menu.newWorld":`Nowy świat`,"menu.back":`← Wstecz`,"menu.difficulty":`Trudność`,"menu.seed":`Ziarno świata`,"menu.randomSeed":`Losowe ziarno`,"menu.start":`Start`,"difficulty.calm":`Kontemplacja`,"difficulty.calm.desc":`Bez Roju. Tylko światło, pasy i budowa.`,"difficulty.standard":`Standard`,"difficulty.standard.desc":`Gniazda budzą się od łuny i wysyłają fale — zawsze z ostrzeżeniem. Wieżyczki, bariery i naprawy ratują bazę.`,"difficulty.abyss":`Otchłań`,"difficulty.abyss.desc":`Gniazda bliżej, fale częstsze i groźniejsze, planety pod ulami. Dla weteranów.`,"settings.title":`Ustawienia`,"settings.tab.general":`Ogólne`,"settings.tab.graphics":`Grafika`,"settings.tab.sound":`Dźwięk`,"settings.tab.controls":`Sterowanie`,"settings.tab.access":`Dostępność`,"settings.lang":`Język`,"settings.quality":`Jakość`,"settings.quality.low":`Niska`,"settings.quality.medium":`Średnia`,"settings.quality.high":`Wysoka`,"settings.quality.ultra":`Ultra`,"settings.quality.hint":`{touch, select, yes {Niska wyłącza poświatę (bloom): dla słabszych telefonów i długiej gry na baterii. Ultra renderuje w pełnej ostrości ekranu i mocniej grzeje telefon.} other {Niska wyłącza poświatę (bloom): dla słabszej karty graficznej i laptopa na baterii. Ultra renderuje w pełnej ostrości ekranu i mocniej obciąża kartę graficzną.}}`,"settings.showFps":`Pokazuj FPS`,"settings.muted":`Wycisz`,"settings.master":`Głośność`,"settings.effects":`Efekty`,"settings.ambience":`Atmosfera`,"settings.voices":`Głosy postaci`,"settings.keys.hint":`Kliknij klawisz akcji, a potem naciśnij nowy. Esc anuluje.`,"settings.keys.press":`Naciśnij…`,"settings.keys.fixed":`Zawsze: WASD — lot; kółko myszy — skala; przytrzymaj i przeciągnij — rozglądanie się; Spacja — kamera na kuter; LPM — postaw lub otwórz; PPM — odłóż z ręki, z pustą ręką — wyburz; Shift+PPM / Shift+LPM — kopiuj i wklej recepturę; 1–0 — budynki paska, Shift+1–0 — jego karty; Tab — ekwipunek; Ctrl+Z / Ctrl+Y — cofnij i ponów; Ctrl+C / Ctrl+V — plan; Ctrl+S — zapis; Esc — zamknij okno lub pauza.`,"settings.keys.reset":`Reset klawiszy`,"settings.uiScale":`Skala interfejsu`,"settings.reduceFlashes":`Mniej błysków i migania`,"settings.shapesAlways":`Kształty kolorów zawsze — by odróżniać światło bez pomocy koloru (daltonizm)`,"settings.access.hint":`Każdy kolor światła ma swój kształt: szkarłatny ▲, szmaragdowy ●, lazurowy ◆, bursztynowy ■ — jak znaki na grzbietach Roju.`,"key.rotate":`Obróć`,"key.pipette":`Pipeta`,"key.remove":`Wyburz`,"key.inventory":`Ekwipunek`,"key.lab":`Badania`,"key.alt":`Tryb Alt`,"key.pause":`Pauza`,"key.sound":`Dźwięk wł./wył.`,"key.stats":`Statystyki`,"key.blueprint":`Plan`,"status.13":`Brak pary`,"status.13.hint":`Postaw drugą bramę przed sobą, w zasięgu fałdy (badania go wydłużają). Fałda ładunku potrzebuje wyjścia; fałdy światła i rury — bramy zwróconej przodem do pierwszej.`,"status.14":`Przegrzanie`,"status.14.hint":`Maszyna jest rozgrzana: zwalnia i traci światło w łunę. Odsuń ją od gwiazdy (r ≥ 7,5) albo dodaj lodowy radiator.`,"status.15":`Wygaszone`,"status.15.hint":`Maszyna stoi: ogłuszona gradem albo ma poniżej ćwierci wytrzymałości. Napraw ją — albo poczekaj, ogłuszenie minie samo.`,"status.16":`Traci światło`,"status.16.hint":`Część światła nie ma dokąd trafić i zamienia się w łunę. Wykorzystaj zbędne wyjście albo skieruj je do pochłaniacza.`,"status.17":`Brak lodu`,"status.17.hint":`Podawaj lód chwytakiem: 1 sztuka na {burn} s chłodzenia.`,"hud.glare":`Łuna {v} ph/s`,"bp.title":`Plany`,"bp.lore":`Udany blok? Nie składaj go od nowa. Obrysuj go ramką: plan trafi do ręki i do biblioteki. {touch, select, yes {„Obróć” go obraca, dotknięcie wybiera miejsce, „Postaw” buduje.} other {R obraca, kliknięcie stawia.}} Budowa idzie z ekwipunku; czego brakuje, zostaje pominięte.`,"bp.copy":`Kopiuj ramką`,"bp.copyHint":`Obrysuj budynki ramką, by je skopiować. Esc anuluje.`,"bp.library":`Biblioteka`,"bp.empty":`Na razie pusto: skopiuj fragment bazy.`,"bp.count":`{n, plural, one {# budynek} few {# budynki} many {# budynków} other {# budynku}}`,"bp.use":`Weź`,"bp.share":`Tekst`,"bp.delete":`Usuń plan`,"bp.import":`Dodaj z tekstu`,"bp.add":`Dodaj`,"bp.bad":`To nie jest tekst planu albo jest uszkodzony.`,"bp.skipped":`Pominięto nieznane budynki: {n}`,"bp.shared":`Tekst planu skopiowany — wklej go znajomym.`,"bp.name":`Plan {n}`,"bp.copied":`Skopiowano: {n, plural, one {# budynek} few {# budynki} many {# budynków} other {# budynku}}. {touch, select, yes {Dotknij miejsca i naciśnij „Postaw”.} other {R obraca, kliknięcie stawia.}}`,"bp.pasted":`Zbudowano: {n}`,"bp.pastedPart":`Zbudowano {n} z {all}: reszta jest zablokowana albo zabrakło przedmiotów.`,"etude.goal.light":`Dostarcz do odbiornika {n} ph właściwego światła`,"etude.goal.item":`Dostarcz do odbiornika: {n} szt.`,"etude.goal.fluid":`Dostarcz do odbiornika {n} j. płynnego światła`,"etude.through_wall.name":`Przez ścianę`,"etude.through_wall.task":`Szlifiernia jest zamknięta w podwójnym pierścieniu murów, a między pierścieniami jest 7 pól — żadna fałda nie sięgnie przez oba naraz. Kwarc, białe światło i odbiornik są na zewnątrz. Przeprowadź ładunek i światło dwoma skokami z lądowaniem między pierścieniami i dostarcz {n} soczewek.`,"etude.amber_duet.name":`Bursztynowa para`,"etude.amber_duet.task":`Zamień biel w bursztyn o jasności 3 (szkarłat + szmaragd, potem skupiacz) i dostarcz {n} ph do odbiornika za murem. Przez mur przejdzie tylko wiązka — przez okno.`,"etude.liquid_light.name":`Płynne światło`,"etude.liquid_light.task":`Mur z dwoma oknami: lód po prawej, światło po lewej. Niebieską wiązkę puść jednym oknem, a płyn rurą drugim (okno to jedno pole: wiązka i rura go nie dzielą). Dostarcz {n} j. płynnego światła; nadmiar szkarłatu i szmaragdu — do pochłaniaczy.`,"goal.tunnel":`Poprowadź grawitaśmę od harpunów do szlifierni`,"goal.tunnel.why":`Kuter jest jeden, a skał tysiące. Grawitaśma wozi je bez ciebie — a ty masz ważniejsze sprawy.`,"goal.tunnel.hint":`Weź grawitaśmę, {touch, select, yes {dotknij} other {kliknij}} pola przy wyjściu harpuna i przeciągnij do szlifierni. Za mało? Wytwórz więcej w oknie „Ekwipunek” z kwarcu i płyty.`,"goal.tunnel.done":`Ruszyła grawitaśma! W Przystani takich nie kładziono od jakichś czterdziestu lat — światło na kartki, nie było kiedy.`,"goal.haze":`Czyste niebo: {n, plural, one {# pryzmat} few {# pryzmaty} many {# pryzmatów} other {# pryzmatu}} w pracy, wycieki ≤ {glare} ph/s`,"goal.haze.why":`Wycieki to światło, które baza traci: wyjścia w pustkę, wiązka obok celu, przegrzanie. Gniazda widzą je i pracę warsztatów. Wycieki najłatwiej usunąć.`,"goal.haze.hint":`Wiersz „wycieki” pod plakietką „Łuna” pokaże maszyny-źródła. Zbędne wyjścia wykorzystaj albo poprowadź światłowodem do pochłaniacza.`,"goal.haze.done":`Niebo czyste — znów widać gwiazdy.`,"goal.spear":`Zbadaj technologię „Włócznia” i naładuj włócznię`,"goal.spear.why":`Meteorytów coraz więcej, a Rój już przyleciał sprawdzić bazę. Włócznia bije skupionym światłem: rozbija meteoryty i odpiera naloty.`,"goal.spear.hint":`Włócznia potrzebuje jasności ≥ {b}: za skupiaczem. {shot} ph na strzał: {slow} ph/s — strzał co {every} s, {fast} ph/s — co sekundę. Zasięg: {range} pól.`,"goal.spear.done":`Włócznia naładowana. Spójrz: w stronę bazy leci kometa — niesie mnóstwo lodu.`,"goal.cooling":`Gorący pierścień: {n, plural, one {# odbiornik} few {# odbiorniki} many {# odbiorników} other {# odbiornika}} przy gwieździe bez przegrzania`,"goal.cooling.why":`Kolonia potrzebuje więcej światła, a najwięcej go przy koronie. Ale maszyny tam się rozgrzewają: lód do radiatora — i żar jest twój.`,"goal.cooling.hint":`Zbadaj „Chłodzenie”. Gorący pierścień leży między koroną gwiazdy a powłoką I: odbiornik łapie tam więcej światła, ale się nagrzewa. Postaw lodowy radiator tuż przy odbiornikach (zasięg wokół: {n}) i włóż lód przyciskiem w oknie radiatora. Radiator zużywa lód, dopóki odbiornikowi jest gorąco: lód dają meteoryty, a na dłużej — niewód przy lodowym pasie i grawitaśma z chwytakiem do radiatora (niewód odblokujesz w drzewie): radiator spala lód przez cały czas, gdy odbiornikowi jest gorąco.`,"goal.cooling.done":`Pół życia przy gorącym żelazie — bez lodu tam nawet śruby nie dokręcisz. Pierścień ostygł!`,"goal.blueprint":`Skopiuj obszar ({n}+ budynków) i postaw kopię`,"goal.blueprint.why":`Kolonię buduje się latami — i z powtarzalnych bloków. Udanego odcinka nie trzeba składać od nowa: plan go powtórzy.`,"goal.blueprint.hint":`{touch, select, yes {„Więcej” → „Plany” → „Kopiuj ramką”: obrysuj palcem budynki, „Kopiuj”, potem dotknij miejsca i „Postaw”.} other {Przycisk „Plany” lub C — obrysuj ramką, R obraca, kliknięcie stawia.}}`,"goal.blueprint.done":`Plan w bibliotece. Archiwum „Zasiewu” urosło — pierwszy raz naszą pracą, a nie Instytutu.`,"goal.node":`Gniazdo Roju: oczyść je lub uśpij`,"goal.node.why":`Gniazdo Roju przy bazie to stałe zagrożenie. Można je oczyścić siłą — albo ukryć bazę: gniazdo, które choć raz się obudziło, po {calm} min w cieniu zaśnie na dobre. Obie drogi dają antyświatło.`,"goal.node.hint":`Postaw włócznię w odległości {range} pól od gniazda (strzałka) i daj jej skupione światło (jasność {b}+): na królową trzeba {shots} strzałów. Światło prowadź wiązką: port → lustra → port. Królowa wypuszcza wartowników na twój statek — pilnuj tarczy.`,"goal.node.done":`Gniazdo nie zagraża już bazie: oczyszczone świeci jako protogwiazda, uśpione śpi.`,"status.11":`Brak cieczy`,"status.11.hint":`Podłącz rurę z płynnym światłem albo zwolnij odpływ: receptura potrzebuje płynu na wejściu lub miejsca na niego na wyjściu.`,"status.12":`Brak sieci`,"status.12.hint":`W pobliżu nie ma pylonu ani rury — postaw bliżej.`,"machine.heat":`Żar {n}%`,"machine.heatLoss":`traci światło w łunę — odsuń od gwiazdy albo dodaj radiator`,"machine.glare":`Traci {n} ph/s → łuna`,"machine.ice":`Lód: {n}`,"cfg.title.modulator":`Rytm`,"cfg.modulator.0":`Równy ▬▬▬`,"cfg.modulator.1":`Puls ▮ ▮ ▮`,"cfg.modulator.2":`Podwójny ▮▮ ▮▮`,"cfg.modulator.3":`Nieregularny ▮ ▮▮ ▮`,"cfg.title.polarizer":`Kąt filtra`,"cfg.polarizer.1":`0°  |`,"cfg.polarizer.2":`45°  /`,"cfg.polarizer.3":`90°  —`,"status.18":`Zły rytm`,"status.18.hint":`Receptura potrzebuje światła o innym rytmie: postaw modulator i wybierz rytm w jego oknie.`,"status.19":`Zły kąt`,"status.19.hint":`Receptura potrzebuje światła pod innym kątem: postaw polaryzator i wybierz kąt w jego oknie.`,"status.20":`Zła faza`,"status.20.hint":`Receptura potrzebuje innej fazy światła: postaw przesuwnik fazy na drodze światła.`,"cfg.title.shutter":`Tryb migawki`,"cfg.shutter.0":`Otwarta przy sygnale`,"cfg.shutter.1":`NIE: zamknięta przy sygnale`,"status.21":`Brak odbiorcy`,"status.21.hint":`Brak portu odbiorczego na tym samym kanale z miejscem na ładunek w promieniu {range} pól.`,"status.22":`Brak dronów`,"status.22.hint":`Włóż drony do slotów portu (montownia robi je z soczewek, rezonatora, płyt i spektrum F).`,"cfg.title.drone_port":`Rola portu`,"cfg.role.0":`Budowa`,"cfg.role.1":`Nadawca`,"cfg.role.2":`Odbiorca`,"cfg.channel":`Kanał {n}`,"drone.title":`Kanał`,"drone.home":`Drony w domu: {n}`,"drone.trips":`Kursy łącznie: {n}`,"drone.put":`Włóż drony ({n})`,"bp.pastedGhost":`Zbudowano {n}, kolejne {g} jako widma: drony dokończą je, gdy dotrą przedmioty`,"bp.ghosted":`Widma: {g} — drony budowlane dokończą je w miarę dostaw przedmiotów`,"goal.spectrum_f":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} F do Centrum`,"goal.spectrum_f.why":`Rytm to trzecia właściwość światła po kolorze i jasności: ta sama zieleń, ale miga według wzoru. Gniazda i gwiazda migają tak samo — czas zrozumieć, co to znaczy.`,"goal.spectrum_f.hint":`Zbadaj „Rytm”, postaw modulator między pryzmatem a montownią i wybierz w jego oknie „Puls”. Spektrum F to dwie szmaragdowe soczewki w pulsującej zieleni.`,"goal.spectrum_f.done":`Czwarta klasa odczytana. Drony poniosą ładunki za ciebie.`,"goal.drone":`Wyślij pierwszy kurs drona`,"goal.drone.why":`Drony noszą ładunki i lód oraz kończą budowy, gdy masz inne zajęcia.`,"goal.drone.hint":`Zbadaj „Drony”. Dwa porty: nadawca (rola i kanał w jego oknie) ma drony w slotach i ładunek, {charge} ph światła na kurs; odbiorca używa tego samego kanału. Rola „Zbiór” przynosi odłamki lodu.`,"goal.drone.done":`Dron leci! Teraz plan może budować się sam.`,"goal.ghost":`Niech drony dokończą {n, plural, one {# budynek} few {# budynki} many {# budynków} other {# budynku}} z widm`,"goal.ghost.why":`Plan, który buduje się sam: drony dokańczają widma, gdy lecisz do pasów i gniazd.`,"goal.ghost.hint":`Port budowlany z dronami i przedmiotami budynków w slotach. {touch, select, yes {Wklej plan: czego zabraknie, stanie jako widmo — drony dokończą, gdy dowieziesz przedmioty.} other {Ctrl+Shift+V wkleja plan jako widma; brak przedmiotów przy zwykłym wklejeniu też zostawia widma.}}`,"goal.ghost.done":`Budowa idzie bez ciebie. Wklejaj plany zawczasu.`,"goal.spectrum_a":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} A do Centrum`,"goal.spectrum_a.why":`Polaryzacja to kierunek drgań światła. Wzory Roju są obrócone różnie, jakby były do kogoś skierowane. Polaryzator ustawia kąt, ale zabiera połowę światła.`,"goal.spectrum_a.hint":`Zbadaj „Polaryzacja”. A to turkusowe światło pod kątem 45°: mieszalnik, polaryzator ustawiony na 45°, montownia.`,"goal.spectrum_a.done":`Pięć klas. Światło zna już rytm i kąt — pora nauczyć je liczyć.`,"goal.logic":`Zbuduj układ: migawka i lampa, {n, plural, one {# przełączenie} few {# przełączenia} many {# przełączeń} other {# przełączenia}} migawki`,"goal.logic.why":`Światło to jedynka, ciemność to zero: fabryka potrafi myśleć. A Sonia jest pewna, że lampą można też odpowiedzieć.`,"goal.logic.hint":`Zbadaj „Logika optyczna”. Migawka przepuszcza światło, dopóki na bocznym wejściu świeci sygnał; lampa pokazuje wynik. Zrób NIE ze sprzężeniem zwrotnym, a dostaniesz migacz.`,"goal.logic.done":`Światło liczy. Zamknięta migawka to idealny zawór bez łuny.`,"goal.spectrum_b":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} B do Centrum`,"goal.spectrum_b.why":`Faza to piąta właściwość światła, przesunięcie fali. Dwie fale przesunięte o π wygaszają się nawzajem — a u Roju to przesunięcie znaczy „tak”.`,"goal.spectrum_b.hint":`Zbadaj „Faza” — wymaga spektrów G, F i A: F i A dzielą szmaragdowe soczewki, drugi szmaragdowy stół przyspieszy pracę. Spektrum B to niebieskie światło w fazie π: przesuwnik fazy na drodze światła. Interferometr pokaże wygaszanie.`,"goal.spectrum_b.done":`Sześć klas odczytanych — została ostatnia, O.`,"achv.title":`Osiągnięcia`,"achv.count":`{n} z {all}`,"achv.hidden":`Ukryte osiągnięcie — odkryj je.`,"achv.at":`w {min}. minucie gry`,"achv.toast":`Osiągnięcie: {name}`,"achv.group.story":`Fabuła`,"achv.group.mastery":`Mistrzostwo`,"achv.group.challenge":`Wyzwania`,"achv.first_light.name":`Pierwsze światło`,"achv.first_light.desc":`Światło dotarło do maszyny.`,"achv.first_spectrum.name":`Pierwsze spektrum`,"achv.first_spectrum.desc":`Centrum odczytało spektrum M.`,"achv.liquid_dawn.name":`Światło w rurze`,"achv.liquid_dawn.desc":`Płynne światło popłynęło rurami.`,"achv.dark_out.name":`Gniazdo upadło`,"achv.dark_out.desc":`Królowa nie żyje — w miejscu gniazda zapłonęła protogwiazda.`,"achv.first_pulse.name":`Puls`,"achv.first_pulse.desc":`Rytm to trzecia właściwość światła, po kolorze i jasności.`,"achv.sky_carriers.name":`Podniebni kurierzy`,"achv.sky_carriers.desc":`Pierwszy kurs drona.`,"achv.logic_gate.name":`Światło liczy`,"achv.logic_gate.desc":`Działa pierwszy układ z migawką.`,"achv.awakening.name":`Łączność`,"achv.awakening.desc":`Dalekie włókno gotowe — Przystań słyszy „Jaskółkę”.`,"achv.red_horizon.name":`Czerwony horyzont`,"achv.red_horizon.desc":`Placówka przy protogwieździe w Szkarłatnej Grani.`,"achv.spm_60.name":`Spektrum na sekundę`,"achv.spm_60.desc":`Spektra na minutę: {n}.`,"achv.spm_300.name":`Spektrograf`,"achv.spm_300.desc":`Spektra na minutę: {n}.`,"achv.spm_1000.name":`Obserwatorium`,"achv.spm_1000.desc":`Spektra na minutę: {n, number}.`,"achv.machines_100.name":`Setka maszyn`,"achv.machines_100.desc":`Budynki w świecie: {n}.`,"achv.machines_500.name":`Całe miasto`,"achv.machines_500.desc":`Budynki w świecie: {n}.`,"achv.clean_100.name":`Czyste niebo`,"achv.clean_100.desc":`{min} min bez łuny przy stu pracujących maszynach (grawitaśmy i światłowody się nie liczą).`,"achv.clean_1000.name":`Baza bez łuny`,"achv.clean_1000.desc":`{min} min czystego nieba przy tysiącu pracujących maszyn.`,"achv.tunnel_trio.name":`Miasto fałd`,"achv.tunnel_trio.desc":`Ładunek, światło i płyn płyną przez fałdy jednocześnie.`,"achv.blueprint_50.name":`Kreślarz`,"achv.blueprint_50.desc":`Wklejono plan — budynki: {n}.`,"achv.swarm.name":`Stado`,"achv.swarm.desc":`Drony w powietrzu naraz: {n}.`,"achv.sings.name":`Migające liczydło`,"achv.sings.desc":`Przełączenia migawek: {n, number}.`,"achv.prima.name":`Prima`,"achv.prima.desc":`Dalekie włókno w {h} godz. {m} min gry.`,"achv.no_hands.name":`Bez rąk`,"achv.no_hands.desc":`Dalekie włókno przy nie więcej niż {n} przedmiotach złożonych ręcznie.`,"achv.silent_hall.name":`Równe światło`,"achv.silent_hall.desc":`Godzina bez ani jednej maszyny migającej „Brak światła”, gdy pracuje co najmniej dziesięć.`,"achv.abyss_awakening.name":`Otchłań`,"achv.abyss_awakening.desc":`Dalekie włókno w świecie „Otchłań”.`,"achv.clean_awakening.name":`Czysta droga`,"achv.clean_awakening.desc":`Dalekie włókno bez ani jednej łuny na niebie powyżej {glare} ph/s.`,"etude.locked":`Otworzy się po celu „{goal}”`,"tech.learned":`Zbadano: {name}`,"tech.learned.opens":`Zbadano: {name} · odblokowano: {list}`,"menu.system":`Układ gwiezdny`,"system.cradle":`Kolebka`,"system.cradle.desc":`Żółta gwiazda klasy G i sześć pasów. Tu wszystko się zaczyna.`,"system.red_ridge":`Szkarłatna Grań`,"system.red_ridge.desc":`Czerwony karzeł: o połowę mniej światła, ciasne i bogate pasy. Białe światło tylko przy żarach-protogwiazdach w szczelinach.`,"goal.ridge_light":`Zbierz {n} ph/s światła odbiornikami promieni`,"goal.ridge_light.why":`Światło czerwonego karła jest o połowę słabsze — zbieraj bliżej.`,"goal.ridge_light.hint":`Bez białego światła szlifiernie (soczewki i płyty) nie działają, a czerwony karzeł daje tylko bursztyn: biel jest przy protogwiazdach, każda ma własną małą sferę. Łuki na sferze karła dają bursztyn; w zestawie jest 48 soczewek i dwa stoły — wystarczy na cel lazurowy i 4 łuki, potem soczewki z własnej szlifierni.`,"goal.ridge_light.done":`Światło zebrane. Ale błękitu tu nie ma.`,"goal.ridge_blue":`Wytwórz maszynami {n, plural, one {# lazurową soczewkę} few {# lazurowe soczewki} many {# lazurowych soczewek} other {# lazurowej soczewki}}`,"goal.ridge_blue.why":`Niebieskie światło żyje tylko przy protogwiazdach: zbuduj placówkę.`,"goal.ridge_blue.hint":`Białe protogwiazdy leżą w szczelinach między pasami — strzałka celu prowadzi do najbliższej. Każda ma własną małą powłokę na {slots} łuków: postaw łuki i odbiornik w pobliżu — złapie biel. Przy protogwieździe jest gorąco: tarcza kutra się tam nie regeneruje — stawiaj łuki od zewnętrznej krawędzi i nie zwlekaj.`,"goal.ridge_blue.done":`Placówka działa: niebieskie światło dotarło do fabryki.`,"settings.haptics":`Wibracje`,"toast.autoQuality":`Mało klatek: grafika obniżona do „{q}” (mniej poświaty).`,"touch.hint":`Przeciągnij — przesuwanie, uszczypnij — powiększenie. Dotknięcie stawia widmo, „Postaw” potwierdza. Przytrzymaj maszynę — okno, dotknięcie dwoma palcami — anuluj.`,"forge.title":`Kuźnia Gwiazdy`,"forge.stars":`rozpalone gwiazdy: {n}`,"forge.lore":`Pradawna kuźnia przy czarnej dziurze. Przyjmuje wszystkie siedem spektrów, antyświatło i trzy znaki układów — i utrzymuje pełne spektrum, aż gwiazda się zapali.`,"forge.chord":`Pełne spektrum: siedem klas i antyświatło`,"forge.relics":`Relikwie układów`,"forge.relic.in":`złożona`,"forge.relic.have":`w plecaku — złóż ją`,"forge.relic.none":`brak — zdobądź ją, kończąc cel układu`,"forge.put":`Złóż z plecaka`,"forge.progress":`Utrzymanie spektrum`,"forge.status.0":`Kuźnia czeka na pełne spektrum.`,"forge.status.1":`Spektrum trzyma: każdy impuls pobiera po jednym spektrum każdej klasy i antyświatło.`,"forge.status.2":`Gwiazda czeka. Rozpal ją!`,"forge.status.noRelics":`Potrzebne relikwie: {have}/{need}. Zdobywa się je za cele układów: Grani, Szafiru, Bliźniąt, Welonu, Pulsara.`,"forge.status.starved":`Spektrum zerwane: brakuje „{item}”. Postęp spada.`,"forge.rule":`Jeden impuls co {sec} s. Pominięty impuls odbiera {drain} postępu, ale nigdy go nie zeruje.`,"forge.eta":`Do utrzymania zostało ≈ {time}.`,"forge.min":`{n} min`,"forge.sec":`{n} s`,"forge.ignite":`Rozpal gwiazdę`,"finale.nameTitle":`Imię gwiazdy`,"finale.nameLead":`Rozbłysła. Jak ją nazwiesz?`,"finale.nameOk":`Nazwij`,"finale.creditsTitle":`Napisy końcowe`,"finale.credits.0":`Gwiazdy gasły. Wystarczyła prośba — i jedna rozbłysła.`,"finale.credits.1":`Każdy łuk twojej sfery to światło, o które poproszono.`,"finale.credits.2":`Białe światło to siedem kolorów widzianych naraz.`,"finale.credits.3":`Kuźnia znów naładowana: następna gwiazda poprosi o więcej.`,"finale.credits.4":`Twoja konstelacja czeka w menu głównym.`,"finale.credits.5":`Fabryka wokół żywej gwiazdy.`,"finale.card.time":`godz. gry`,"finale.card.npm":`szczyt spektrów na minutę`,"finale.card.machines":`maszyny`,"finale.card.stars":`gwiazdy w konstelacji`,"finale.continue":`Kontynuuj`,"finale.toast.lit":`Gwiazda „{name}” rozpalona!`,"menu.stars":`Konstelacja ({n})`,"menu.starsTitle":`Twoja konstelacja`,"menu.starLine":`{h} h · szczyt {npm} spektrów/min · maszyny: {machines}`,"system.sapphire":`Szafir`,"system.sapphire.desc":`Błękitny olbrzym: wielokrotnie więcej światła, ale i żaru — maszyny i tarcza się rozgrzewają. Za linią śniegu leży pas szronu helowego.`,"system.horizon":`Horyzont`,"system.horizon.desc":`Czarna dziura z dyskiem akrecyjnym — niezwykle bogaty, szybki pas w żarze. Kuźnia Gwiazdy: tu rozpala się finał.`,"goal.si":`Wytwórz maszynami {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} O`,"goal.si.why":`Klasa O — najgorętsze gwiazdy. Klucz wrót to pełne spektrum, od M do O, a bez ostatniej klasy nie da się go złożyć.`,"goal.si.hint":`Zbadaj technologię „Klasa O”. O to purpurowe światło podwójnego rytmu w fazie π (jasność {b}+) plus antyświatło: krąży małym pasem wokół oczyszczonego albo uśpionego gniazda Roju — łap je niewodem.`,"goal.si.done":`Siedem klas — pełne spektrum. Kowale wyciskali je z gwiazd siłą, a nam udało się je złożyć samodzielnie.`,"goal.sap_cool":`Zbadaj „Kriogenika” i postaw {n, plural, one {# krioradiator} few {# krioradiatory} many {# krioradiatorów} other {# krioradiatora}}`,"goal.sap_cool.why":`Gwiazda-olbrzym rozgrzewa maszyny przy koronie: bez chłodzenia światło przepada w łunie.`,"goal.sap_cool.hint":`Otwórz Centrum i ustaw w kolejce technologię „Kriogenika” (spektra są w zestawie startowym). Krioradiator chłodzi maszyny przy olbrzymie.`,"goal.sap_cool.done":`Maszyny ostygły: można budować bliżej gwiazdy.`,"goal.sap_frost":`Zbierz niewodem szron helowy: {n}`,"goal.sap_frost.why":`Szron to paliwo krioradiatora: bez niego żar wróci.`,"goal.sap_frost.hint":`Pas szronu leży za linią śniegu (strzałka). Niewód przy pasie — grawitaśma — magazyn; radiator przyjmuje szron z chwytaka.`,"goal.sap_frost.done":`Szron płynie sam.`,"goal.sap_la":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} B do Centrum`,"goal.sap_la.why":`W świetle olbrzyma spektra powstają szybciej — ale i żaru jest więcej.`,"goal.sap_la.hint":`Spektrum B to niebieskie światło w fazie π. Użyj wszystkiego, co umiesz: światło jest tu hojne.`,"goal.sap_la.done":`Olbrzym hojnie daje światło.`,"goal.sap_relic":`Osiągnij {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} na minutę`,"goal.sap_relic.why":`To znak Szafiru: Relikwia Szronu przyda się przy czarnej dziurze.`,"goal.sap_relic.hint":`Wszystkie spektra razem, co najmniej {n} na minutę — szczyt liczy się raz na minutę. Dołącz drony i zewnętrzne powłoki.`,"goal.sap_relic.done":`Relikwia Szronu zdobyta i zapisana w profilu.`,"goal.hz_light":`Zbierz {n} ph/s światła odbiornikami promieni`,"goal.hz_light.why":`Pełne spektrum siedmiu klas wymaga ≈ 1000 ph/s światła.`,"goal.hz_light.hint":`Dysk czarnej dziury jest bardzo jasny: sfera wokół niego daje mnóstwo światła. Stawiaj łuki i odbiorniki; maszyny przy koronie się grzeją — radiatory są konieczne.`,"goal.hz_light.done":`Światło zebrane. Teraz Rój.`,"goal.hz_node":`Gniazdo Roju: oczyść je albo uśpij`,"goal.hz_node.why":`Gniazdo — oczyszczone albo uśpione — oddaje pas antyświatła: potrzebny i do spektrum O, i samej Kuźni.`,"goal.hz_node.hint":`Gniazdo jest za bazą (strzałka). Włócznia sięga na {range} pól, potrzebuje światła o jasności {b}+. Tu królowa jest twardsza, a fale zacieklejsze; można też przestać je oślepiać — uśpione gniazdo daje ten sam pas.`,"goal.hz_node.done":`Gniazdo już nie zagraża — krąży wokół niego pas antyświatła.`,"goal.hz_si":`Zbadaj „Klasa O” i wytwórz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} O`,"goal.hz_si.why":`Siódma klasa domyka pełne spektrum.`,"goal.hz_si.hint":`Spektrum O — purpura podwójnego rytmu w fazie π, jasność {b}+, plus antyświatło z pasa gniazda — oczyszczonego albo uśpionego (niewód).`,"goal.hz_si.done":`Siedem klas gwiazd — pełne spektrum.`,"goal.hz_antilight":`Zbierz niewodami antyświatło: {n}`,"goal.hz_antilight.why":`{forge} pójdzie na spektra O, a {forge} — do Kuźni.`,"goal.hz_antilight.hint":`Pas antyświatła krąży wokół zgasłego albo uśpionego gniazda: dwa niewody wystarczą. Nie zapominaj o obronie.`,"goal.hz_antilight.done":`Antyświatło zdobyte. Została Kuźnia.`,"goal.hz_ignite":`Rozpal gwiazdę w Kuźni`,"goal.hz_ignite.why":`To po to było wszystko: pełne spektrum — białe światło — zapala gwiazdę.`,"goal.hz_ignite.hint":`Włóż trzy relikwie, doprowadź grawitaśmy z siedmioma spektrami i antyświatłem (po {rate, number} każdego na sekundę) i utrzymaj pełne spektrum przez {hold} s.`,"goal.hz_ignite.done":`Gwiazda rozpalona!`,"relic.earned":`Zdobyto relikwię: „{name}”. Jest zapisana w profilu; dowolne trzy otwierają Horyzont.`,"achv.class_o_made.name":`Błękitny olbrzym`,"achv.class_o_made.desc":`Spektrum O wytworzone maszynami: pełne spektrum zebrane.`,"achv.cold_giant.name":`Ostudzić olbrzyma`,"achv.cold_giant.desc":`Krioradiatory Szafiru działają.`,"achv.frost_bearer.name":`Szron w dłoni`,"achv.frost_bearer.desc":`Relikwia Szronu zdobyta w Szafirze.`,"achv.star_lit.name":`Rozpalić gwiazdę`,"achv.star_lit.desc":`Kuźnia Gwiazdy oddała pełne spektrum: na mapie zapłonęła nowa gwiazda.`,"hint.noLight.first":`Światło nie dociera do maszyny: postaw łuk na powłoce przy gwieździe, odbiornik obok i poprowadź światłowód. Plakietka nad maszyną powie, czego brakuje.`,"toast.autoQuality.undo":`Cofnij`,"forge.need":`Potrzeba {rate} każdego spektrum i antyświatła na sekundę.`,"forge.relicsHint":`Kuźnia stoi zimna bez trzech relikwii: zdobywa się je za cele innych układów. Zostają w profilu i trafiają do plecaka nowego świata.`,"system.twins":`Bliźnięta`,"system.twins.desc":`Dwie gwiazdy, bursztynowa i niebieska, z pasami wokół obu. Białe światło miesza się z dwóch; noc przetrwać pomagają akumulatory światła.`,"system.veil":`Mgławica Welon`,"system.veil.desc":`Mgławica: żadnej skały — tylko pasy lodowej mgiełki. Kwarc i obsydian powstają z mgły.`,"system.pulsar":`Pulsar Keplera`,"system.pulsar.desc":`Gwiazda neutronowa miga: całe światło przychodzi w rytmie, spektrum F nie potrzebuje modulatora. Pasy to szczątki supernowej.`,"goal.twin_white":`Wytwórz maszynami {n, plural, one {# soczewkę} few {# soczewki} many {# soczewek} other {# soczewki}}`,"goal.twin_white.why":`Szlifiernie potrzebują białego światła, a tutejsze dwie gwiazdy mają różne kolory.`,"goal.twin_white.hint":`Sfera Bliźniąt obejmuje obie gwiazdy: za dnia jej światło jest bursztynowe, potem niebieskie — nigdy oba naraz. Niebieskie bierz prosto ze sfery, a bursztyn z akumulatora światła napełnionego za dnia; oba do mieszalnika, biel do szlifierni.`,"goal.twin_white.done":`Dwie gwiazdy zlały się w białe światło.`,"goal.twin_blue":`Wytwórz maszynami {n, plural, one {# lazurową soczewkę} few {# lazurowe soczewki} many {# lazurowych soczewek} other {# lazurowej soczewki}}`,"goal.twin_blue.why":`Niebieskie światło żyje tylko przy drugiej gwieździe: stół optyczny musi stać blisko niej.`,"goal.twin_blue.hint":`Niebieska gwiazda jest 70 pól od bursztynowej. Zbuduj przy niej placówkę albo poprowadź światłowód: jasność spada z odległością.`,"goal.twin_blue.done":`Błękitne światło dotarło do fabryki.`,"goal.twin_relic":`Utrzymaj {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} na minutę także nocą`,"goal.twin_relic.why":`To znak Bliźniąt: relikwia przyda się przy czarnej dziurze.`,"goal.twin_relic.hint":`Wszystkie spektra razem, nie mniej niż {n} na minutę — także pod koniec nocy, gdy gwiazd nie ma. Światło sfery zmienia kolor za gwiazdami, noc podtrzymują akumulatory światła.`,"goal.twin_relic.done":`Relikwia Bliźniąt zdobyta i zapisana w profilu.`,"goal.veil_quartz":`Wytwórz maszynami kwarc z mgły: {n}`,"goal.veil_quartz.why":`Nie ma tu skały — bez kwarcu nie będzie soczewek ani spektrów.`,"goal.veil_quartz.hint":`Lód (strzałka) i niebieskie światło w kondensatorze dają płynne światło; drugi kondensator z recepturą „Kwarc z mgły” zamienia lód i płynne światło w kwarc.`,"goal.veil_quartz.done":`Kwarc rodzi się ze światła.`,"goal.veil_lens":`Wytwórz maszynami {n, plural, one {# soczewkę} few {# soczewki} many {# soczewek} other {# soczewki}}`,"goal.veil_lens.why":`Soczewki to podstawa każdego spektrum; teraz wystarczy ich na całą fabrykę.`,"goal.veil_lens.hint":`Stawiaj kondensatory rzędami: grawitaśmy i chwytaki działają tak samo jak przy skale.`,"goal.veil_lens.done":`Linie biegną bez stałego gruntu.`,"goal.veil_relic":`Dostarcz do Centrum: spektrum M × {n} i spektrum K × {n}`,"goal.veil_relic.why":`To znak Welonu: relikwia przyda się przy czarnej dziurze.`,"goal.veil_relic.hint":`Spektra powstają jak wszędzie, tylko surowiec pochodzi z mgły: niewód przy lodowej mgiełce, kondensator, mgła w kwarc. Światła jest tu mniej.`,"goal.veil_relic.done":`Relikwia Welonu zdobyta i zapisana w profilu.`,"goal.pulse_light":`Zbierz {n} ph/s światła odbiornikami promieni`,"goal.pulse_light.why":`Gwiazda jest jasna, ale jej światło przychodzi pulsami; trzeba jeszcze znaleźć mu zastosowanie.`,"goal.pulse_light.hint":`Puls widać w światłowodach jako miganie. Szlifierniom i spektrom M/K/G to nie przeszkadza: przyjmują każdy rytm.`,"goal.pulse_light.done":`Pulsar zasila fabrykę.`,"goal.pulse_fa":`Dostarcz {n, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} F do Centrum`,"goal.pulse_fa.why":`Spektrum F to rytm, a tu przychodzi sam: modulator jest zbędny.`,"goal.pulse_fa.hint":`Zielone światło z pulsem: zielone wyjście pryzmatu zachowuje rytm gwiazdy. Montownia F przyjmuje je takie, jakie jest.`,"goal.pulse_fa.done":`Rytm prosto z pudełka — działa.`,"goal.pulse_relic":`Dostarcz do Centrum po {n} spektrów M, K i F`,"goal.pulse_relic.why":`To znak Pulsara: relikwia przyda się przy czarnej dziurze.`,"goal.pulse_relic.hint":`Trzy spektra w tempie pulsara. Jeśli światło mętnieje, mieszaj tylko wiązki o jednym rytmie.`,"goal.pulse_relic.done":`Relikwia Pulsara zdobyta i zapisana w profilu.`,"stick.label":`Drążek lotu Strażnika`,"keeper.recenter":`Do Strażnika`,"toast.far":`Poza zasięgiem Strażnika — podlatuję bliżej`,"toast.farMining":`Wydobycie wstrzymane: Strażnik jest za daleko`,"guide.title":`Samouczek`,"guide.skip":`Opuść samouczek`,"guide.skipStep":`Pomiń ten krok`,"guide.fly":`Leć do znacznika przy niebieskich skałach: WASD. Kółko myszy — skala, Spacja — kamera na kuter. Strzałka przy krawędzi pokazuje drogę.`,"guide.fly.touch":`Pchnij gałkę w stronę znacznika przy niebieskich skałach. Strzałka przy krawędzi ekranu wskazuje drogę.`,"guide.fly.why":`Nie podlatuj blisko gwiazdy: tarcza się przegrzeje. Potrzebuję cię w pełni sił, Strażniku.`,"guide.mine":`Kliknij niebieską skałę — wiązka kutra będzie sama wydobywać kwarc. Potrzeba {n}.`,"guide.mine.touch":`Dotknij niebieskiej skały — wiązka kutra będzie sama wydobywać kwarc. Potrzeba {n}.`,"guide.mine.why":`Ręcznie to powoli, wiem. Pierwsze kamienie zawsze idą ręcznie, dowódco. Maszyny przyjdą potem.`,"guide.lay-tunnel.touch":`Dotknij {o, select, 1 {górnego} 2 {prawego} 3 {dolnego} other {lewego}} końca ramki i, nie odrywając palca, przeciągnij {o, select, 1 {w dół} 2 {w lewo} 3 {w górę} other {w prawo}} do końca.`,"guide.place-grinder":`Postaw szlifiernię w ramce obok odbiornika.`,"guide.place-grinder.repick":`Weź szlifiernię z paska budynków: szlifuje kwarc na soczewki.`,"guide.recipe":`Maszyna bez zadania to tylko żelastwo. Naciśnij szlifiernię i wybierz recepturę „Soczewka”.`,"guide.recipe.open":`Naciśnij szlifiernię, by otworzyć jej okno.`,"guide.recipe.why":`Receptura to zlecenie pracy. Maszyny są tu pojętne — nie to co nawigacja.`,"guide.place-grabIn":`Postaw chwytak w ramce między grawitaśmą a szlifiernią.`,"guide.place-grabIn.rotate":`Obróć chwytak strzałką {o, select, 1 {w lewo} 2 {w górę} 3 {w prawo} other {w dół}} — do szlifierni: „Obróć” lub R — jeszcze {n, plural, one {# raz} few {# razy} many {# razy} other {# raza}}.`,"guide.place-grabIn.repick":`Weź chwytak z paska budynków: bierze z tyłu i kładzie z przodu, zgodnie ze strzałką.`,"guide.place-grabOut":`Drugi chwytak postaw w ramce {o, select, 1 {pod szlifiernią} 2 {na lewo od szlifierni} 3 {nad szlifiernią} other {na prawo od szlifierni}}: będzie wynosić soczewki.`,"guide.place-grabOut.rotate":`Obróć chwytak strzałką {o, select, 1 {w dół} 2 {w lewo} 3 {w górę} other {w prawo}} — od szlifierni: „Obróć” lub R — jeszcze {n, plural, one {# raz} few {# razy} many {# razy} other {# raza}}.`,"guide.place-grabOut.repick":`Weź kolejny chwytak.`,"guide.place-storage":`Magazyn — skrzynię na soczewki — postaw w ramce przed strzałką drugiego chwytaka.`,"guide.place-storage.repick":`Weź magazyn — skrzynię na gotowe soczewki.`,"guide.lay-lights":`Poprowadź żyłę: światłowód wzdłuż ramki od odbiornika do szlifierni.`,"guide.lay-lights.repick":`Weź światłowód: niesie światło od odbiornika do maszyny.`,"guide.first-lens":`Patrz: kwarc leci, szlifiernia pracuje. Czekamy na pierwszą soczewkę w skrzyni.`,"guide.first-lens.why":`Gdy maszyna stanie, nad nią pojawi się znaczek — {touch, select, yes {stuknij} other {kliknij}} maszynę, a okno powie, co przeszkadza.`,"guide.done":`Samouczek ukończony! Dalej prowadzi karta celu u góry.`,"guide.recipe.look":`Naciśnij „Patrz” (Esc): wtedy {touch, select, yes {stuknięcie} other {kliknięcie}} otwiera maszynę zamiast budować.`,"landmark.lab":`Wrak modułu`,"landmark.lab.sub":`„Jaskółka” · kriokomora i archiwum`,"landmark.star":`Gwiazda Kolebki`,"landmark.star.sub":`źródło światła`,"intro.t0":`Światło gaśnie`,"intro.p0":`Gwiazdy gasną jedna po drugiej. Razem z nimi gasną wrota, które łączyły ludzi.`,"intro.t1":`Jesteś Strażnikiem`,"intro.next":`Dalej`,"intro.skip":`Pomiń`,"compass.label":`Cel poza ekranem, {n, plural, one {# pole} few {# pola} many {# pól} other {# pola}}`,"compass.cells":`{n, plural, one {# pole} few {# pola} many {# pól} other {# pola}}`,"menu.play":`Graj`,"menu.replayGuide":`Powtórz samouczek`,"lab.noteHow":`{touch, select, yes {stuknij} other {kliknij}} — pokażemy, jak to zdobyć`,"guide.place-grinder.why":`Szlifiernia szlifuje z kwarcu soczewki. Soczewek potrzebuje wszystko, co zbudujemy.`,"guide.place-grabIn.why":`Chwytak bierze z grawitaśmy i podaje do szlifierni. Ręka, tylko bez łokcia.`,"tools.more":`Więcej`,"tools.hideHud":`Ukryj interfejs`,"hud.show":`Pokaż interfejs`,"place.title":`Potwierdzenie stawiania`,"place.cancel":`Anuluj`,"place.build":`Postaw`,"place.remove":`Wyburz`,"place.copy":`Kopiuj`,"stick.hide":`Ukryj drążek`,"stick.show":`Przywróć drążek Strażnika`,"stick.flip":`Drążek na drugą stronę`,"settings.stickSide":`Drążek Strażnika`,"settings.stickSide.left":`Po lewej`,"settings.stickSide.right":`Po prawej`,"settings.stickSide.off":`Ukryty`,"settings.confirmPlace":`Stawianie dwoma dotknięciami`,"settings.confirmPlace.hint":`Dotknięcie stawia widmo, a przycisk „Postaw” je potwierdza — palec nie zasłania miejsca. Wyłącz, by budować od razu.`,"settings.bigButtons":`Duże przyciski`,"shell.worlds":`Światy`,"shell.stars":`Konstelacja`,"shell.about":`O grze`,"shell.exit":`Wyjdź`,"shell.exit.title":`Wyjść z gry?`,"shell.exit.text":`Świat jest zapisany — wrócisz do miejsca, w którym przerwano grę.`,"shell.cancel":`Anuluj`,"shell.playWorld":`Graj: {name}`,"shell.rename":`Zmień nazwę`,"shell.delete":`Usuń`,"shell.delete.title":`Usunąć świat?`,"shell.delete.text":`„{name}” i wszystkie jego zapisy znikną na zawsze.`,"shell.deleted":`Świat usunięty`,"shell.timeH":`{h} godz. {m} min`,"shell.timeM":`{m} min`,"shell.loading":`Świat się budzi…`,"shell.loadFailed":`Nie udało się otworzyć zapisu — świat rozpoczęto od nowa`,"shell.create.title":`Nowy świat`,"shell.create.name":`Nazwa świata`,"shell.create.randomName":`Losowa nazwa`,"shell.create.advanced":`Zaawansowane`,"shell.create.tutorial":`Samouczek krok po kroku`,"shell.create.go":`Utwórz świat`,"pause.title":`Menu`,"pause.resume":`Wznów`,"pause.save":`Zapisz`,"pause.toTitle":`Do menu głównego`,"world.name":`{a} {b}`,"world.a.0":`Dolina`,"world.a.1":`Brzeg`,"world.a.2":`Kres`,"world.a.3":`Przystań`,"world.a.4":`Siedziba`,"world.a.5":`Kopuła`,"world.a.6":`Pas`,"world.a.7":`Ogród`,"world.a.8":`Próg`,"world.a.9":`Zatoka`,"world.b.0":`Świtu`,"world.b.1":`Blasku`,"world.b.2":`Odblasków`,"world.b.3":`Zorzy`,"world.b.4":`Południa`,"world.b.5":`Iskier`,"world.b.6":`Pryzmatów`,"world.b.7":`Jasności`,"world.b.8":`Spektrum`,"world.b.9":`Refleksów`,"tip.0":`Pryzmat rozszczepia białe światło na kolory — z każdego koloru powstaje własne spektrum.`,"tip.1":`Kamera uciekła? Przycisk z celownikiem lub Spacja przywróci ją do Strażnika.`,"tip.2":`Centrum prosi o spektra: każda nowa klasa otwiera kolejny stopień technologii.`,"tip.3":`Rój nie przychodzi znienacka: plakietka z licznikiem i kręgi wokół gniazda pojawiają się zawczasu.`,"tip.4":`Sfera Dysona rośnie warstwami: zamknij powłokę, a każdy łuk da +{closed}%; potrzeba więcej światła — buduj zewnętrzną powłokę wyższego stopnia.`,"tip.5":`Pasy się obracają, wewnętrzne szybciej. Harpun w jednym miejscu wyczerpuje cały pas — patrz, jak rzednie.`,"tip.6":`Plany kopiują całe obszary — zbuduj raz, stawiaj wszędzie.`,"tip.7":`Tryb Alt pokazuje zawartość maszyn wprost na polu.`,"tip.8":`Nie wiesz, co dalej? Cel u góry podpowie następny krok, a strzałka — dokąd lecieć.`,"tip.9":`Eksperymenty to krótkie łamigłówki ze światłem — błędy nic tam nie kosztują.`,"tip.10":`Świat zapisuje się sam co {sec} s i przy zwijaniu gry.`,"tip.11":`Każda zapalona gwiazda zostaje w twojej konstelacji na zawsze.`,"boot.render":`Przygotowujemy płótno…`,"boot.worlds":`Szukamy twoich światów…`,"boot.ready":`Gotowe`,"about.idea":`O grze`,"about.idea.text":`Heliohold to fabryka wokół żywej gwiazdy. Zbuduj wokół niej sferę Dysona łuk po łuku, łów skały z pasa harpunami, kruś komety wiązkami, rozszczepiaj światło o pięciu właściwościach i zbierz pełne spektrum, by zapalić nową gwiazdę.`,"about.made":`Jak powstała`,"about.made.text":`Budynki, statek, gwiazdy i Rój powstały w Blenderze i są składane skryptami; portrety postaci stworzył model generatywny, a skrypty je dopracowały (światło, animacja). Cały dźwięk jest syntezowany na bieżąco — w grze nie ma plików dźwiękowych.`,"about.privacy":`Prywatność`,"about.privacy.text":`Gra nie zbiera ani nie wysyła żadnych danych. Światy i ustawienia są przechowywane tylko na twoim urządzeniu.`,"about.thanks":`Podziękowania`,"about.thanks.text":`Pierwszym testerom — za szczere „nic nie rozumiem”, które uczyniło grę jaśniejszą.`,"gen.title":`Ustawienia świata`,"gen.preview":`Podgląd układu: gwiazda, pasy, Centrum, gniazdo Roju`,"gen.preview.legend":`Centrum pośrodku · gwiazda z koroną · żółte ramki — pierwsza linia · fiolet — gniazdo Roju`,"gen.presets":`Szablon świata`,"gen.preset.classic":`Klasyczny`,"gen.preset.plenty":`Obfitość`,"gen.preset.scarce":`Niedostatek`,"gen.preset.deep":`Daleki kosmos`,"gen.preset.custom":`Własny`,"gen.preset.classic.desc":`Zamierzony balans: zwykłe pasy, jasna gwiazda, Rój w swoim czasie.`,"gen.preset.plenty.desc":`Bogate szerokie pasy, więcej komet, jaśniejsza gwiazda, spokojniejszy Rój, hojny zestaw.`,"gen.preset.scarce.desc":`Ubogie wąskie pasy, rzadkie komety, przygasła gwiazda, wcześniejszy Rój. Liczy się każda skała.`,"gen.preset.deep.desc":`Rozległy układ: pasy daleko od siebie, ale bogatsze, większa gwiazda. Po kamień trzeba będzie lecieć.`,"gen.preset.custom.desc":`Twoje własne wartości — otwórz grupy poniżej. Świat zawsze da się ukończyć: generator sprawdza start.`,"gen.group.res":`Pasy i komety`,"gen.group.star":`Gwiazda`,"gen.group.dark":`Rój`,"gen.group.kit":`Zestaw startowy`,"gen.knob.star_power":`Jasność`,"gen.knob.dark_freq":`Częstość gniazd`,"gen.knob.dark_delay":`Czujność gniazd`,"gen.kit.0":`Skromny`,"gen.kit.1":`Zwykły`,"gen.kit.2":`Hojny`,"gen.code":`Kod świata`,"gen.code.copy":`Kopiuj kod świata`,"gen.code.copied":`Kod świata skopiowany — możesz go udostępnić`,"gen.code.bad":`Nie rozpoznano kodu. Wklej ciąg w rodzaju PHW1-…`,"gen.reset":`Jak w Klasycznym`,"gen.hint.star_power":`Jasność gwiazdy: przygasła daje sferze mniej — zewnętrzne powłoki szybciej trafiają na limit.`,"gen.hint.dark_freq":`Ile jest gniazd Roju; pierwsze gniazdo istnieje zawsze — potrzebuje go finał.`,"gen.hint.dark_delay":`Ile łuny budzi gniazda: ×2 — dwa razy jaśniej, ×0,5 — wystarczy o połowę mniej.`,"etude.crossed_filters.name":`Skrzyżowane filtry`,"etude.crossed_filters.task":`Światło źródła jest spolaryzowane pod 0°, odbiornik przyjmuje tylko 90°. Płyta 90° blokuje wszystko — ale co, jeśli postawisz między nimi jeszcze jedną? Dostarcz {n} ph (kąt ustawisz w oknie polaryzatora).`,"etude.phase_cancel.name":`Faza π`,"etude.phase_cancel.task":`Dwa niebieskie źródła w przeciwfazie; odbiornik przyjmuje tylko fazę π. Połącz je w interferometrze takie, jakie są, a znoszą się nawzajem. Dodaj oba strumienie i dostarcz {n, number} ph.`,"etude.light_gates.name":`Bramki światła`,"etude.light_gates.task":`Sygnały A (czerwony) i B (zielony) migają. Górny odbiornik zlicza białe światło tylko przy „A i B”, dolny przy „A lub B, ale nie oba naraz”. Długie światło w złym momencie zeruje jego licznik. Dostarcz {n} ph za pomocą migawek (sterowanych z boków) i interferometru.`,"cfg.title.level_gate":`Tryb czujnika poziomu`,"cfg.level_gate.0":`Otwarta, dopóki sąsiad nie jest pełny (< {full} %)`,"cfg.level_gate.1":`Otwarta, dopóki sąsiad nie jest pusty (> {empty} %)`,"goal.twin_cell":`Postaw {n, plural, one {# akumulator światła} few {# akumulatory światła} many {# akumulatorów światła} other {# akumulatora światła}}`,"goal.twin_cell.why":`Bliźnięta mają noce: {night} s bez gwiazd.`,"goal.twin_cell.hint":`Doba trwa tu {day} min: bursztynowa gwiazda świeci {amber} s, niebieska {blue} s, potem {night} s nocy. Oś czasu jest w panelu Doby pod celem. Akumulator światła gromadzi światło w dzień i oddaje w nocy: światło wchodzi z tyłu, wychodzi z przodu. Zapamiętuje pierwszą barwę i nie przyjmuje innej. Światłowód niesie do {flux} ph/s — jedna linia zasila 5 maszyn.`,"goal.twin_cell.done":`Akumulatory stoją. Teraz przetrwaj noc.`,"goal.twin_night":`Utrzymaj do świtu światło w {n, plural, one {# maszynie} few {# maszynach} many {# maszynach} other {# maszynach}}`,"goal.twin_night.why":`Fabryka, która nie śpi.`,"goal.twin_night.hint":`Gdy obie gwiazdy zachodzą, światło żyje tylko w akumulatorach. Panel Doby pokazuje, na ile sekund starczy zapasu każdej barwy; liczy się, jeśli maszyny wciąż świecą pod koniec nocy.`,"goal.twin_night.done":`Noc minęła — fabryka świeciła bez gwiazd.`,"toast.dusk":`Noc: obie gwiazdy zaszły na {night} s — światło tylko w akumulatorach`,"toast.dawn":`Świt: wzeszła bursztynowa gwiazda`,"lab.filter":`Filtr drzewa`,"lab.filter.open":`Dostępne · {n}`,"lab.filter.all":`Wszystkie · {n}`,"lab.filter.done":`Zbadane · {n}`,"lab.filter.empty":`Tu pusto — wybierz inny filtr lub gałąź.`,"lab.branch":`Gałąź drzewa`,"tech.level":`poz. {n}`,"tech.time":`po {s} s`,"branch.any":`Wszystkie gałęzie`,"branch.mining":`Wydobycie`,"branch.logistics":`Logistyka`,"branch.light":`Światło`,"branch.matter":`Materia`,"branch.resonance":`Rezonans`,"branch.logic":`Logika`,"branch.defense":`Obrona`,"branch.stars":`Gwiazdy`,"branch.finale":`Finał`,"bonus.grabber":`+{v}% szybkości chwytaków`,"bonus.research":`+{v}% szybkości Centrum`,"bonus.hand":`+{v}% pracy ręcznej`,"bonus.spear":`+{v}% tempa przeładowania włóczni`,"bonus.glare":`−{v}% łuny`,"bonus.drone":`+{v}% szybkości i ładowności dronów`,"bonus.cool":`+{v}% chłodzenia radiatorów`,"bonus.forge":`+{v}% szybkości Kuźni`,"bonus.speed":`+{v}% szybkości maszyn`,"bonus.attenuation":`światłowody: −1 jasności na {n, plural, one {# pole} few {# pola} many {# pól} other {# pola}}`,"bonus.tunnel":`fałdy do {n, plural, one {# pola} few {# pól} many {# pól} other {# pola}}`,"bonus.swift":`szybkie drony`,"bonus.perLevel":`{one} na poziom · łącznie {total}%`,"lock.goto":`Pokaż w Centrum`,"goal.research":`Wytwórz {n, plural, one {# Odblask} few {# Odblaski} many {# Odblasków} other {# Odblasku}} i zbadaj Pryzmat`,"goal.research.hint":`Centrum potrzebuje światła: światłowód od linii do dowolnego jego boku. Osobna szlifiernia z recepturą „Odblask” (kwarc + płyta): „Włóż” kwarc i płyty w jej oknie, gotowe — „Weź”. W oknie „Badania” przy Centrum — „Oddaj tutaj”; Pryzmat — „Do kolejki”. Linii soczewek nie ruszaj. Później ręce uwolni linia: chwytak ze szlifierni Odblasków prosto do Centrum.`,"goal.research.why":`W archiwum nie ma planu wrót. Centrum odczytuje światło — i archiwum otwiera się krok po kroku.`,"goal.research.done":`Centrum odczytało pierwszy Odblask. Pryzmat odblokowany — archiwum „Zasiewu” zaczęło się otwierać.`,"bp.locked":`Zablokowane budynki: {n} — wklejanie je pominie`,"tree.title":`Drzewo technologii`,"tree.count":`zbadano {n} z {all}`,"tree.fit":`Pokaż całe drzewo`,"tree.queue":`Kolejka Centrum`,"tree.path":`Zbadaj ścieżkę · {n}`,"tree.open":`Całe drzewo`,"lock.gotoTree":`Pokaż na drzewie`,"key.tree":`Drzewo technologii`,"tree.filter.all":`Wszystko`,"tree.filter.open":`Dostępne`,"tree.filter.done":`Zbadane`,"tree.search":`Znajdź technologię`,"tree.mini":`Minimapa drzewa: naciśnij, by przejść`,"guide.tree":`Naciśnij „Całe drzewo” — mapę wszystkich odkryć, od Pryzmatu do finału.`,"guide.tree.reopen":`Otwórz Centrum jeszcze raz — jest tam przycisk „Całe drzewo”.`,"tree.queueFull":`Do kolejki trafia teraz {now}, pozostałe {n} dojdą w miarę kończenia badań.`,"tree.goal":`Cel ścieżki: Centrum samo uzupełnia kolejkę.`,"tree.gate":`Etap {spectrum} — odblokuje go „{tech}”`,"tree.next":`Następny krok:`,"tree.band":`etap · {stage}`,"settings.uiScale.capped":`Ten ekran używa {n}% — większa skala się nie zmieści.`,"status.23":`Zły pas`,"status.23.hint":`Harpun bierze skały (kwarc, obsydian), niewód bierze pył (szron, lód, antyświatło). Użyj drugiej wydobywarki.`,"status.24":`Pas się przerzedza`,"status.24.hint":`Zostało mniej niż ćwierć pasa. Czas budować przy następnym, bogatszym pasie.`,"status.25":`Pas wyczerpany`,"status.25.hint":`Skał już nie ma — przenieś wydobywarkę na inny pas.`,"machine.belt":`Pozostało w pasie: {n}%`,"machine.noBelt":`Brak pasa w zasięgu`,"cfg.role.3":`Zbiór`,"shield.label":`Tarcza`,"shield.aria":`Tarcza Strażnika: {n}%`,"toast.heatWarm":`Gorąco: tarcza się tu nie odnawia. Bliżej korony dostaje obrażenia.`,"toast.heatLow":`Tarcza na wyczerpaniu — odleć od gwiazdy!`,"toast.heatEject":`Wiatr gwiezdny odrzucił Strażnika. Nic nie przepadło.`,"goal.harpoon":`Postaw {n, plural, one {# harpun} few {# harpuny} many {# harpunów} other {# harpuna}} przy niebieskich skałach`,"goal.harpoon.hint":`Pasek budynków → harpun → miejsce przy znaczniku, tuż przy pasie. Jasny punkt i zsyp to wyjście; przycisk „Obróć” (R) kieruje je ku grawitaśmie. Jednej szlifierni wystarczy {n, plural, one {# harpun} few {# harpuny} many {# harpunów} other {# harpuna}}.`,"goal.harpoon.why":`Skał ręcznie się nie nanosi: śpiący potrzebują światła za kilka godzin, nie tygodni.`,"goal.harpoon.done":`Harpuny wystrzeliły. Skały przyjdą same — ty masz wolne ręce, ja — obliczenia.`,"goal.colors":`Rozszczep światło na kolory`,"goal.colors.hint":`Pryzmat: białe z tyłu → czerwień przed siebie, szmaragd w lewo, lazur w prawo. Soczewki kładź na stole optycznym pod barwnym światłem.`,"goal.colors.why":`Białe światło to wszystkie barwy naraz. Rozłożymy je — a archiwum odsłoni drogę do wrót.`,"goal.colors.done":`Światło rozszczepione na barwy — Centrum może je odczytać.`,"goal.ice":`Zbierz lód z meteorytów: {n}`,"goal.ice.why":`Kapsuły potrzebują zimna, a zimno to tutaj lód. Przychodzi z kosmosu: przez układ przelatują lodowe meteoryty i komety.`,"goal.ice.hint":`Meteoryty to jasne skały przecinające układ; strzałka wskazuje najbliższy, który zmierza ku bazie. {touch, select, yes {Stuknij} other {Kliknij}} go — kuter doleci, a wiązka skruszy skałę. Przeleć przez odłamki — lód zbiera się sam. Później włócznia na skupionym świetle będzie kruszyć meteoryty za ciebie.`,"goal.ice.done":`Lód w ładowni. Później włócznie i drony będą go łowić za ciebie.`,"goal.deep_signal":`Wyślij Głęboki sygnał`,"goal.deep_signal.why":`Gwiazda mrugnęła dwie sekundy po pierwszym spektrum. Przypadek? Głęboki sygnał rozłoży jej światło aż do najsłabszych linii.`,"goal.deep_signal.hint":`Głęboki sygnał: każda jednostka jego kosztu to po jednym spektrum M, K i G (liczba jest w oknie Centrum). K idzie najwolniej: dodaj drugą montownię K.`,"goal.deep_signal.done":`Sygnał poszedł! Centrum płonie trzema pierścieniami.`,"goal.awakening":`Zbadaj „Dalekie włókno” — łączność z Przystanią`,"goal.awakening.why":`Dalekie włókno przebija łącze przez podszewkę: pierwszy raz czysty kanał do domu, do Przystani. I droga ku innym gwiazdom.`,"goal.awakening.hint":`Potrzeba wszystkich sześciu spektrów: droga do Dalekiego włókna wiedzie przez wszystkie klasy, a jego cena to spektra F, A i B. Potem światłowody rzadziej tracą jasność.`,"goal.awakening.done":`Włókno gotowe: Przystań usłyszy „Jaskółkę”. Przed nami — inne gwiazdy.`,"goal.ridge_awakening":`Pierścień Grani otwarty`,"goal.ridge_awakening.why":`Otwarty pierścień trzyma drogę w obie strony — i niesie wzór ogrodu Grani.`,"goal.ridge_awakening.hint":`Otworzy się sam — za zgodą ogrodu albo kluczem siły.`,"goal.ridge_awakening.done":`Pierścień Grani otwarty. Jest w nim wzór narodzin.`,"achv.deep_signal.name":`Głęboki sygnał`,"achv.deep_signal.desc":`Spektrograf znalazł w świetle gwiazdy powtórzenia, jakich gwiazdy nie tworzą.`,"landmark.ring.quartz_rock":`kamień na soczewki`,"landmark.ring.obsidian_rock":`kamień na płyty`,"landmark.ring.ice_haze":`drobny lód — niewodem`,"landmark.ring.frost_dust":`szron — niewodem`,"gen.knob.belt_rich":`Zasobność pasów`,"gen.knob.belt_width":`Szerokość pasów`,"gen.knob.belt_spread":`Rozpiętość układu`,"gen.knob.meteor_rate":`Meteoryty i komety`,"gen.knob.star_size":`Rozmiar gwiazdy`,"gen.hint.belt_rich":`Ile kamienia mieści każdy pas: ×2 starcza na dwa razy dłużej.`,"gen.hint.belt_spread":`Pasy dalej od siebie: szersze luki na bazę, dłuższe drogi.`,"gen.hint.meteor_rate":`Jak często przelatują lodowe ciała: im częściej, tym więcej lodu.`,"gen.hint.star_size":`Większa gwiazda jest jaśniejsza i odpycha pasy na zewnątrz.`,"guide.place-harpoonA":`Postaw harpun w ramce przy pasie. Jasny punkt i rynna to jego wyjście: tam trafiają skały.`,"guide.place-harpoonA.rotate":`Obróć harpun tak, by wyjście było zwrócone {o, select, 1 {w lewo} 2 {w górę} 3 {w prawo} other {w dół}}: naciśnij „Obróć” lub R jeszcze {n, plural, one {# raz} few {# razy} many {# razy} other {# raza}}.`,"guide.place-harpoonA.repick":`Weź harpun z paska budynków: łowi skały z pasa sam.`,"guide.place-harpoonA.why":`Ten harpun zszedł z zacisku dokującego. Łowi skały sam — ręce masz wolne.`,"guide.place-harpoonB":`Drugi harpun idzie w ramkę obok, wyjściem w tę samą stronę.`,"guide.place-harpoonB.rotate":`Obróć harpun tak, by wyjście było zwrócone {o, select, 1 {w lewo} 2 {w górę} 3 {w prawo} other {w dół}}: „Obróć” lub R jeszcze {n, plural, one {# raz} few {# razy} many {# razy} other {# raza}}.`,"guide.place-harpoonB.repick":`Weź kolejny harpun z paska budynków.`,"shell.legacy":`{name} — świat z bardzo starej wersji, nieobsługiwany`,"shell.legacy.note":`Świat z bardzo starej wersji (sprzed pasów i spektrów) nie jest obsługiwany. Można go usunąć i zacząć nowy.`,"bonus.harvest":`+{v}% szybkości wydobywarek`,"bonus.meteor":`+{v}% meteorytów i komet`,"hover.left":`Pas: zostało {n}% skały. Pas się obraca — harpun obsłuży cały pas.`,"gen.code.legacy":`Ten kod świata pochodzi ze starszej wersji i nie jest obsługiwany: w grze są teraz pasy i spektra.`,"goal.far_belt":`Nowy pas: harpuny na trzecim pasie`,"goal.far_belt.why":`Kolonia to lata, a wewnętrzny pas rzednie. Dalsze pasy są bogatsze: fabryka nie stanie, gdy bliski się skończy.`,"goal.far_belt.hint":`Poleć do następnego skalistego pasa za obsydianowym i postaw harpun na jego skraju — liczy się, gdy zacznie wydobywać. Bliskie pasy rzednieją: później przenieś się dalej — harpuny i szlifiernia przy dalekim pasie, soczewki do skrzyni, stamtąd grawitaśma do bazy. Pozostały zasób pasa widać w podpowiedzi harpuna.`,"goal.far_belt.done":`Trzy pasy w pracy — gdy wewnętrzny zrzednie, fabryka nie stanie.`,"goal.fold":`Zbadaj fałdy i poprowadź ładunek lub światło pod przeszkodą`,"goal.fold.why":`Baza rośnie i linie wpadają na siebie. Fałda przestrzeni prowadzi ładunek i światło pod przeszkodą: najpierw {s1} pola, potem Centrum otworzy {s2}, {s3} i {s4}.`,"goal.fold.hint":`Zbadaj „Fałdy” w Centrum (spektrum M). Fałda: pierwszy łuk to wejście, następny dalej to wyjście (stawia się automatycznie); fałda przenosi też ładunek ponad pasem planetoid. Fałda świetlna to osobne badanie: dwa łuki zwrócone ku sobie. Wiązka już teraz leci nad grawitaśmami i pasami, tracąc {loss}% na pole nad grawitaśmą, ale przez maszyny przejdzie tylko fałdą.`,"goal.fold.done":`Linia zanurkowała i wynurzyła się! Jak ścieg na tkaninie. Mogę to narysować w albumie?`,"guide.lay-tunnel":`Kliknij {o, select, 1 {górny} 2 {prawy} 3 {dolny} other {lewy}} koniec ramki i przeciągnij grawitaśmę {o, select, 1 {w dół} 2 {w lewo} 3 {w górę} other {w prawo}} do końca.`,"guide.lay-tunnel.repick":`Weź grawitaśmę z paska budynków: przenosi skały.`,"guide.lay-tunnel.reverse":`Grawitaśma biegnie w złą stronę. Naciśnij „Cofnij” i narysuj ją jeszcze raz — od brzegu ramki przy harpunach.`,"guide.lay-tunnel.why":`Grawitaśma sama poniesie skały od harpunów.`,"status.26":`Brak wiązki`,"status.26.hint":`Wiązka sfery nie dociera: połóż łuk na najbliższej powłoce (orbita z kropek przy gwieździe) albo przysuń odbiornik — w promieniu {range} pól od orbity z łukami.`,"status.27":`Skały daleko`,"status.27.hint":`Pas jest tu wyjedzony i obraca się wolno. Postaw wydobywarkę gdzie indziej wzdłuż pasa.`,"status.28":`Powłoka ukończona`,"status.28.hint":`Wszystkie miejsca powłoki tego stopnia są zajęte. Wyjmij pozostałe łuki przyciskiem „Weź” i załaduj łuki następnego stopnia — dla zewnętrznej powłoki.`,"guide.place-arc":`Wszystko tu żyje światłem gwiazdy — łapią je łuki na kropkowanym pierścieniu wokół niej. Weź „Łuk I” i wybierz pierścień z kropek w ramce.`,"guide.place-arc.repick":`Weź „Łuk I” z paska budynków na dole.`,"guide.place-arc.why":`Łuk łapie światło gwiazdy. Jeden daje {arc} ph/s. Czterdziestu śpiących to dużo łuków. Zacznijmy od jednego.`,"guide.place-receiver":`Postaw talerz — odbiornik promieni — w ramce. Łuk wyśle do niego wiązkę.{touch, select, yes {} other { Lewy przycisk myszy stawia, prawy odkłada budynek z ręki.}}`,"guide.place-receiver.repick":`Weź odbiornik promieni z paska budynków.`,"guide.place-receiver.why":`Odbiornik to gniazdko bazy. Z niego światło płynie do maszyn.`,"goal.arc":`Rzuć łuk na przerywany pierścień przy gwieździe`,"goal.arc.hint":`Pasek budynków → „Łuk I” → {touch, select, yes {stuknij} other {kliknij}} jarzący się pierścień z kropek przy gwieździe (orbitę łuków). Nie trzeba lecieć blisko: kuter rzuca łuk na {reach} pól.`,"goal.arc.why":`Zapas awaryjny topnieje. Łuk to pierwsze światło, które karmi śpiących, a nie zużywa ich zapasu.`,"goal.arc.done":`Łuk w ramce. Tej gwiazdy nie ma w katalogu, ale świeci hojnie. Biorę.`,"goal.catapult":`Katapulta: łuki lecą same`,"goal.catapult.hint":`Zbadaj „Katapulta” w Centrum (spektrum M) i postaw ją w luce. Łuki trafiają do samej katapulty (chwytakiem lub „Włóż” w jej oknie), światło idzie światłowodem — ona wystrzeliwuje je w wolne miejsca powłok. Długi chwytak sięga przez pole, więc grawitaśma nie musi jej dotykać.`,"goal.catapult.why":`Śpiący i przyszłe wrota potrzebują sfery z setek łuków. Ręcznie się jej nie złoży — katapulta rzuca łuki sama.`,"goal.catapult.done":`Pierwszy łuk w locie — sfera buduje się sama.`,"goal.crown":`Zamknij pierścień łuków wokół gwiazdy`,"goal.crown.hint":`Powłoka I przy koronie — slotów: {slots}. Zamknięta powłoka daje każdemu łukowi +{closed}% i rozbłyska całym pierścieniem. Cały Wieniec to {total} ph/s: {rx, plural, one {# odbiornik} few {# odbiorniki} many {# odbiorników} other {# odbiornika}} po {cap}.`,"goal.crown.why":`Zamknięty pierścień łuków to Wieniec, pierwsza powłoka. Jego światła wystarczy, by przełączyć kapsuły z paneli awaryjnych na światło bazy.`,"goal.crown.done":`Wieniec zamknięty! Każdy łuk świeci o {closed}% jaśniej.`,"goal.shell2":`Powłoka II: {n, plural, one {# łuk} few {# łuki} many {# łuków} other {# łuku}} drugiego stopnia`,"goal.shell2.hint":`Zbadaj „Powłoka II” (spektrum K). Łuk II składa się z bursztynowej soczewki, soczewek i płyt; jego orbita leży na zewnętrznym skraju szczeliny Centrum. Zewnętrzna powłoka łapie światło, które wewnętrzna przepuszcza.`,"goal.shell2.why":`Wieńcowi brakuje światła na spektra K, a łączności z Przystanią — mocy. Nowa powłoka wokół starej da jedno i drugie.`,"goal.shell2.done":`Druga powłoka rośnie — baza ma więcej światła.`,"goal.captured":`Gwiazda w sferze: {pct}% jasności`,"goal.captured.hint":`Wszystkie powłoki razem biorą część jasności gwiazdy. Powłoki III i IV leżą przy dalekich pasach; pełna sfera bierze {n}%.`,"goal.captured.why":`Ile światła Kolebki już pracuje na ciebie — i na przyszłe wrota. Wrota będą potrzebować niemal całej gwiazdy.`,"goal.captured.done":`{pct}% gwiazdy — w twojej sferze.`,"hover.shell.name":`Powłoka {n} sfery Dysona`,"hover.shell.arcs":`Łuki: {built} z {n} · po {flux} ph/s`,"hover.shell.star":`Gwiazda w sferze: {p}%`,"hover.shell.hint":`Rzuć Łuk {n} na orbitę z kropek; zamknięta powłoka daje każdemu łukowi +{closed}%.`,"landmark.shell":`Powłoka {n}`,"landmark.shell.sub":`łuki: {built} z {n}`,"achv.crown_closed.name":`Wieniec`,"achv.crown_closed.desc":`Zamknij powłokę I sfery Dysona — pierścień światła wokół gwiazdy.`,"achv.half_star.name":`Pół gwiazdy`,"achv.half_star.desc":`Sfera zbiera połowę jasności gwiazdy.`,"achv.whole_star.name":`Cała gwiazda`,"achv.whole_star.desc":`Sfera Dysona bierze {pct}% jasności gwiazdy.`,"launcher.put":`Załaduj: {name}`,"hover.shell.got":`Odbiorniki biorą {got} z {power} ph/s sfery`,"hover.shell.lost":`Odbiorniki biorą tylko {got} z {power} ph/s — dodaj jeszcze jeden odbiornik ({cap} ph/s)`,"lab.sphere":`Gwiazda w sferze: {p}% · łuki: {arcs}`,"goal.more":`Jak to zrobić?`,"goal.less":`Zwiń`,"goal.part.research":`Zbadaj „{name}” w Centrum`,"goal.part.deliver":`Dostarcz do Centrum: {name}`,"goal.part.auto":`Wytwórz maszynami: {name}`,"goal.part.make":`Zdobądź: {name}`,"goal.part.build":`Postaw: {name}`,"goal.beam.part":`Wiązka dociera do portu odbiorczego`,"goal.resonance.part":`Harpuny w rezonansie`,"goal.fold.part":`Ładunek lub światło przeszło przez fałdę`,"goal.shell2.part":`Łuki na powłoce II`,"goal.liquid.part":`Wytworzone płynne światło, j.`,"goal.cooling.part":`Odbiorniki przy gwieździe bez przegrzania`,"goal.drone.part":`Pierwszy kurs drona`,"goal.logic.part":`Przełączenia migawki`,"goal.spear.part":`Włócznia naładowana`,"compass.fly":`Leć do celu`,"place.why.busy":`Zajęte`,"place.why.belt":`Pas — tu nie zbudujesz`,"place.why.orbit":`Orbita sfery — tylko łuki`,"place.why.corona":`Korona gwiazdy`,"place.why.far":`Za daleko — {touch, select, yes {stuknij} other {kliknij}} ponownie`,"place.why.items":`Brak w ekwipunku`,"place.why.slot":`Łuki tylko na przerywanej linii powłoki`,"place.why.grade":`Zła powłoka — potrzebny łuk innego stopnia`,"hint.lab.5":`Wybierz technologię w oknie Centrum lub w drzewie — samo Centrum nie ruszy.`,"machine.putAll":`Włóż wszystko: {item}`,"status.lowLight":`Mało światła`,"status.lowLight.hint":`Działa wolniej niż w recepturze: dociera mniej światła, niż potrzeba na cykl. Dodaj łuki i odbiorniki albo ogranicz liczbę maszyn na tym światłowodzie.`,"machine.inflow":`Dopływ {n} ph/s → cykl {s} s`,"machine.noInflow":`Dopływ 0 ph/s — światło nie dociera`,"status.7.dry":`Nie dociera do niej światło: poprowadź światłowód do maszyny — od odbiornika promieni lub wyjścia pryzmatu. Światło nie przechodzi między stykającymi się maszynami. Światłowód jest — wtedy jego sieć nie ma źródła albo inne maszyny zabierają całe światło: najczęściej pryzmat z wolnymi wyjściami.`,"status.prism.3":`Odbiorcy nasyceni — światło czeka`,"status.mixer.3":`Nie ma gdzie oddać światła`,"hint.mixer.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.focuser.3":`Nie ma gdzie oddać światła`,"hint.focuser.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.receiver.3":`Nie ma gdzie oddać światła`,"hint.receiver.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.modulator.3":`Nie ma gdzie oddać światła`,"hint.modulator.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.polarizer.3":`Nie ma gdzie oddać światła`,"hint.polarizer.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.phaser.3":`Nie ma gdzie oddać światła`,"hint.phaser.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.interferometer.3":`Nie ma gdzie oddać światła`,"hint.interferometer.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.light_cell.3":`Nie ma gdzie oddać światła`,"hint.light_cell.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"status.port.3":`Nie ma gdzie oddać światła`,"hint.port.3":`Podłącz światłowód do wyjścia (jeden światłowód zasila kilka maszyn) albo dosuń wejście maszyny prosto do wyjścia.`,"hud.glareFrom":`{name} — {v} ph/s`,"lab.choose":`Wybierz technologię`,"machine.inflowOnly":`Dopływ {n} ph/s`,"machine.bufferFull":`Bufor światła pełny — czeka na wejście`,"inv.toHand":`Do ręki — postaw`,"toast.firstCrack":`Meteoryt skruszony! Przeleć przez odłamki — lód zbiera się sam (albo {touch, select, yes {stuknij odłamek} other {kliknij odłamek}}).`,"machine.spearMeteor":`Rój nie jest w pobliżu — kruszy meteoryty w promieniu {r} pól (co {every} s). Skruszone w tej grze: {n}`,"card.fromBelt":`Pas planetoid: wiązka kutra ({touch, select, yes {stuknij skałę} other {kliknij skałę}}) albo harpun tuż przy wstędze pasa.`,"card.fromTrawl":`Pas drobnicy: niewód przy wstędze pasa.`,"place.why.planet":`Orbita planety — przeleci tędy`,"status.29":`Planeta za daleko`,"status.29.hint":`Planeta jest poza oknem wyrzutni masowej — poczekaj, aż się zbliży, albo użyj wahadłowców. Okno to rozświetlony łuk orbity.`,"status.30":`Brak stacji`,"status.30.hint":`Najpierw postaw na planecie stację orbitalną — rzuć ją Strażnikiem albo wystrzel ze stołu startowego.`,"status.31":`Planeta pełna`,"status.31.hint":`Wszystkie sloty planety zajęte (albo stacja i wyrzutnia już tam są). Wybierz inną planetę.`,"status.32":`Wybierz planetę`,"status.32.hint":`Wybierz zbadaną planetę w oknie maszyny. Obserwatorium albo przelot Strażnika bada nowe.`,"status.33":`Zła planeta`,"status.33.hint":`Lądowniki idą na planety skaliste, syfony na planety z atmosferą; wyrzutnię masową stawia się tylko rakietą.`,"status.34":`Brak wyrzutni masowej`,"status.34.hint":`Wystrzel wyrzutnię masową na planetę ze stołu startowego.`,"bonus.planet":`+{v}% tempa lądowników i syfonów`,"bonus.shuttle":`+{v}% szybkości i ładowności wahadłowców`,"bonus.driver":`+{v}% okna wyrzutni masowej`,"branch.planets":`Planety`,"planets.title":`Planety`,"planets.empty":`Ta gwiazda nie ma planet.`,"planet.unknown":`Niezbadana`,"planet.hours":`{h} godz. {m} min`,"planet.min":`{n} min`,"planet.cells":`{n, plural, one {# pole} few {# pola} many {# pól} other {# pola}}`,"planet.orbit":`Orbita`,"planet.orbitVal":`{r, plural, one {# pole} few {# pola} many {# pól} other {# pola}} · {time} na obieg`,"planet.dist":`Do Strażnika`,"planet.atmo":`Atmosfera`,"planet.atmo.thick":`gęsta`,"planet.atmo.thin":`rzadka`,"planet.atmo.trace":`śladowa`,"planet.none":`brak`,"planet.rings":`Pierścienie`,"planet.ring.ice":`lodowe`,"planet.ring.rock":`skaliste`,"planet.moons":`Księżyce`,"planet.stock":`Zasób`,"planet.kind.lava":`Planeta lawowa`,"planet.kind.rocky":`Planeta skalista`,"planet.kind.desert":`Planeta pustynna`,"planet.kind.crystal":`Planeta krystaliczna`,"planet.kind.ocean":`Planeta oceaniczna`,"planet.kind.cloud":`Planeta chmur`,"planet.kind.ice":`Planeta lodowa`,"planet.kind.ice_giant":`Lodowy olbrzym`,"planet.kind.gas_giant":`Gazowy olbrzym`,"planet.special.tidal":`rozrywana pływowo`,"planet.special.aurora":`zorza polarna`,"planet.unsurveyed":`Niezbadana: poleć w promień {survey} pól od niej albo zbuduj obserwatorium.`,"planet.slots":`Sloty`,"planet.slotFree":`wolne`,"planet.mod.1":`Stacja orbitalna`,"planet.mod.2":`Lądownik`,"planet.mod.3":`Syfon atmosferyczny`,"planet.mod.4":`Wyrzutnia masowa`,"planet.store":`Magazyn stacji`,"planet.needStation":`Moduły wymagają stacji — zrzuć ją pierwszą.`,"planet.window":`Okno wyrzutni masowej za {time}`,"planet.fly":`Leć`,"planet.here":`Tutaj`,"planet.take":`Weź {n}`,"planet.throw.hint":`Strażnik rzuca moduł z odległości {reach} pól od krawędzi planety`,"planet.throw.station":`Stacja`,"planet.throw.lander":`Lądownik`,"planet.throw.siphon":`Syfon`,"planet.why.far":`Podleć bliżej — na {reach, plural, one {# pole} few {# pola} many {# pól} other {# pola}} od krawędzi`,"planet.why.none":`Brak w ekwipunku — wytwórz`,"planet.why.locked":`Najpierw zbadaj technologię`,"planet.why.full":`Wszystkie sloty planety zajęte`,"planet.why.station":`Stacja już tam jest`,"planet.why.noStation":`Najpierw stacja`,"planet.why.wrong":`Nie do tej planety`,"planet.how.tektite":`Tektyt: stacja plus lądowniki. Zwoź go wahadłowcem albo łap wyrzutnią masową.`,"planet.how.neon":`Neon: stacja plus syfony. Zwoź go wahadłowcem albo łap wyrzutnią masową.`,"planet.how.ice":`Lód: stacja plus lądowniki — zapas lodu dla megabazy.`,"cfg.title.launch_pad":`Cel startu`,"cfg.title.shuttle_port":`Cel wahadłowców`,"cfg.title.catcher":`Planeta wyrzutni`,"cfg.title.neon_emitter":`Kolor światła`,"cfg.neon_emitter.0":`Czerwony`,"cfg.neon_emitter.1":`Szmaragdowy`,"cfg.neon_emitter.2":`Lazurowy`,"cfg.planetAuto":`Auto`,"cfg.planetNone":`Brak`,"shuttle.home":`Wahadłowce w domu: {n} · w locie: {f}`,"shuttle.put":`Włóż wahadłowce`,"observatory.target":`Badanie: {name} — {n}%`,"observatory.done":`Wszystkie planety zbadane`,"goal.planet_seen":`Zbadaj planetę`,"goal.planet_seen.why":`Śpiący i dziewięć tysięcy z „Exodusu” potrzebują ziemi, a Kolebka ma własne światy. Na planetach jest też to, czego nie ma w pasach: tektyt i neon.`,"goal.planet_seen.hint":`{touch, select, yes {Stuknij} other {Kliknij}} strzałkę — kuter poleci do najbliższej planety. W promieniu {survey} pól jest badana automatycznie; albo zbuduj obserwatorium.`,"goal.planet_seen.done":`Planeta zbadana: typ, surowiec i sloty są w jej karcie.`,"goal.planet_seen.part":`Zbadaj planetę`,"goal.planet_landing":`Lądowanie: stacja i lądownik`,"goal.planet_landing.why":`Stacja na orbicie to pierwszy dok kolonii przy żywej ziemi. Lądownik wydobywa tektyt do jej magazynu.`,"goal.planet_landing.hint":`Wytwórz stację i lądownik, poleć na planetę stałą (skalistą, lawową, pustynną, kryształową), {touch, select, yes {stuknij ją} other {kliknij ją}} — „Stacja”, potem „Lądownik”.`,"goal.planet_landing.done":`Pierwsze lądowanie! Magazyn stacji się zapełnia.`,"goal.planet_landing.part":`Postaw stację`,"goal.planet_landing.part.2":`Postaw lądownik`,"goal.planet_tektite":`Szkło tektytowe: {n}`,"goal.planet_tektite.why":`Szkło tektytowe to optyka wyższych stopni: rurki, wahadłowce, łapacz. Bez niego wrota pozostaną poza zasięgiem.`,"goal.planet_tektite.hint":`Weź tektyt ze stacji („Weź” w karcie planety), zanieś do domu i przetop w piecu tektytowym na czerwonym świetle.`,"goal.planet_tektite.done":`Szkło z planety! Pierwsza rzecz zrobiona z prawdziwej ziemi. W Przystani ziemia jest tylko na obrazkach.`,"goal.planet_shuttle":`Pierwszy kurs wahadłowca`,"goal.planet_shuttle.why":`Wahadłowce same zwożą ładunek ze stacji planet do twojej bazy — koniec z ręcznymi kursami.`,"goal.planet_shuttle.hint":`Zbuduj port wahadłowców, doprowadź światło ({charge} ph na start), włóż wahadłowce i wybierz planetę albo Auto. Ładunek ląduje w miejscach portu — odbierz go chwytakami.`,"goal.planet_shuttle.done":`Wahadłowiec wrócił z ładunkiem.`,"goal.planet_shuttle.part":`Wahadłowiec dostarczył ładunek`,"goal.planet_neon":`Neon: syfon i {n} j. płynnego neonu`,"goal.planet_neon.why":`Neon to światło bez gwiazdy. Przyda się tam, gdzie gwiazda nie pomoże — i do rurek spektrum O, ostatniego klucza wrót.`,"goal.planet_neon.hint":`Postaw stację i syfon na planecie z atmosferą (olbrzym, chmury, ocean). Neon plus lód trafia do kondensatora neonu na niebieskim świetle.`,"goal.planet_neon.done":`Neon świeci sam, bez gwiazdy! Jakby ktoś zostawił nam światło na noc.`,"goal.planet_neon.part":`Postaw syfon`,"goal.planet_neon.part.2":`Wytwórz {n} j. płynnego neonu`,"goal.planet_light":`Własne światło: emiter neonowy`,"goal.planet_light.why":`{flux} ph/s dowolnej barwy podstawowej bez gwiazdy — tam, gdzie jej światło nie sięga.`,"goal.planet_light.hint":`Zbuduj emiter neonowy, doprowadź płynny neon rurą i wybierz barwę; poprowadź światłowód od jego przodu.`,"goal.planet_light.done":`Emiter świeci.`,"goal.planet_light.part":`Emiter świeci`,"planet.windowOpen":`Planeta jest w oknie wyrzutni masowej — lecą kapsuły`,"planet.sec":`{n} s`,"guide.doneTitle":`Gotowe!`,"guide.next":`Dalej`,"guide.min":`Zwiń podpowiedź`,"guide.restore":`Samouczek {n}/{total} — pokaż`,"guide.intro":`Światło gwiazdy jest tu za darmo. Maszyny, które je łapią, robi się ze skały. Zacznijmy od skały.`,"guide.fly.done":`Jesteśmy na miejscu. Niebieskie skały to kwarc. Wszystko zaczyna się od niego.`,"guide.mine.done":`Kwarc w ładowni: {n}. Zachowaj go — przyda się na grawitaśmy.`,"guide.place-arc.done":`Światło płynie: {arc} ph/s. Łuk złapał pierwszą część gwiazdy.`,"guide.place-receiver.done":`Promień dotarł: {arc} ph/s w odbiorniku.`,"guide.place-grinder.done":`Stoi. Ale jest ciemna: bez receptury i światła.`,"guide.recipe.done":`Zlecenie wystawione. Teraz podaj światło — i ruszy.`,"guide.lay-lights.touch":`Poprowadź żyłę: weź światłowód i przesuń palcem po ramce od odbiornika do szlifierni.`,"guide.lay-lights.why":`Światłowód to przewód dla światła. Bez światła maszyny stoją — a śpiący czekają.`,"guide.lay-lights.stuck":`Nie świeci? Światłowód musi dotykać i talerza, i szlifierni — wypełnij całą ramkę.`,"guide.lay-lights.done":`Szlifiernia rozbłysła! Brakuje już tylko kwarcu.`,"guide.place-harpoonA.done":`Pal! Lina trzyma skałę. Łowimy, dowódco.`,"guide.place-harpoonB.why":`Jeden harpun nie nakarmi szlifierni. Drugi będzie akurat.`,"guide.place-harpoonB.done":`Drugi harpun na miejscu — szlifierni starczy kamienia.`,"guide.lay-tunnel.stuck":`Brakuje grawitaśm? Wytwórz więcej w oknie „Ekwipunek”. Przeciągnij od jednego końca ramki do drugiego.`,"guide.lay-tunnel.done":`Kwarc popłynął. Pięknie idzie.`,"guide.place-grabIn.done":`Kwarc w szlifierni — szlifuje!`,"guide.place-grabOut.done":`Chwytak czeka na miejsce, gdzie położy soczewkę.`,"guide.place-storage.done":`Linia gotowa: pas → grawitaśma → szlifiernia → skrzynia. Pierwszy łańcuch w tym układzie.`,"guide.first-lens.stuck":`Jeszcze nie ma soczewki? Wybierz szlifiernię lub chwytak z plakietką: jego okno powie, czego brakuje.`,"guide.first-lens.done":`Pierwsza rzecz zrobiona w tym układzie — przez maszyny, bez twoich rąk.`,"guide.research-pick":`Centrum odblokowuje nowe maszyny za naukę. Znajdź „Pryzmat” i naciśnij „Do kolejki”.`,"guide.research-pick.reopen":`Otwórz Centrum jeszcze raz — wybierzmy pierwsze badanie.`,"guide.research-pick.why":`Pryzmat rozszczepia białe światło gwiazdy na barwy. Wszystko inne zaczyna się od barw.`,"guide.research-pick.done":`Pryzmat w kolejce. Centrum potrzebuje {n} Odblasków — robi je szlifiernia, a cel pokaże, jak.`,"goal.mark.resource":`WYDOBYWAJ TUTAJ`,"goal.mark.harvest":`HARPUN — TUTAJ`,"goal.mark.meteor":`{touch, select, yes {STUKNIJ} other {KLIKNIJ}}, BY ROZBIĆ`,"goal.mark.lab":`CENTRUM`,"goal.mark.star":`ŁUKI NA PIERŚCIEŃ`,"goal.mark.protostar":`PROTOGWIAZDA`,"goal.mark.ghost":`WIDMO BUDYNKU`,"goal.mark.node":`GNIAZDO ROJU`,"goal.mark.farBelt":`NOWY PAS — HARPUN TUTAJ`,"goal.mark.forge":`KUŹNIA GWIAZDY`,"goal.mark.planet":`PLANETA`,"goal.mine.mark":`{touch, select, yes {STUKNIJ} other {KLIKNIJ}}, BY WYDOBYĆ`,"goal.expand.mark":`SZLIFIERNIA PŁYT — TUTAJ`,"goal.mark.lineGrinder":`SZLIFIERNIA — TUTAJ`,"goal.obsidian.mark":`HARPUN — WYJŚCIEM DO SZLIFIERNI`,"goal.plates.mark":`JESZCZE JEDEN HARPUN — DO SZLIFIERNI`,"ship.title":`Statek`,"ship.hull.1":`„Strzała”`,"ship.hull.2":`„Osa”`,"ship.hull.3":`„Sokół”`,"ship.fire.title":`Automatyczny ogień do zagrożeń i meteorytów w zasięgu broni`,"ship.fire.on":`Ogień: auto`,"ship.fire.off":`Ogień: wył.`,"ship.slots":`Sloty statku`,"ship.empty":`pusty`,"ship.filter":`Do czego strzelać`,"ship.filter.auto":`Wszystko`,"ship.filter.big":`Tylko duże`,"ship.filter.tap":`Wybrane`,"ship.ammo":`{name}: {n} w ładowni, {m} w magazynku`,"ship.none":`Brak pasujących modułów w ekwipunku — wytwórz je ręcznie lub w montowni.`,"ship.unequip":`Zdejmij moduł`,"ship.hint":`{touch, select, yes {Stuknij} other {Kliknij}} gniazdo lub numer na modelu, by założyć albo wymienić moduł.`,"ship.energy":`Energia`,"ship.energy.short":`za mało energii: broń zgaśnie`,"ship.energy.aria":`Energia statku {n}%`,"ship.overload":`przeciążenie`,"ship.stat.speed":`Prędkość`,"ship.stat.shield":`Tarcza`,"ship.stat.regen":`Odnowienie`,"ship.stat.output":`Moc E/s`,"ship.stat.drain":`Pobór E/s`,"ship.stat.battery":`Bateria`,"ship.stat.dps":`Obrażenia/s`,"ship.stat.reach":`Zasięg wydobycia`,"ship.stat.collect":`Zbiór odłamków`,"hail.warn":`Kamienny grad za {s} s · skały: {n}`,"achv.ship_first_shot.name":`Pierwszy strzał`,"achv.ship_first_shot.desc":`Rozbij meteoryt lub skałę bronią statku.`,"achv.ship_mark_2.name":`Mk II`,"achv.ship_mark_2.desc":`Zamontuj na statku moduł Mk II.`,"achv.ship_leviathan.name":`Flagowiec`,"achv.ship_leviathan.desc":`Zbadaj kadłub „Zenit” — szczyt linii statków.`,"achv.ship_hail_50.name":`Kamienna tarcza`,"achv.ship_hail_50.desc":`Zestrzel bronią statku skały gradu: {n}.`,"achv.ship_swarms_10.name":`Postrach Roju`,"achv.ship_swarms_10.desc":`Zniszcz obcych z Roju: {n}.`,"ship.tasks":`Zadania statku`,"ship.task.module":`Zamontuj broń`,"ship.task.shot":`Rozbij meteoryt bronią`,"ship.task.ammo":`Montownia wytworzyła taśmy nabojowe: {n}`,"ship.task.mark":`Moduł Mk II`,"ship.task.hail":`Zestrzel skały gradu: {n}`,"guide.ship-open":`Otwórz okno „Statek” — są tam moduły twojego kutra.`,"guide.ship-open.more":`Okno „Statek” jest w menu „Więcej”.`,"guide.ship-craft":`Wytwórz laser impulsowy — mocniejszy od seryjnego: płyty, lazurowe soczewki i rezonator.`,"guide.ship-craft.stuck":`Brak lazurowych soczewek? Stół optyczny robi je z soczewek pod lazurowym światłem.`,"guide.ship-weapon":`{touch, select, yes {Stuknij} other {Kliknij}} gniazdo broni — numer 6 — i załóż laser.`,"guide.ship-weapon.why":`Broń strzela sama — do meteorytów i do wszystkiego, co przypełznie.`,"guide.ship-weapon.reopen":`Ponownie otwórz okno „Statek”.`,"guide.ship-shot":`Laser strzela sam — do meteorytów i do Roju w pobliżu statku. Energia to pasek pod tarczą.`,"guide.ship-shot.done":`Trafienie! Przeleć przez odłamki, by je zebrać. Laser poradzi sobie też z gniazdem Roju — ale chroni je straż.`,"flare.warn":`Gwiazda rozbłyskuje: wybuch za {s} s — odsuń się od korony`,"flare.now":`Rozbłysk gwiazdy! Korona jest dwa razy szersza jeszcze przez {s} s`,"swarm.title":`Rój`,"swarm.calm":`Kontemplacja: w tym świecie nie ma Roju.`,"swarm.gate":`Rój żyje od pierwszej minuty. Oczy gniazda pokazują, czy widzi łunę twojej bazy.`,"swarm.evo":`Ewolucja {e} ‰`,"swarm.nests":`Gniazda w pobliżu: {n} (przebudzone: {a})`,"swarm.cleared":`Oczyszczone gniazda: {n}`,"swarm.hives":`Planety pod ulami: {n} · uwolnione: {f}`,"swarm.repelled":`Odparte fale: {n} z {m}`,"swarm.repaired":`Naprawiono: {n} pkt · uszkodzone teraz: {d}`,"swarm.wave.soon":`Fala za {t} · obcy: {n}`,"swarm.wave.now":`Fala atakuje · zostało: {n}`,"swarm.advice":`Pancerz — {c}: włócznie i wiązki ze światłem tej barwy biją ×{match, number}, białym ×{white}, innym ×{other, number}.`,"swarm.hue.r":`Czerwony`,"swarm.hue.g":`Szmaragdowy`,"swarm.hue.b":`Lazurowy`,"swarm.showTarget":`Pokaż cel`,"swarm.showNest":`Najbliższe gniazdo`,"swarm.repairNext":`Napraw najbliższy ({n})`,"swarm.quiet":`Brak fal. Radar wcześniej pokaże kolejną.`,"swarm.quietRadar":`Brak fal — radar czuwa.`,"swarm.hint":`Łuna rozchodzi się od twojej bazy; gniazda ją widzą, chłoną i hodują z niej grupy nalotowe. Ewolucja rośnie wraz z łuną, nowymi stopniami spektrów i wyzwolonymi planetami — nie z czasem. Mniej wycieków, mniej fal; stawiaj wieżyczki i bariery przy najjaśniejszych maszynach.`,"hud.swarm.incoming":`Fala {t} · {n}`,"hud.swarm.fight":`Rój · zostało {n}`,"hud.swarm.awake":`Rój · {n} · {e} ‰`,"swarm.toast.woke":`Gniazdo Roju się przebudziło: dotarła do niego łuna. Usuń łunę — a gniazdo znów zaśnie.`,"swarm.toast.wave":`Rój nadciąga: fala za {t} s, {n} obcych. Strzałka pokazuje, skąd.`,"swarm.toast.go":`Fala wyruszyła!`,"swarm.toast.repelled":`Fala odparta! Zestrzelono {k}, obrażenia bazy: {d}.`,"swarm.toast.left":`Fala odeszła, obrażenia bazy: {d}. Napraw, co zepsute.`,"swarm.toast.nest":`Gniazdo oczyszczone: królowa nie żyje, zapala się protogwiazda. +{chitin} chityny.`,"machine.hp":`Wytrzymałość {n} / {m}`,"machine.wreck":`Wrak — nie działa. Napraw go albo wyburz (maszyna wraca do ciebie).`,"machine.repair":`Napraw`,"machine.ammo":`Amunicja: {n} z {m} strzałów`,"machine.kits":`Zapas napraw: {n} z {m} pkt`,"machine.dome":`Tarcza: {n}`,"machine.def.turret":`Obrażenia {dmg} · {rate} na s · zasięg {r, plural, one {# pole} few {# pola} many {# pól} other {# pola}}`,"machine.def.barrier":`Obcy na drodze gryzie barierę, a nie maszyny za nią.`,"machine.def.dome":`Pochłania trafienia w maszyny w promieniu {r} pól, tarcza do {cap}.`,"machine.def.radar":`Fale widać {warn} s wcześniej.`,"machine.def.decoy":`Ściąga falę na siebie, jeśli jest w promieniu {reach} pól od celu.`,"machine.def.bay":`Naprawia {heal} pkt/s w promieniu {r} pól, zużywając zestawy naprawcze.`,"alien.spark.name":`Iskra`,"alien.reaper.name":`Żniwiarz`,"alien.stinger.name":`Żądło`,"alien.ram.name":`Taran`,"status.35":`Uszkodzone`,"status.35.hint":`Wytrzymałość poniżej połowy — maszyna iskrzy. Napraw ją: „Napraw” w oknie maszyny albo stacja naprawcza.`,"status.36":`Wrak`,"status.36.hint":`Rój zniszczył tę maszynę. Napraw ją (szybciej z zestawami naprawczymi) albo wyburz: maszyna wraca do ciebie.`,"status.37":`Brak amunicji`,"status.37.hint":`Podawaj taśmy amunicji (albo zestawy naprawcze do stacji) chwytakiem, grawitaśmą lub ręcznie.`,"status.38":`Wymaga fazy π`,"status.38.hint":`Włócznia fazowa bierze tylko światło fazy π: poprowadź wiązkę przez przesuwnik fazy.`,"status.39":`Planeta pod ulem`,"status.39.hint":`Rój trzyma tę planetę: wydobycie wstrzymane. Uwolnij ją statkiem lub wieżyczkami orbitalnymi.`,"achv.first_wave.name":`Pierwsza fala`,"achv.first_wave.desc":`Odeprzyj falę Roju.`,"achv.repairman.name":`Złota rączka`,"achv.repairman.desc":`Napraw {n, number} pkt wytrzymałości.`,"achv.nest_breaker.name":`Pogrom gniazd`,"achv.nest_breaker.desc":`Oczyść gniazda Roju: {n}.`,"achv.liberator.name":`Wyzwolenie`,"achv.liberator.desc":`Uwolnij planetę od ula Roju.`,"achv.fortress.name":`Twierdza`,"achv.fortress.desc":`Odeprzyj fale Roju: {n}.`,"swarm.tasks":`Zadania obrony`,"swarm.task.turret":`Postaw wieżyczkę (włócznię lub gatling)`,"swarm.task.wave":`Odeprzyj falę`,"swarm.task.repair":`Napraw {n} pkt wytrzymałości`,"swarm.task.barrier":`Postaw bariery: {n}`,"swarm.task.bay":`Stacja naprawcza`,"swarm.task.nest":`Oczyść gniazdo`,"swarm.task.planet":`Uwolnij planetę od ula`,"guide.swarm-hud":`Gniazdo tutejszych istot zauważyło światło bazy i wysłało oddział. Pasek u góry pokazuje, ilu ich i dokąd. {touch, select, yes {Stuknij} other {Kliknij}} go.`,"guide.swarm-hud.why":`Na najjaśniejsze światło gniazdo wysyła oddziały — by gryzły budynki.`,"guide.swarm-turret":`Postaw wieżyczkę przy celu fali i daj jej światło lub amunicję: chwytakiem, grawitaśmą albo ręcznie.`,"guide.swarm-turret.why":`Wieżyczka strzela, gdy ty budujesz. Czy każda jest potrzebna — pogadamy później.`,"guide.swarm-turret.stuck":`Wieżyczki są w zakładce „Obrona”. Można też statkiem: jego broń strzela sama.`,"guide.swarm-wave":`Rój gryzie budynki. Leć kutrem do nich — laser strzela sam; wieżyczki pomagają.`,"guide.swarm-wave.done":`Fala odeszła. Podsumowanie — w komunikacie u góry.`,"guide.swarm-repair":`Uszkodzone maszyny iskrzą, zniszczone są szkieletami. Otwórz maszynę, naciśnij „Napraw” — wiązka naprawi wszystko wokół.`,"guide.swarm-repair.why":`Nic nie przepada: wrak da się naprawić do całej maszyny. Zestawy naprawcze przyspieszają to czterokrotnie.`,"goal.gate_core":`Postaw rdzeń wrót w starożytnym pierścieniu za zewnętrznym pasem`,"goal.gate_core.why":`Ciemny pierścień za zewnętrznym pasem to starożytne wrota. Rdzeń wchodzi w jego gniazda — i pierścień się budzi.`,"goal.gate_core.hint":`Zbadaj „Teoria wrót” (spektrum B). Montownia buduje rdzeń; można go postawić tylko na ruinach — znacznik pokazuje gdzie.`,"goal.gate_core.done":`Rdzeń na miejscu — wpusty ruin pasują.`,"goal.gate_core.part":`Postaw rdzeń na platformie pierścienia`,"goal.gate_core.mark":`RDZEŃ WRÓT — TUTAJ`,"goal.gate_ring":`Zamknij pierścień: {n, plural, one {# segment} few {# segmenty} many {# segmentów} other {# segmentu}} do rdzenia`,"goal.gate_ring.why":`Każdy segment to krok ku drodze do domu: pierścień Kowali ożywa segment po segmencie i widać go z każdego przybliżenia.`,"goal.gate_ring.hint":`Segmenty buduje montownia: łuki III, rezonatory, spektra B i falowody wrót (falowód to dwie lazurowe soczewki, rezonator i szkło tektytowe w białym spolaryzowanym świetle). Podawaj je do rdzenia chwytakiem albo przyciskiem „Włóż segmenty”. Chwytak z filtrem bierze ze wspólnej grawitaśmy tylko swój przedmiot.`,"goal.gate_ring.done":`Pierścień zamknięty!`,"goal.gate_ring.part":`Segmenty w rdzeniu`,"goal.gate_field":`Utrzymaj pole: {n, plural, one {# stabilizator} few {# stabilizatory} many {# stabilizatorów} other {# stabilizatora}} o różnych właściwościach`,"goal.gate_field.why":`Pierścień otwiera się tylko za zgodą: pole trzyma się na świetle wszystkich właściwości naraz — egzamin ze wszystkiego, co już wiesz o języku Ogrodników.`,"goal.gate_field.hint":`Zbadaj „Stabilizacja pola”. Postaw stabilizatory w promieniu {range} pól od rdzenia; w ich oknie wybierz właściwość: czerwień, polaryzacja, rytm, faza π. Każdy potrzebuje {flux} ph/s takiego światła.`,"goal.gate_field.done":`Pole się trzyma!`,"goal.gate_field.part":`Świecące właściwości`,"goal.gate_charge":`Naładuj {n, plural, one {# akumulator pola} few {# akumulatory pola} many {# akumulatorów pola} other {# akumulatora pola}}`,"goal.gate_charge.why":`Skok wymaga całego światła, które łapie sfera. Za pierścieniem czeka „Exodus” — przy gasnącej gwieździe, na głodowych racjach.`,"goal.gate_charge.hint":`Zbadaj „Akumulatory pola” (wymaga „Powłoka IV”). Postaw je przy rdzeniu; każdy potrzebuje {flux, number} ph/s, poniżej {low} ph/s się nie ładują. Pełne po {full} min.`,"goal.gate_charge.done":`Akumulatory pełne po brzegi. Czterdzieści lat naprawiałem to, co gaśnie. Pierwszy raz ładuję coś, co się zapali.`,"goal.gate_charge.part":`Pełne akumulatory`,"goal.gate_key":`Włóż klucz: po {each, plural, one {# spektrum} few {# spektra} many {# spektrów} other {# spektrum}} z każdej klasy`,"goal.gate_key.why":`Klucz wrót to spektrum każdej klasy, od M do O: wszystko, co odczytano przy Kolebce, w jednej wiązce. Pierścień je rozpozna i otworzy przejście.`,"goal.gate_key.hint":`Dostarcz do rdzenia po {each} spektrów M, K, G, F, A, B i O: chwytakiem albo przyciskiem „Włóż spektra z ekwipunku” w oknie rdzenia. Chwytak stosowy niesie cały stos, a chwytak świetlny przy pylonie jest dwa razy szybszy.`,"goal.gate_key.done":`Klucz w środku! Dziadku, widziałeś? Pierścień świeci wszystkimi naszymi kolorami.`,"goal.gate_key.part":`Spektra klucza`,"goal.gate_jump":`Aktywuj wrota i skocz do domu`,"goal.gate_jump.why":`Dwa miliony ludzi czekają przy przygasłym Ognisku. Wrota otworzą im drogę do żywej gwiazdy — jeśli Ogrodnicy odpowiedzą „tak”.`,"goal.gate_jump.hint":`W oknie rdzenia — „Aktywuj”. Rozruch trwa {spin} min: stabilizatory muszą świecić, a baza rozświetli niebo łuną — przygotuj obronę.`,"goal.gate_jump.done":`Skok!`,"goal.gate_jump.part":`Skok`,"logbook.title":`Dziennik pokładowy`,"logbook.tab.story":`Fabuła`,"logbook.tab.logs":`Zapisy Wery`,"logbook.tab.cast":`Postacie`,"logbook.none":`W tym świecie nie ma kampanii: opowieść toczy się w nowym świecie Kolebki.`,"logbook.empty":`Na razie pusto. Pojawią się tu sceny i kwestie — można je obejrzeć ponownie.`,"logbook.logs":`Znalezione zapisy Wery: {n} z {total}. Kapsuły świecą na niebiesko — podleć tuż do nich.`,"logbook.found":`Znaleziono zapis Wery nr {n} — w „Dzienniku pokładowym”`,"story.skip":`Pomiń`,"story.credits.minutes":`minut w Kolebce`,"story.credits.arcs":`łuków sfery`,"story.credits.logs":`zapisów Wery`,"story.credits.nests":`uśpionych gniazd`,"story.credits.thanks":`Dziękujemy za lot do samego końca.`,"settings.story":`Fabuła`,"settings.story.full":`Pełna`,"settings.story.radio":`Tylko radio`,"settings.story.off":`Bez kwestii`,"gate.title":`Hiperwrota`,"gate.segments":`Pierścień: {n} z {need} segmentów`,"gate.key":`Klucz pełnego spektrum`,"gate.field":`Pole: {n} z {total} właściwości`,"gate.charge":`Akumulatory: pełne {n} z {total}`,"gate.prop.0":`Czerwień`,"gate.prop.1":`Polaryzacja`,"gate.prop.2":`Rytm`,"gate.prop.3":`Faza π`,"gate.activate":`Aktywuj`,"gate.notReady":`Potrzeba: pierścienia, klucza, {field} właściwości pola i {charge} pełnych akumulatorów.`,"gate.spinning":`Rozruch {p} % — utrzymaj stabilizatory w świetle!`,"gate.jumped":`Skok wykonany. Wrota otwarte.`,"gate.putKey":`Włóż spektra z ekwipunku`,"gate.putSegments":`Włóż segmenty`,"gate.stab.prop":`Właściwość światła`,"gate.stab.range":`{yes, select, yes {W polu rdzenia — pracuje dla wrót} other {Poza polem rdzenia: dalej niż {range} pól od jego środka — nie zasila ani pola, ani ładunku}}`,"gate.cap.fill":`Ładunek {p} %`,"cfg.title.gate_stabilizer":`Właściwość światła`,"cfg.gate_stabilizer.0":`Czerwień`,"cfg.gate_stabilizer.1":`Polaryzacja`,"cfg.gate_stabilizer.2":`Rytm`,"cfg.gate_stabilizer.3":`Faza π`,"guide.ora":`ORA · SI STATKU`,"goal.mark.gate":`HIPERWROTA`,"landmark.ruins":`PIERŚCIEŃ KOWALI`,"landmark.ruins.sub":`starożytne wrota`,"landmark.gate":`HIPERWROTA`,"landmark.capsule":`KAPSUŁA`,"landmark.capsule.sub":`stary zapis — podleć bliżej`,"scene.label":`Scena`,"story.log.title":`Zapis {n} · dzień {day}`,"story.credits.sleepers":`I śpiącym, którzy przespali wszystko, co najciekawsze.`,"logbook.tab.world":`Kronika`,"logbook.prologue":`Prolog`,"logbook.scene.prologue":`Podszewka`,"logbook.scene.hab":`Czterdzieści świateł`,"logbook.scene.intruder":`Pasażerka na gapę`,"logbook.scene.first_log":`Zapis w kapsule`,"logbook.scene.confess":`Wyznanie`,"logbook.scene.chorus":`Przekład`,"logbook.scene.protostar":`Pierwsze gniazdo`,"logbook.scene.refrain":`Wzór`,"logbook.scene.token":`Nieśmiertelnik`,"logbook.scene.channel":`Kanał`,"logbook.scene.report7":`Raport nr 7`,"logbook.scene.core":`Rdzeń`,"logbook.scene.matvey_nest":`Matwiej przy gnieździe`,"logbook.scene.spin":`Rozruch`,"logbook.scene.threshold":`Próg`,"settings.textSpeed":`Szybkość tekstu`,"settings.textSpeed.slow":`Wolno`,"settings.textSpeed.normal":`Normalnie`,"settings.textSpeed.fast":`Szybko`,"settings.textSpeed.instant":`Od razu`,"chron.1.when":`−260 lat`,"chron.1":`Przy Ognisku zostaje znaleziony fragment starożytnego pierścienia. Na jego wzór powstają pierwsze Hiperwrota i pierwsza sfera. Zaczyna się Jasny Wiek.`,"chron.2.when":`−230 lat`,"chron.2":`Naszyjnik: wrota przy trzystu gwiazdach. Pierwsze spotkanie z Rojem — „robale gryzą sferę”.`,"chron.3.when":`−215 lat`,"chron.3":`Instytut Przystani ogłasza Kampanię Sanitarną. Gniazda zostają wypalone; układy dostają w katalogu oznaczenie „jasny”.`,"chron.4.when":`−212 lat`,"chron.4":`Ekspedycja „Pierwsze Światło” odnajduje nieznaną żywą gwiazdę — i przepada.`,"chron.5.when":`−211 lat`,"chron.5":`Raport Lund nr 7 trafia do Instytutu. Gwiazdę wymazano z katalogu, raport utajniono.`,"chron.6.when":`−170 lat`,"chron.6":`Pierwsze gwiazdy przygasają. Pojawia się słowo „Gaśnięcie”; przyczyny Instytut nigdy nie podaje.`,"chron.7.when":`−120 lat`,"chron.7":`Naszyjnik się rwie: wrota gasną bez światła, setki kolonii przepadają.`,"chron.8.when":`−90 lat`,"chron.8":`Zamknięto ostatnie wrota. Ludzie zbierają się przy Ognisku i budują Przystań.`,"chron.9.when":`−45 lat`,"chron.9":`Ostatnia czystka sanitarna — układ Jasnej. W ekipie — dwudziestotrzyletni Matwiej Rogow.`,"chron.10.when":`−30 lat`,"chron.10":`Flota „Exodus” — dziewięć tysięcy ludzi — wyrusza do Jasnej. Trasę wyznacza Mira Vent.`,"chron.11.when":`−12 lat`,"chron.11":`Program „Zasiew”: dwanaście szybkich siewników wysłanych ku żywym gwiazdom.`,"chron.12.when":`−1,5 roku`,"chron.12":`„Jaskółka” wyrusza do Jasnej. W kapsule nr 17 — Sonia Vent: matka zdecydowała za nią.`,"chron.13.when":`dzień 547`,"chron.13":`Podszewka. ORA łapie sygnał na częstotliwości, której nie ma w żadnym protokole, i zmienia kurs.`,"guide.lab-place":`Plan Centrum wyciągnąłem z archiwum. Postaw go w ramce — jest na pasku budynków.`,"guide.lab-place.repick":`Weź Centrum Badawcze z paska budynków.`,"guide.lab-place.why":`Centrum odczytuje światło gwiazdy i wydaje nowe plany. Stawiaj ich, ile chcesz — byle było światło.`,"guide.lab-place.done":`Stoi, kochane. Teraz potrzebuje światła.`,"lab.count":`Centra: {n} · odczytuje teraz: {w}`,"lab.none":`Jeszcze nie ma centrów. Postaw Centrum Badawcze z paska budynków — bez niego nauki nie odczytasz.`,"swarm.rules":`Rój żyje od pierwszej minuty. Oczy gniazda: ciemne — nie widzi twojej łuny, żółte — widzi bazę, czerwone — nie śpi. Pierwsze nadchodzą zwiadowcy i nie gryzą; potem fale. Kolce wokół gniazda to jego granica: budowa w środku je budzi, a twój kuter drażni straż. Czyste światło — spokojny Rój.`,"swarm.toast.scout":`Rój cię dostrzegł: jego zwiadowcy lecą to sprawdzić. Nie gryzą — ale za nimi pójdzie fala.`,"swarm.toast.scoutGo":`Zwiadowcy ruszyli.`,"swarm.toast.pact":`Ul odszedł sam: Ogień Zgody zrobił swoje. Planeta jest wolna na dobre.`,"swarm.scout.soon":`Zwiad za {t} · {n}`,"swarm.scout.now":`Zwiad nad bazą · {n}`,"goal.planet_free":`Uwolnij pierwszą planetę`,"goal.planet_free.part":`Uwolnione planety`,"goal.planet_free.why":`Na każdej planecie jest ul Ogrodników. Ziemię dla ludzi trzeba będzie wziąć — albo o nią poprosić.`,"goal.planet_free.hint":`Zdobyć: bij ul bronią kutra albo wieżyczkami orbitalnymi — szybko, ale Rój odpowie falą i może wrócić. Poprosić: „Ogień Zgody” na orbitę — dopóki wokół planety jest czysto, ul odejdzie sam i na zawsze. Wieżyczka orbitalna utrzyma wyzwoloną planetę. Najbliższe ule są młode.`,"goal.planet_free.done":`Planeta jest wolna. Ogrodnicy to widzieli — i jest ich teraz trochę więcej.`,"goal.lab2":`Drugie Centrum i Odblask bez rąk`,"goal.lab2.why":`W archiwum są setki planów, a czas śpiących nie jest nieskończony. Każde Centrum odczytuje własną jednostkę nauki: dwa Centra — dwa razy szybciej.`,"goal.lab2.hint":`Wytwórz Centrum Badawcze ({plates} płyt, {lenses} soczewek, {res} rezonatorów — ze stołu rezonatorów) i postaw tuż obok pierwszego — sąsiedzi dzielą się nauką sami, ale każde potrzebuje własnego światła: poprowadź światłowód do obu. Niech linia niesie Odblask: harpun na kwarc → szlifiernia „Odblask” ← chwytak ze skrzyni płyt; chwytak od szlifierni prosto do Centrum.`,"goal.lab2.done":`Dwa Centra odczytują naraz: archiwum otwiera się dwa razy szybciej. Dalej — po jednym Centrum na każdy nowy stopień.`,"landmark.center":`Centrum Badawcze`,"landmark.center.sub":`centra: {n}`,"track.path":`Ścieżka`,"track.light":`Światło`,"track.matter":`Materia`,"track.logistics":`Logistyka`,"track.defense":`Obrona`,"track.sky":`Niebo`,"tree.reqFar":`{tech} ({track}, jeszcze {n, plural, one {# krok} few {# kroki} many {# kroków} other {# kroku}})`,"settings.handTips":`Karta budynku przy wyborze`,"cryo.title":`Kriokomora · {n} z {total}`,"cryo.open":`Kriokomora: {n} z {total}`,"cryo.panels":`Awaryjne panele modułu utrzymują wszystkie czterdzieści kapsuł. Gdy zapłonie Wieniec, ORA przełączy kriokomorę na światło bazy — będzie potrzebne lazurowe światło (niebieskie wyjście pryzmatu, krótkim światłowodem do modułu) i lód.`,"cryo.cold":`Lazurowe światło dla śpiących: {got} z {need} ph/s`,"cryo.dim":`za słabe — wymagana jasność {b}`,"cryo.wrong":`zły odcień — wymagany lazurowy`,"cryo.ice":`Lód: {n} z {max} — starczy na {m} min`,"cryo.warm":`Ciepłe światło dla przebudzonych: {got} z {need} ph/s`,"cryo.grace":`Komora przyzwyczaja się do twojego światła: {t}`,"cryo.reserve":`Zapas zimna {p}%`,"cryo.seats":`Przebudzeni: {a} · miejsca: {s}`,"cryo.infirmary":`izba chorych {n} z {m}`,"cryo.repair":`Napraw pęknięcie (wiązką)`,"cryo.capsules":`Kapsuły`,"cryo.hint":`Kapsuła to tabliczka z imieniem. Każda nowa klasa spektrum daje jedno miejsce więcej dla obudzonych. Lód — przyciskiem „Włóż lód” albo chwytakiem z grawitaśmy.`,"cryo.tag":`Nr {n} · {name}`,"cryo.state.sleep":`śpi`,"cryo.state.crack":`pęknięcie — napraw moduł`,"cryo.state.alarm":`alarm — za mało zimna`,"cryo.state.thaw":`rozmrażanie`,"cryo.state.awake":`nie śpi`,"cryo.state.lost":`kapsuła zgasła`,"cryo.inInfirmary":`w izbie chorych, czeka na miejsce`,"cryo.wake":`Obudź`,"cryo.rescue":`Ratuj — obudź teraz`,"cryo.noSeat":`Brak miejsc: nowe da następna klasa spektrum`,"cryo.noBed":`Izba chorych jest pełna — tę kapsułę mogą uratować tylko światło i naprawa`,"cryo.cannot":`Tej kapsuły nie da się obudzić`,"cryo.bonus.tetra":`Czyta wzór Roju: +{pct}% obrażeń w jego słaby kolor`,"cryo.bonus.engineer":`+{pct}% naprawy; pęknięcia kapsuł naprawiane bez ciebie`,"cryo.bonus.medic":`Alarmy kapsuł trwają dwa razy dłużej, rozmrażanie jest dwa razy szybsze`,"cryo.bonus.geologist":`+{pct}% szybkości wydobywarek`,"cryo.bonus.optician":`+{pct}% szybkości badań`,"cryo.bonus.pilot":`+{pct}% szybkości i ładowności dronów`,"cryo.bonus.agronomist":`+{pct}% wydajności modułów planet`,"cryo.bonus.fitter":`+{pct}% szybkości chwytaków`,"cryo.bonus.signaller":`−{pct}% łuny bazy`,"cryo.radio.reserve":`Zapas chłodu w kriokomorze spadł poniżej połowy. Daj jej lazurowe światło i lód.`,"cryo.radio.alarm":`Alarm: kapsuła nr {n}, {name}. Za mało zimna — zostało jej {min} min.`,"cryo.radio.crack":`Kapsuła {n} pękła — szron na szkle. Przyleć i napraw moduł wiązką.`,"cryo.radio.lost":`Kapsuła {n} zgasła. {name}. Wybacz mi — i utrzymaj resztę.`,"cryo.radio.seat":`Nowa klasa spektralna — w module jest miejsce dla jeszcze jednego, który się obudzi. Wybierz w kriokomorze.`,"cryo.radio.ice":`Lodu w kriokomorze — na {min} min. Dowieź lód.`,"cryo.radio.wake.engineer":`{name}, inżynier, już na nogach. Mój klucz ma teraz nowe ręce.`,"cryo.radio.wake.medic":`{name}, lekarz, już na nogach. Pierwsze badanie dla Soni, drugie dla mnie. Kazali mi usiąść.`,"cryo.radio.wake.geologist":`{name}, geolog, już na nogach. Spór z ORĄ o pas już się zaczął.`,"cryo.radio.wake.optician":`{name}, optyk, już na nogach. Patrzy na twoje pryzmaty i się uśmiecha.`,"cryo.radio.wake.pilot":`{name}, pilot, już na nogach. Pierwsze pytanie: kto lata dronami?`,"cryo.radio.wake.agronomist":`{name}, agronom, już na nogach. Pierwsze pytanie: są tu jakieś planety z glebą?`,"cryo.radio.wake.fitter":`{name}, monter, już na nogach. Twoje chwytaki są policzone; strojenie obiecane.`,"cryo.radio.wake.signaller":`{name}, łącznościowiec, już na nogach. Mówi, że baza oślepia Rój, i obiecuje ją przyciemnić.`,"cryo.radio.wake.tetra":`Sonia na nogach.`,"goal.cryo":`Kriokomora na twoim świetle: lazurowe światło i lód`,"goal.cryo.hint":`Pryzmat w białej sieci: niebieskie wyjście — światłowodem do modułu (do {cells} pól, jasność {b}). Potrzeba {need, number} ph/s na {sleepers} śpiących. Lód trzyma zimno: jeden blok — na {min} min; dokładaj do modułu do {ice} — „Włóż lód” w jego oknie albo chwytakiem z grawitaśmy.`,"goal.cryo.why":`Awaryjne panele modułu się wyczerpały. Teraz czterdziestu śpiących żyje na twoim świetle: kapsuły potrzebują lazurowego światła i lodu.`,"goal.cryo.done":`Czterdzieści z czterdziestu na świetle bazy. Zapas awaryjny już niepotrzebny — najlepszy wpis w dzienniku od katastrofy.`,"goal.cryo_wake":`Obudź kolonistę: nowe miejsce otwiera Spektroskopia`,"goal.cryo_wake.hint":`Otwórz kriokomorę ({touch, select, yes {stuknij moduł} other {kliknij moduł}}), wskaż kapsułę według zawodu i naciśnij „Obudź”. Obudzeni potrzebują ciepłego światła — czerwonego wyjścia tego samego pryzmatu.`,"goal.cryo_wake.why":`Śpiący to nie ładunek, tylko koloniści: lekarze, inżynierowie, agronomowie. Każdy obudzony pracuje dla bazy, a miejsce dla niego otwiera Spektroskopia.`,"goal.cryo_wake.done":`W module przybyło rąk do pracy.`,"goal.mark.hab":`MODUŁ`,"guide.hab":`{touch, select, yes {Stuknij wrak} other {Kliknij wrak}} modułu mieszkalnego i naciśnij „Napraw moduł”. Wiązka kutra naprawia z {reach} pól — jeśli jesteś za daleko, przysuń się.`,"guide.hab.why":`To oderwany moduł mieszkalny: czterdziestu śpiących i Matwiej Iljicz. Napraw go, a wróci do życia także archiwum planów.`,"guide.hab.look":`Naciśnij „Patrz” (Esc): wtedy {touch, select, yes {stuknięcie} other {kliknięcie}} otwiera budynek zamiast go stawiać.`,"guide.hab.open":`{touch, select, yes {Stuknij wrak} other {Kliknij wrak}} modułu — otworzy się jego okno.`,"guide.hab.done":`Moduł znów żyje.`,"hab.wreck":`Moduł mieszkalny „Jaskółki” z czterdziestoma śpiącymi oderwał się w katastrofie; działa na zasilaniu awaryjnym. Przyleć blisko i napraw go wiązką kutra.`,"hab.repair":`Napraw moduł`,"cfg.title.filter_grabber":`Filtr`,"cfg.filter.any":`Dowolny`,"cfg.filter.anyHint":`Bez filtra bierze każdy przedmiot, który przyjmie cel.`,"cfg.filter.only":`Bierze tylko: {name}.`,"grabber.noPylon":`Brak zasilanego pylonu: zwykła prędkość. W strefie pylonu jest do dwóch razy szybszy.`,"logbook.now.title":`W skrócie`,"logbook.now.none":`Opowieść jeszcze się nie zaczęła: pojawi się tu streszczenie tego, co już się wydarzyło.`,"logbook.now.prologue":`„Jaskółka” wyszła z podszewki nie przy Jasnej, lecz przy nieznanej żywej gwieździe — ORA nazwała ją Kolebką. Statek przeciągnęło przez pas: napęd spadł w gwiazdę, moduł mieszkalny z czterdziestoma śpiącymi i Matwiejem został oderwany. Jesteś na kutrze. Pierwsze zadanie — światło dla kriokomory.`,"logbook.now.hab":`Moduł mieszkalny naprawiony: w kriokomorze płonie czterdzieści świateł. Matwiej jest w module, ORA prowadzi budowę; archiwum „Zasiewu” odblokowuje plany za światło nowych spektrów. Dalej — Centrum Badawcze.`,"logbook.now.intruder":`Wieniec świeci, komora żyje na świetle bazy. Kapsuła nr 17 pękła — obudziła się Sonia, ma szesnaście lat. Twoje lazurowe światło podtrzymuje sen pozostałych trzydziestu dziewięciu.`,"logbook.now.tag":`Komora budzi kolonistów po jednym: nowe miejsce za każde nowe spektrum. Obudzeni potrzebują ciepłego światła, śpiący — lazurowego.`,"logbook.now.first_log":`W pasie znalazła się kapsuła Wery Lund z ekspedycji „Pierwsze Światło”: dwieście dwanaście lat temu oni też nazwali tę gwiazdę Kolebką. Kapsuły świecą na niebiesko — szukaj pozostałych.`,"logbook.now.confess":`ORA się przyznała: w podszewce złapała sygnał i sama odwiodła statek od Jasnej. Powtórzenia w widmie gwiazdy to właśnie ten sygnał.`,"logbook.now.chorus":`Pierwsza fala Roju odparta. ORA przełożyła ich światło: „OŚLEPIA… BOLI”. Łuna bazy ich rani.`,"logbook.now.protostar":`Pierwsze gniazdo uspokoiło się: pod Włócznią zgasło i stało się małą gwiazdą — albo zasnęło, zostawiając pancerze.`,"logbook.now.refrain":`Drony poleciały — gniazda odpowiedziały tym samym wzorem. Czysta baza to spokojny Rój; oślepiają go nie rozmiary bazy, lecz straty i przegrzanie.`,"logbook.now.token":`Matwiej opowiedział o nieśmiertelniku: czterdzieści pięć lat temu wypalał gniazda Roju w układzie Jasnej. Tam też poleciała flota „Exodus” — flota matki Soni.`,"logbook.now.channel":`Czysty kanał z Przystanią. „Exodus” żyje, ale Jasna gaśnie im na oczach. Katalog powiedział prawdę: gasną tylko „jasne” gwiazdy — te, przy których wypalono Rój. Obręcz za pasem to starożytne wrota, Przystań o jeden krok.`,"logbook.now.report7":`Mira odczytała na antenie Przystani raport Lund nr 7: „Rój podtrzymuje puls gwiazdy”. Kanał urwał się od strony Przystani.`,"logbook.now.core":`Rdzeń stanął w starożytnym pierścieniu za zewnętrznym pasem — zbudowali go Kowale. Ostatni zapis Wery: „Nie bierzcie światła. Proście”. Dokończ pierścień.`,"logbook.now.matvey_nest":`Matwiej poszedł do gniazda bez broni — prosić o wybaczenie. Pierścień jest prawie gotowy.`,"logbook.now.spin":`Rozruch: stabilizatory pokazały wzór, po pasach biegną światła. Został próg.`,"logbook.now.threshold":`Pierścień się otworzył: po drugiej stronie — Ognisko, Przystań i znacznik „Exodusu”. Los wrót rozstrzygnął twój wybór.`,"logbook.cast.more":`Ktoś jeszcze czeka na spotkanie.`,"logbook.world.more":`Kronika uzupełnia się w miarę rozwoju historii.`,"logbook.bio.ora.1":`SI siewnika „Jaskółka”. Precyzyjna, z suchym humorem; prowadzi budowę i liczy światło.`,"logbook.bio.ora.2":`Przyznała się: w podszewce złapała sygnał i sama zabrała statek spod Jasnej do Kolebki.`,"logbook.bio.ora.3":`Tłumaczy Rój: ich światło na słowa.`,"logbook.bio.matvey.1":`Inżynier pokładowy, 68 lat. Zrzędzi, naprawia wszystko, co świeci; na szyi — mosiężny nieśmiertelnik.`,"logbook.bio.matvey.2":`Czterdzieści pięć lat temu był sanitariuszem przy ostatniej czystce Roju — w układzie Jasnej.`,"logbook.bio.matvey.3":`Poszedł do gniazda bez broni — prosić o wybaczenie.`,"logbook.bio.sonya.1":`Kolonistka z kapsuły nr 17, 16 lat. Obudziła się przed czasem: kapsuła pękła, gdy komorę przełączano na światło bazy.`,"logbook.bio.sonya.2":`Córka Miry Vent: do kapsuły położyła ją matka.`,"logbook.bio.sonya.3":`Widzi czwarty kolor. Jej rysunki mrugania gniazd zgodziły się z powtórzeniami w świetle gwiazdy; pierwsza odpowiedziała Rojowi „tak”.`,"logbook.bio.mira.1":`Dyspozytorka Przystani. Przebija się przez zakłócenia dalekiej łączności.`,"logbook.bio.mira.2":`Matka Soni.`,"logbook.bio.mira.3":`Trzydzieści lat temu wyznaczyła trasę floty „Exodus” do Jasnej.`,"logbook.bio.mira.4":`Odczytała na antenie Przystani tajny raport Lund — odsunięto ją od pulpitu.`,"logbook.bio.vera.1":`Ksenolingwistka ekspedycji „Pierwsze Światło”, 212 lat temu. Jej zapisy leżą w kapsułach rozsianych po pasach.`,"logbook.bio.vera.2":`Odmówiła wypalania gniazd, odesłała załogę do domu — i została.`,"logbook.bio.vera.3":`Powstrzymała uruchomienie pierścienia Kowali.`,"logbook.bio.chorus.1":`Rój: gniazda w pasach. Mówi światłem — kolorem, rytmem, fazą; ORA tłumaczy. Łuna ich oślepia.`,"logbook.bio.chorus.2":`Ogrodnicy gwiazd: podtrzymują puls gwiazdy. Gdzie Rój wypalono, gwiazda gaśnie.`,"logbook.bio.keeper.1":`Ty. Strażnik „Jaskółki”: czuwasz w czasie lotu i budujesz wrota. Dom — Przystań; przed Kolebką nie było ci dane zobaczyć żywej gwiazdy.`,"chron.0.when":`≈ −40 000 lat`,"chron.0":`Kowale budują pierścień przy Kolebce. Brali światło od gwiazd siłą — i zgaśli.`,"chron.1b":`Przy Ognisku zostaje znaleziony fragment pierścienia Kowali. Na jego wzór powstają pierwsze Hiperwrota i pierwsza sfera. Zaczyna się Jasny Wiek.`,"chron.4b":`Ekspedycja „Pierwsze Światło” odnajduje żywą gwiazdę z nienaruszonym pierścieniem Kowali — i przepada.`,"chron.6b":`Przygasają pierwsze „jasne” gwiazdy — te, przy których wypalono Rój. Instytut nazywa to Gaśnięciem, a przyczyny nie podaje.`,"logbook.scene.tag":`Plakietka`,"settings.keepBuildTool":`Zachowaj wybrany budynek`,"settings.keepBuildTool.hint":`Wyłączone: po postawieniu ręka się opróżnia, a {touch, select, yes {stuknięcie} other {kliknięcie}} w pustkę niczego nie dobuduje. Włącz, by stawiać rzędy jeden po drugim.`,"toast.shipDown":`Kuter jest rozbity. Cały twój ładunek został we wraku, tam gdzie spadł — zaznaczony na kompasie. Nowy kuter składa się przy module mieszkalnym.`,"toast.wreckTaken":`Ładunek z wraku kutra wrócił do twojego ekwipunku.`,"compass.wreck":`Wrak{nest, select, yes { · przy gnieździe} other {}} · {n} pól`,"compass.wreckLabel":`Wrak kutra z twoim ładunkiem{nest, select, yes {, przy gnieździe} other {}}, {n} pól`,"compass.wreckFly":`Przyleć do wraku, by odzyskać ładunek{nest, select, yes {. Uwaga: gniazdo jest blisko, jego straż znów spotka kuter} other {}}`,"card.usedMore":`Jeszcze {n}`,"inv.lockedLater":`Odblokowane później ({n})`,"machine.removeConfirm":`Na pewno wyburzyć?`,"card.handTime":`Ręcznie: {s} s`,"ship.recall.go":`Do Centrum`,"ship.recall.wait":`Do Centrum · {s} s`,"hud.craftQueue":`Kolejka wytwarzania: {n}. Otwórz ekwipunek`,"hud.craftMore":`…+{n}`,"hud.swarm.raid":`Baza atakowana · {n}`,"toast.raid":`Rój gryzie bazę! Plakietka Roju prowadzi na miejsce — wieżyczki i naprawa.`,"toast.nestRage":`Królowa wpadła w szał: wartowników jest więcej i są szybsi.`,"settings.raidAlarm":`Alarm nalotu`,"settings.raidAlarm.full":`Pełny`,"settings.raidAlarm.edge":`Krawędź ekranu`,"settings.raidAlarm.off":`Tylko plakietka`,"guide.via.tool-more":`Naciśnij „Więcej” (trzy kropki w prawej kolumnie) — potrzebny przycisk jest tam.`,"guide.via.tool-inventory":`Otwórz Ekwipunek — to, czego trzeba, jest w jego oknie.`,"guide.via.tool-lab":`Otwórz Centrum — potrzebny przycisk jest w jego oknie.`,"guide.via.tool-ship":`Otwórz okno „Statek” — tam jest to, czego trzeba.`,"guide.stuck.place":`Czerwone widmo — miejsce zajęte albo zły obrót. Brak budynku — wytwórz w „Ekwipunku”. Kuter doleci sam.`,"guide.stuck.fly":`Nie widać znacznika? Wskazuje go strzałka na krawędzi ekranu — leć za strzałką.`,"guide.mine.stuck":`Kwarc nie leci? Wybierz niebieskie skały pasa tuż przy znaczniku — kuter musi być blisko nich.`,"guide.recipe.stuck":`Okno się nie otwiera? Naciśnij „Patrz”, potem szlifiernię — „Soczewka” jest na liście w jej oknie.`,"guide.hab.stuck":`Moduł za daleko? Przysuń się: wiązka naprawia z {reach} pól. Okno modułu otwiera {touch, select, yes {stuknięcie} other {kliknięcie}} w trybie „Patrz”.`,"guide.ship-shot.stuck":`Nie ma meteorytów? Przelatują co parę minut. Doleć do jasnej skały — laser strzeli sam.`,"goal.partDone":`Gotowe: {part}. Teraz — {next}: {have}/{need}.`,"goal.obsidian.part":`Harpun przy pomarańczowych skałach złapał skałę`,"goal.plates.part":`Czwarty harpun — wyjściem do szlifierni płyt`,"cryo.ask.crack":`Kapsuła {n} pękła — poleć do modułu i napraw go wiązką.`,"cryo.ask.reserve":`Zapas chłodu w komorze spadł poniżej połowy — daj śpiącym lazurowe światło i lód.`,"cryo.ask.ice":`Lodu w kriokomorze na {min} min — dowieź lód (meteoryty, komety).`,"guide.aside":`Radio`,"guide.aside.next":`{touch, select, yes {Stuknij} other {Kliknij}} — dalej`,"goal.obsidian.stuck":`Brak płyt? Otwórz szlifiernię płyt: receptura to „Płyta obsydianowa”; ikona nad maszyną mówi, czego brakuje — światła (łuk i światłowód) czy skały (wyjście harpuna prosto do niej).`,"goal.plates.stuck":`Płyty idą wolno? Szlifiernia płyt potrzebuje {light} ph/s światła — rzuć jeszcze jeden łuk; czwarty harpun idzie wyjściem prosto do niej.`,"guide.via.close":`Zamknij okno (krzyżyk) — to, czego trzeba, jest pod spodem.`,"logbook.scene.embers":`Żar`,"logbook.scene.umbrella":`Parasol`,"logbook.scene.night":`Noc Bliźniąt`,"logbook.scene.veil":`Sama z siebie`,"logbook.scene.count":`Rachunek`,"logbook.scene.forge":`Kuźnia`,"logbook.now.embers":`Pięć żarów: trzy z „Pierwszego Światła”, dwieście dwanaście lat; dwa młode, osiem lat — ślady „Jerzyka”.`,"logbook.now.umbrella":`Szafir. Szron w pasie układa się w kratę: Rój daje błękitnemu olbrzymowi cień, żeby płonął dłużej. Niewód bierze z brzegu — tyle, ile trzeba radiatorom.`,"logbook.now.night":`Bliźnięta. Pierwsza noc przetrwana na akumulatorach. Sonia zapytała mamę, czemu ją wysłała: „Żebyś miała poranek”. Dalej — spektra w świetle dwóch gwiazd.`,"logbook.now.veil":`Welon. Kwarc z mgły popłynął. Gwiazda umarła tu sama, bez niczyjej winy; z jej mgiełki narodzą się kiedyś nowe. Dalej — soczewki i spektra bez stałego gruntu.`,"logbook.now.count":`Pulsar Keplera. W pulsie są luki: Roje wielu gwiazd zestrajają z nim wzory, a każda luka to ogród, który przestał odpowiadać. Wera naliczyła trzy, ORA — sto dwanaście.`,"logbook.now.forge":`Horyzont. Kuźnię przy czarnej dziurze zbudowali ci, którzy zapalali gwiazdy siłą — i pękła. Siedem klas zebranych; relikwie to wzory ogrodów. Gwiazdę zapala się prośbą: trzy relikwie, siedem spektrów i antyświatło.`,"logbook.slogs":`Znalezione zapisy Wery w tym układzie: {n} z {total}. Boje świecą na niebiesko — podleć tuż do nich.`,"landmark.buoy":`BOJA`,"goal.twin_night.stuck":`Gaśnie w nocy? Akumulator stoi między odbiornikiem a maszynami i trzyma jedną barwę. Czerwone „N s” w panelu Doby oznacza, że zapas się skończy: dodaj jeszcze jeden akumulator.`,"goal.twin_relic.stuck":`{n} w dzień, a pod koniec nocy mniej? Liniom spektrów brakuje akumulatorów światła — sprawdź „N s” w panelu Doby.`,"hud.day":`Doba`,"hud.day.star.twin_amber":`Bursztynowa`,"hud.day.star.twin_blue":`Błękitna`,"hud.day.night":`Noc`,"hud.day.toNight":`zachód za {t}`,"hud.day.toStar":`{star} za {t}`,"hud.day.toDawn":`świt za {t}`,"hud.cells":`Akumulatory`,"hud.cells.for":`{color} — na {s} s`,"hud.cells.filling":`{color} — ładuje się`,"hud.cells.short":`nie starczy do wschodu`,"hue.0":`bez koloru`,"hue.1":`szkarłatny`,"hue.2":`szmaragdowy`,"hue.3":`bursztynowy`,"hue.4":`lazurowy`,"hue.5":`purpurowy`,"hue.6":`turkusowy`,"hue.7":`biały`,"cell.charge":`Ładunek {n} / {cap} ph`,"cell.out":`Oddaje {f} ph/s — starczy na {s} s`,"cell.idle":`Ładuje się: maszyny za nim nie pobierają światła`,"cell.hue":`Pamięta kolor: {color}`,"cell.hue.none":`Kolor niezapamiętany — przyjmie pierwszy, który dotrze`,"cell.forget":`Zapomnij kolor`,"hud.cells.chip":`akumulatory {s} s`,"bonus.ship_damage":`+{v}% obrażeń broni statku`,"bonus.ship_power":`+{v}% mocy generatora statku`,"bonus.turret":`+{v}% obrażeń wieżyczek`,"bonus.hull":`+{v}% wytrzymałości budynków`,"bonus.barrier":`+{v}% wytrzymałości barier`,"bonus.ammo":`+{v}% obrażeń pocisków i rakiet`,"bonus.beam":`+{v}% obrażeń wieżyczek promieniowych`,"bonus.repair":`+{v}% szybkości napraw`,"bonus.dome":`+{v}% pojemności kopuły ochronnej`,"bonus.chain":`+{n} do celów łuku łańcuchowego`,"bonus.orbital":`+{v}% obrażeń wieżyczek orbitalnych`,"bonus.radar":`+{v}% czasu ostrzeżenia radaru`,"bonus.lore":`+{v}% obrażeń przeciw słabemu kolorowi`,"cryo.putIce":`Włóż lód ({n})`,"machine.putHalf":`Połowę`,"hint.prism.16":`Wolne wyjście świeci w pustkę — to łuna, a sąsiedzi z jego sieci mają za mało bieli. Podłącz światłowód do każdego wyjścia albo dosuń do niego maszynę (lub pochłaniacz) wejściem.`,"toast.shieldLow":`Tarcza słaba — uciekaj od gradu i Roju!`,"status.prism.16":`Traci światło: wolne wyjście`,"goal.lab2.part":`Odblask do Centrum linią (nie ręcznie)`,"goal.catapult.part":`Pierwszy łuk wystrzelony`,"toast.damaged":`Rój uszkodził budynki: {n}. Łańcuchy za nimi staną.`,"toast.damagedFix":`Napraw najbliższy`,"goal.asks.more":`jeszcze próśb: {n} — {touch, select, yes {stuknij kartę} other {kliknij kartę}}`,"hud.cryo.lead":`Komora: lód na {m} min`,"hud.cryo.alarm":`Komora: alarm kapsuły!`,"toast.cryoLow":`Kriokomora: chłodu na {m} min. Włóż lód — albo poprowadź chwytak z lodem prosto do komory.`,"toast.cryoOpen":`Otwórz komorę`,"hotbar.groups":`Grupy budynków`,"hotbar.group.logic":`Logika`,"hotbar.group.fluid":`Płynne światło`,"hotbar.group.resonance":`Rezonans`,"toast.netClash":`Sieci różnych barw połączyłyby się tu — interferencja i obie stają. Zostaw puste pole między nimi.`,"guide.lay-tunnel.reverseRemove":`Grawitaśma biegnie w złą stronę. Weź „Wyburz”, usuń ją i narysuj jeszcze raz — od brzegu ramki przy harpunach.`,"lab.reading":`Odczyt jednostki {k}/{n} · jeszcze {s} s`,"lab.waitingLab":`Czeka na spektra: każde Centrum potrzebuje pełnej jednostki — po sztuce każdego stopnia. Przynieś naukę albo doprowadź do Centrum linię: grawitaśmę i chwytak.`,"lab.asked":`Przyjęto: {tech} — Centrum bierze się do pracy…`,"toast.researchStart":`Rozpoczęto badanie: {tech}`,"toast.researchOpen":`Centrum`,"map.title":`Mapa układu`,"key.map":`Mapa układu`,"map.layers":`Warstwy mapy`,"map.layer.swarm":`Rój`,"map.layer.base":`Baza`,"map.layer.planets":`Planety`,"map.layer.logs":`Zapisy`,"map.layer.wrecks":`Wraki`,"map.layer.tunnels":`Grawitaśmy`,"map.hint":`Przeciągaj myszą, przybliżaj kółkiem; kliknij, by wybrać miejsce.`,"map.far":`{n, plural, one {# pole} few {# pola} many {# pól} other {# pola}} od kutra`,"map.fog":`niezbadane — doleć tam lub postaw radar`,"map.fly":`Leć tutaj`,"map.center":`Do kutra`,"map.zoomIn":`Przybliż`,"map.zoomOut":`Oddal`,"compass.fog":`we mgle`,"compass.fogHint":`Niezbadane: poleć tam — kuter rozwieje mgłę — albo zbuduj radar. {touch, select, yes {Stuknij} other {Kliknij}}, by lecieć.`,"goal.radar":`Radar: mgła ustępuje`,"goal.radar.why":`Za dalekimi pasami leży mgła: gniazda Roju i planety, na których kiedyś zamieszkają koloniści. Radar czuwa za ciebie i wcześniej widzi fale.`,"goal.radar.hint":`Zbadaj „Radar” w Centrum (gałąź „Obrona”, spektrum K) i postaw go na skraju bazy. Światło — światłowodem albo tuż przy wyjściu odbiornika: radar odsłania mgłę na {sight} pól wokół. Cały układ widać na mapie (przycisk „Mapa układu”).`,"goal.radar.done":`Radar czuwa nad mgłą — gniazda i fale pokazują się wcześniej.`,"goal.radar.part":`Radar w świetle`,"map.hint.touch":`Przeciągaj palcem, rozsuwaj palce, by przybliżyć; stuknij, by wybrać miejsce.`,"swarm.look":`Znak na grzbiecie wartowników to kolor fali: trójkąt — szkarłatny, koło — szmaragdowy, romb — lazurowy. Światło w światłowodach ma te same kształty.`,"ship.hull.4":`„Kosa”`,"ship.hull.5":`„Zenit”`,"ship.class.1":`Zwiadowca`,"ship.class.2":`Przechwytywacz`,"ship.class.3":`Fregata`,"ship.class.4":`Korsarz`,"ship.class.5":`Flagowiec`,"ship.line.beam":`Wiązka`,"ship.line.kinetic":`Kinetyka`,"ship.line.star":`Gwiazda`,"ship.line.depths":`Głębiny`,"ship.line.wing":`Skrzydło`,"ship.line.beam.bonus":`energia strzału −{p}%`,"ship.line.kinetic.bonus":`magazynek +{p}%`,"ship.line.star.bonus":`moc generatora +{p}%`,"ship.line.star.bonus2":`moc generatora +{p}%, żar −{h}%`,"ship.line.depths.bonus":`uzysk z ciała +{p}%, zbiór +{c, plural, one {# pole} few {# pola} many {# pól} other {# pola}}`,"ship.line.wing.bonus":`obrażenia drona +{p}%, naprawa +{r}%`,"ship.tab.ship":`Statek`,"ship.tab.stats":`Parametry`,"ship.tab.grow":`Rozwój`,"ship.tab.look":`Wygląd`,"ship.slot.locked":`Odblokuje kadłub {hull}`,"ship.empty.hint":`Pasuje tutaj:`,"ship.empty.craft":`{name} — wytwórz w ekwipunku lub w montowni`,"ship.empty.tech":`{name} — odblokuje „{tech}”`,"ship.main.damage":`Obrażenia wg Mk`,"ship.main.speed":`Prędkość wg Mk`,"ship.main.shield":`Tarcza wg Mk`,"ship.main.output":`Moc wg Mk`,"ship.main.collect":`Zbiór wg Mk`,"ship.main.mine":`Wydobycie wg Mk`,"ship.main.warn":`Wzrok wg Mk`,"ship.main.escort":`Obrażenia drona wg Mk`,"ship.main.repair":`Naprawa wg Mk`,"ship.main.heat":`Żar wg Mk`,"ship.main.recall":`Odnowienie wg Mk`,"ship.main.battery":`Bateria wg Mk`,"ship.unit.damage":`{v, number}`,"ship.unit.speed":`{v, number} pól/s`,"ship.unit.shield":`{v, number}`,"ship.unit.output":`{v, number} E/s`,"ship.unit.collect":`{v, number} pól`,"ship.unit.mine":`{v, number}%`,"ship.unit.warn":`×{v, number}`,"ship.unit.escort":`{v, number}`,"ship.unit.repair":`{v, number}%`,"ship.unit.heat":`−{v, number}%`,"ship.unit.recall":`{v, number} s`,"ship.unit.battery":`+{v, number} E`,"ship.group.move":`Ruch`,"ship.group.move.by":`Zmieniają to: silnik i jego Mk, poziom kadłuba.`,"ship.group.shield":`Tarcza`,"ship.group.shield.by":`Zmieniają to: tarcza i jej Mk, radiator, poziom kadłuba, podwójny komplet Gwiazdy. Ciepło, uderzenie i ukąszenie to udziały w obrażeniach.`,"ship.group.energy":`Energia`,"ship.group.energy.by":`Zmieniają to: generator, bateria, poziom kadłuba, komplety Gwiazdy i Wiązki.`,"ship.group.weapons":`Broń`,"ship.group.weapons.by":`Zmieniają to: broń i jej Mk, poziom kadłuba, badania obrażeń, komplety Wiązki i Kinetyki.`,"ship.group.mine":`Wydobycie`,"ship.group.mine.by":`Zmieniają to: laser górniczy, ładownia, komplet Głębin.`,"ship.group.utils":`Wyposażenie`,"ship.group.utils.by":`Zmieniają to: skaner, naprawiacz, latarnia powrotu, komplet Skrzydła.`,"ship.group.sets":`Komplety linii`,"ship.sets.none":`Jeszcze nie ma kompletów: moduły jednej linii w różnych gniazdach dają premię.`,"ship.sets.next":`w komplecie: {b}`,"ship.sets.rule":`{a} modułów jednej linii tworzy komplet, {b} — podwójny komplet; działają dwa najlepsze komplety.`,"ship.gun.escort":`Dron eskorty`,"ship.gun.line":`obr. {d, number} · {r, number} strz./s · {range} pól · {dps, number}/s`,"ship.stat.accel":`Przyspieszenie`,"ship.stat.boost":`Dopalacz, ×`,"ship.stat.regenDelay":`Opóźnienie tarczy, s`,"ship.stat.heat":`Żar, %`,"ship.stat.kinetic":`Uderzenie skały, %`,"ship.stat.dark":`Ukąszenie Roju, %`,"ship.stat.guns":`Lufy`,"ship.stat.nest":`Na gniazda, %`,"ship.stat.mine":`Szybkość wydobycia, %`,"ship.stat.yield":`Uzysk z ciała, %`,"ship.stat.sight":`Zasięg wzroku, pola`,"ship.stat.repair":`Naprawa, %`,"ship.stat.recall":`Powrót, s`,"ship.grow.line":`Linia kadłubów`,"ship.grow.current":`obecny`,"ship.grow.slots":`Sloty: {n}`,"ship.grow.slot":`Nowy slot {n}: {slot}`,"ship.grow.tech":`Technologia {tech}:`,"ship.grow.done":`zbadana`,"ship.grow.open":`dostępna`,"ship.grow.locked":`wymaga wcześniejszych`,"ship.grow.toTree":`Do drzewa`,"ship.grow.max":`Szczyt linii — twój flagowiec jest kompletny.`,"ship.tasks.tier":`Zadania kadłuba {hull}`,"ship.trait.base":`Lekki zwiadowca: szybki w budowie, mało miejsca na moduły.`,"ship.trait.move":`prędkość +{p}%`,"ship.trait.accel":`przyspieszenie +{p}%`,"ship.trait.boost":`dopalacz tańszy o {p}%`,"ship.trait.capacity":`tarcza +{p}%`,"ship.trait.range":`zasięg broni +{c, plural, one {# pole} few {# pola} many {# pól} other {# pola}}`,"ship.trait.damage":`obrażenia +{p}%`,"ship.trait.battery":`bateria +{p}%`,"ship.trait.nest":`na gniazda i ule +{p}%`,"ship.trait.main":`prędkość, tarcza, moc i obrażenia +{p}%`,"ship.trait.sets":`komplet od {a} modułów, podwójny od {b}`,"ship.task.set":`Zbierz komplet: moduły jednej linii — {n}`,"ship.task.slotsFull":`Zajmij wszystkie sloty kadłuba`,"ship.task.coreMark2":`Wszystkie moduły rdzenia ({n}) — Mk II`,"ship.task.set2":`Dwa komplety naraz`,"ship.task.mark3":`Moduł Mk III`,"ship.task.nest":`Zniszcz gniazdo lub ul bronią statku`,"ship.task.loadout":`Zapisz zestaw wyposażenia`,"ship.task.set5":`Podwójny komplet`,"ship.task.allMark3":`Wszystkie sloty — Mk III`,"ship.task.name":`Nadaj statkowi nazwę`,"ship.look.paint":`Farba`,"ship.look.trim":`Wykończenie`,"ship.look.pattern":`Wzór`,"ship.look.flame":`Płomień dysz`,"ship.look.name":`Nazwa statku`,"ship.look.name.ph":`Bez nazwy`,"ship.look.name.save":`Nazwij`,"ship.flame.engine":`Wg silnika`,"ship.flame.1":`Turkusowy`,"ship.flame.2":`Pomarańczowy`,"ship.flame.3":`Purpurowy`,"ship.flame.4":`Zielony`,"ship.flame.5":`Fioletowy`,"ship.flame.6":`Złoty`,"ship.paint.steel":`Stal`,"ship.paint.graphite":`Grafit`,"ship.paint.crimson":`Karmazyn`,"ship.paint.cobalt":`Kobalt`,"ship.paint.jade":`Nefryt`,"ship.paint.bronze":`Brąz`,"ship.paint.violet":`Fiolet`,"ship.paint.ivory":`Kość słoniowa`,"ship.color.0":`Turkusowy`,"ship.color.1":`Bursztynowy`,"ship.color.2":`Purpurowy`,"ship.color.3":`Zielony`,"ship.color.4":`Fioletowy`,"ship.color.5":`Szkarłatny`,"ship.color.6":`Złoty`,"ship.color.7":`Ciepła biel`,"ship.pattern.none":`Brak`,"ship.pattern.stripes":`Pasy`,"ship.pattern.chevrons":`Szewrony`,"ship.pattern.blade":`Ostrze`,"ship.pattern.teeth":`Zęby`,"ship.pattern.sunedge":`Słoneczna krawędź`,"ship.loadouts":`Zestawy wyposażenia`,"ship.loadouts.locked":`Zestawy wyposażenia odblokowuje kadłub {hull}, gdy pojawia się wybór.`,"ship.loadout.n":`Zestaw {n}`,"ship.loadout.empty":`pusty`,"ship.loadout.missing":`brakuje: {n}`,"ship.loadout.save":`Zapisz`,"ship.loadout.apply":`Zastosuj`,"ship.upgrade":`Nowy kadłub: {cls} {hull}`,"ship.upgrade.more":`{slot} · {trait}`,"ship.sets.idle.wing":`nieaktywny: wymaga drona eskorty lub naprawczego`,"ship.sets.idle.kinetic":`nieaktywny: wymaga broni na amunicję`,"ship.sets.idle.beam":`nieaktywny: wymaga broni energetycznej`,"ship.sets.idle.star":`nieaktywny`,"ship.sets.idle.depths":`nieaktywny`,"ship.look.trail":`Smuga`,"ship.trail.same":`Jak płomień`,"ship.grow.state.cur":`obecny`,"ship.grow.state.done":`ukończony`,"ship.grow.state.next":`dostępny`,"ship.grow.state.locked":`zablokowany`,"tech.extraCost":`{item}: masz {have} z {need} — pobrane przy dodaniu do kolejki`,"tech.extraCost.where":`Rdzenie noszą tylko komety, a te przelatują rzadko: rozbij kometę i zbierz żarzący się odłamek.`,"tech.extraCost.short":`Potrzeba: {item} ×{need}, masz {have}. Komety przelatują rzadko — rozbij jedną i zbierz jej rdzeń.`,"comet.toast":`Kometa! Rozbij ją — jej rdzeń kryje rzadki surowiec na kadłuby statku.`,"saves.failed":`Nie udało się zapisać — ponowię próbę`,"saves.restored":`Ostatni zapis był uszkodzony — świat przywrócono z: {from}, o {min} min gry wcześniej`,"saves.unreadable":`Nie da się odczytać zapisów tego świata. Świat nie został usunięty: być może odczyta go zaktualizowana wersja gry.`,"saves.kind.auto":`Autozapis`,"saves.kind.pause":`Przy wyjściu`,"saves.kind.manual":`Ręczny`,"saves.kind.backup":`Kopia zapasowa`,"saves.title":`Zapisy`,"saves.open":`Zapisy świata`,"saves.load":`Wczytaj`,"saves.loadTitle":`Wczytać ten zapis?`,"saves.loadText":`Świat wróci do „{slot}” ({time} gry). Obecny stan zostanie jako autozapis.`,"saves.delete":`Usuń zapis`,"saves.deleteText":`Usunąć ręczny zapis „{time}”?`,"saves.empty":`Brak zapisów`,"saves.hint":`Autozapis co {sec} s, {n} w rotacji. „Przy wyjściu” — gdy gra idzie w tło. „Ręczny” — przycisk Zapisz, do {max}.`,"saves.export":`Eksportuj świat`,"saves.import":`Importuj świat`,"saves.exported":`Plik świata gotowy`,"saves.exportFailed":`Nie udało się wyeksportować świata`,"saves.imported":`Dodano świat „{name}”`,"saves.importFailed":`To nie jest plik świata Heliohold albo jest uszkodzony`,"saves.importLegacy":`Świat z bardzo starej wersji gry (sprzed pasów i spektrów) — nieobsługiwany`,"saves.importName":`{name} (import)`,"saves.status.ago":`Zapisano · {ago}`,"saves.status.saving":`Zapisywanie…`,"saves.status.failed":`Nie zapisano`,"saves.status.never":`Jeszcze nie zapisano`,"saves.cloud.on":`Kopia w chmurze · {ago}`,"saves.cloud.over":`Brak kopii w chmurze — za mało miejsca`,"saves.cloud.conflictTitle":`Dwie wersje świata`,"saves.cloud.conflictText":`W „{name}” grano zarówno tu, jak i na innym urządzeniu. Którą wersję chcesz kontynuować? Druga zostanie jako zapis ręczny.`,"saves.cloud.here":`To urządzenie`,"saves.cloud.other":`Inne urządzenie`,"saves.cloud.pick":`Kontynuuj tę`,"saves.cloud.taken":`Przejęto zapis z chmury — świat był kontynuowany na innym urządzeniu`,"saves.cloud.goals":`cele: {n}`,"logbook.scene.threat":`Pierwsze zagrożenie`,"logbook.now.threat":`W dalekim pasie ożyło gniazdo Roju — żywych istot, które budzi jasne światło. Oddział leci na bazę. Przepędź go kutrem.`,"logbook.scene.threat_after":`Po nalocie`,"logbook.now.threat_after":`Oddział odleciał. Rój zapytał światłem: „KTO?”. Na razie odpowiada laser; w archiwum jest wieżyczka Włócznia. A do tego czasu — równiejsze światło: rośnij, ale nie oślepiaj.`,"logbook.scene.first_wave":`Pierwsza fala`,"logbook.now.first_wave":`Gniazdo zebrało prawdziwą falę. Wieżyczki — na cel, kuter — w powietrze.`,"logbook.scene.still":`Puste pasy`,"logbook.now.still":`Światło bazy wzrosło czterokrotnie. Sąsiadów w pasach brak — tylko kamienie i lód; budujemy porządnie z przyzwyczajenia.`,"logbook.scene.seventh":`Siódma`,"logbook.now.seventh":`Matwiej macha kubkiem z iluminatora: do „Zasiewu” zgłosił się sam — żeby zobaczyć żywą gwiazdę.`,"logbook.scene.leg":`Noga`,"logbook.now.leg":`Matwiej nie pozwala zdjąć z siebie grodzi, dopóki śpiący potrzebują światła. ORA spiera się z nim według procedury.`,"logbook.scene.colors":`Pierwsze kolory`,"logbook.now.colors":`Pryzmat rozszczepił światło na szkarłat, szmaragd i lazur. W Przystani światło jest na przydział, a kolor — na kartki; tu światła jest pod dostatkiem i kolor staje się narzędziem. Bursztyn zmieszamy sami.`,"logbook.scene.dark_ring":`Ciemny pierścień`,"logbook.now.dark_ring":`Za zewnętrznym pasem — ogromny pierścień w bruzdach jak gwint. Nie nasz, bardzo stary. Niech na razie leży.`,"logbook.scene.amber":`Bursztyn`,"logbook.now.amber":`Pierwszy kolor zrobiony własnymi siłami — bursztyn, ładunek Włóczni. Matwiej zna recepturę Włóczni na pamięć i obraca w palcach nieśmiertelnik.`,"logbook.scene.twelve":`Dwanaście siewników`,"logbook.now.twelve":`Dziennik „Zasiewu”: dwanaście siewników, „Jaskółka” jest siódma; od pozostałych ani słowa.`,"logbook.scene.erased":`Wymazana gwiazda`,"logbook.now.erased":`Ani ekspedycji „Pierwsze Światło”, ani tej gwiazdy nie ma w katalogu Instytutu — wyczyszczono je. Wera Lund coś znalazła.`,"logbook.scene.first_spectrum":`Pierwsze spektrum`,"logbook.now.first_spectrum":`Centrum odczytało klasę M — pierwszy z siedmiu zamków archiwum. Gwiazda mrugnęła dwie sekundy po odczycie. ORA na razie nazywa to zbiegiem okoliczności.`,"logbook.scene.tags":`Plakietki`,"logbook.now.tags":`ORA ponownie odczytała plakietki czterdziestu kapsuł. Nr 17 — Sonia Vent, szesnaście lat, córka Miry, dyspozytorki Przystani.`,"logbook.scene.course":`Kurs`,"logbook.now.course":`Matwiej zapytał, jak „Jaskółka” minęła się z Jasną. ORA po raz pierwszy powiedziała: „Ja… przeliczę”.`,"logbook.scene.spear":`Włócznia`,"logbook.now.spear":`Włócznia stoi — pierwsza obrona bazy. Matwiej wie, gdzie uderzyć: „pod trzeci segment”. Skąd — „gdzieś czytałem”.`,"logbook.scene.eyes":`Oczy`,"logbook.now.eyes":`Sonia widzi kolor, którego nie łapią kamery: jest tetrachromatką. ORA porównuje jej rysunki — wygląda na to, że Sonia widzi więcej.`,"logbook.scene.shell2":`Kanał Przystani`,"logbook.now.shell2":`Powłoka II dała moc — głos Miry dociera wyraźniej, ale ona nas nie słyszy. Potrzebny promień do domu — Dalekie włókno.`,"logbook.scene.grandpa":`Dziadek`,"logbook.now.grandpa":`Sonia pierwszy raz nazwała Matwieja dziadkiem. Spodobało mu się.`,"logbook.scene.withdrawn":`Doliczę`,"logbook.now.withdrawn":`ORA na minutę pogrążyła się w obliczeniach: spektrum G rozłożyło powtórzenia w świetle gwiazdy. Obiecała powiedzieć coś ważnego — „nie teraz”.`,"logbook.scene.hunter":`Łowca`,"logbook.now.hunter":`Matwiej zna gniazda lepiej niż archiwum ORY. Sonia to zauważyła; obiecał opowiedzieć — nie dziś.`,"logbook.scene.refusal":`Odmowa`,"logbook.now.refusal":`Zapiski Wery: odmówiła palenia gniazd i odesłała załogę do domu. Jej raport nr 7 Instytut ukrył.`,"logbook.scene.rhythm":`Szkicownik`,"logbook.now.rhythm":`Spektrum F to rytm. Sonia pokazała szkicownik: migotanie gniazd zgadza się z powtórzeniami w świetle gwiazdy — to język. Matwiej rozpoznał wzór.`,"logbook.scene.name":`Imię`,"logbook.now.name":`Rój pamięta imię Wery od ponad dwustu lat. „Jak świecimy, tak nas zapamiętają” — mówi ORA.`,"logbook.scene.yes":`Tak`,"logbook.now.yes":`Pierwsza rozmowa: Rój zapytał światłem „TAK?”, Sonia odpowiedziała lampą — fazą π. „TAK”.`,"logbook.scene.tea":`Herbata`,"logbook.now.tea":`Sonia przyniosła Matwiejowi herbatę. „Wszyscy wiedzieli, że gniazda gasną — po prostu nie patrzyli”. Teraz on patrzy.`,"logbook.scene.clear_word":`Jasna`,"logbook.now.clear_word":`W katalogu Instytutu „jasna” stoi przy układach, przez które przeszła kampania sanitarna. ORA zaczyna sprawdzać, które gwiazdy gasną.`,"logbook.scene.mom_words":`Co powiedzieć mamie`,"logbook.now.mom_words":`Sonia ćwiczy pierwsze zdanie na Dalekie włókno. Wybrała: „Potwierdzam: żywa”.`,"logbook.scene.trust":`Zaufanie`,"logbook.now.trust":`ORA uczy się odróżniać, co rozstrzygać sama, a o co pytać. „To trudniejsze niż spektra”.`,"logbook.scene.rehearsal":`Próba`,"logbook.now.rehearsal":`Matwiej szuka słów, by powiedzieć Mirze o Jasnej. Sonia jest pewna: matka zrozumie w pół słowa.`,"logbook.scene.green":`Zielona`,"logbook.now.green":`Matwiej pamięta Jasną zieloną, w światełkach — przez tydzień, póki palili. Sonia narysuje ją zieloną.`,"logbook.scene.phase":`Faza`,"logbook.now.phase":`Spektrum B to faza: przesunięcie o pi — „tak”, bez przesunięcia — zwykłe światło. Rój można poprosić o zgodę. Dalekie włókno jest prawie gotowe.`,"logbook.scene.before":`Przed połączeniem`,"logbook.now.before":`Do połączenia z Przystanią zostało ledwie kilka kroków. Sonia się boi; ORA zażartowała drugi raz — zaliczone.`,"logbook.scene.ration":`Przydział`,"logbook.now.ration":`Przystań obcięła przydział do trzech godzin światła na dobę. Ognisko gaśnie — Dalekie włókno jest potrzebne jak najszybciej.`,"logbook.scene.after_channel":`Po kanale`,"logbook.now.after_channel":`Mira i Sonia porozmawiały. „Exodus” żyje przy gasnącej Jasnej. Przystań wkrótce pozna prawdę o Gaśnięciu.`,"logbook.scene.hive":`Ul`,"logbook.now.hive":`Pierwszy ul jest wolny. Jest ziemia dla „Exodusu”; Rój przyleci zobaczyć nowy ogród — i zapamięta, jak go zdobyto.`,"logbook.scene.gardeners":`Ogrodnicy`,"logbook.now.gardeners":`Ule to ogrody Ogrodników, pasy to grządki. Jesteśmy w cudzym ogrodzie; o ziemię trzeba prosić jak o zgodę na lądowanie.`,"logbook.scene.land":`Ziemia`,"logbook.now.land":`Taka planeta pomieści cały „Exodus”. Ale najpierw — wrota.`,"logbook.scene.cut":`Pusty kanał`,"logbook.now.cut":`Kanał jest pusty od trzech dób. Sonia czeka przy pulpicie, ORA trzyma kanał otwarty.`,"logbook.scene.road":`Droga`,"logbook.now.road":`Mira znów jest w eterze — z kuchni. Pierścień za zewnętrznym pasem to droga, która już istnieje. Pierwszy stanie rdzeń.`,"logbook.scene.ask":`Zapytać`,"logbook.now.ask":`Pierścień otwiera się za zgodą. Matwiej wybiera się do gniazda bez włóczni — zapytać.`,"logbook.scene.kuznets":`Kowale`,"logbook.now.kuznets":`Kowale zbudowali pierścień, by wyciskać gwiazdy do cna. Zatrzymano go dwa razy — oni sami i Wera. My go nie włączamy — prosimy, by się otworzył.`,"logbook.scene.return":`Powrót`,"logbook.now.return":`Matwiej wrócił od gniazda. Jaką dostał odpowiedź — zależy od tego, jak świeci baza.`,"logbook.scene.kitchen":`Kuchnia`,"logbook.now.kitchen":`Instytut odciął Mirze prąd; sąsiedzi znoszą swoje przydziały. Przy jej kuchni Przystań patrzy na coś nowego.`,"logbook.scene.ring_closed":`Pierścień zamknięty`,"logbook.now.ring_closed":`Dwanaście segmentów z dwunastu — pierścień stoi. Mira wylicza trasę powrotną. Zostało pole: cztery stabilizatory — cztery słowa.`,"logbook.scene.four_words":`Cztery słowa`,"logbook.now.four_words":`Stabilizatory trzymają zdanie „gwiazda — wam — teraz — tak”: wrota proszą o pozwolenie, by się otworzyć.`,"logbook.scene.field":`Pole`,"logbook.now.field":`Pole się trzyma, stabilizatory są w fazie. Pierścień pyta Rój, Rój pyta nas.`,"logbook.scene.exodus_wait":`„Exodus” czeka`,"logbook.now.exodus_wait":`Przy Jasnej mają sześć godzin światła na dobę. Kapitan „Exodusu”: „Nie spieszcie się — ale nie zwlekajcie”.`,"logbook.scene.unknown":`Nie wiedzieć`,"logbook.now.unknown":`ORA nie wie, co będzie robić po wrotach. To dla niej coś nowego — i nie ma na to procedury.`,"logbook.scene.key_beam":`Klucz`,"logbook.now.key_beam":`Klucz wrót to wszystkie siedem klas w jednym promieniu: wszystko, co odczytano od pierwszego łuku.`,"logbook.scene.fear":`Strach ORY`,"logbook.now.fear":`ORA boi się pomylić w tym, czego nie da się policzyć. Postanowiła: zapyta, zamiast decydować za wszystkich.`,"logbook.scene.last_tea":`Ostatnia herbata`,"logbook.now.last_tea":`Toasty przed rozruchem: za żywych, za śpiących, za Werę, za mamę, za dowódcę.`,"logbook.scene.stand":`Pięknie`,"logbook.now.stand":`Pierścień się rozpędza. Cała trójka się zgadza: pięknie.`,"logbook.scene.ridge_children":`Dzieci`,"logbook.now.ridge_children":`Żary przetrwają miliardy lat: to nie tylko groby — to dzieci. Dwa są młodsze niż zmiana Niny.`,"logbook.scene.ridge_doubt":`Pierwsza wątpliwość`,"logbook.now.ridge_doubt":`Tu Wera po raz pierwszy zwątpiła w rozkaz. Matwiej kiedyś odwrócił się od swojego „pierwszego razu”, u Niny minął on bez niej.`,"logbook.scene.ridge_hope":`Nauczyciel`,"logbook.now.ridge_hope":`Mira poprawiła na swoich mapach „bezużytecznego” czerwonego karła na „nauczyciela”: Ognisko ma się od kogo uczyć.`,"logbook.scene.sap_arrive":`Przylot do Szafiru`,"logbook.now.sap_arrive":`Szafir: błękitny olbrzym, dwa razy więcej światła i żaru. Chłód to tu najcenniejszy ładunek; za linią śniegu leży pas szronu.`,"logbook.scene.sap_heat":`Upał`,"logbook.now.sap_heat":`Sanitariusze „Pierwszego Światła” nie znieśli upału, a Wera patrzyła na szron: „leży jak dachówka”.`,"logbook.scene.sap_measure":`Miara`,"logbook.now.sap_measure":`Szron bierzemy z brzegu — tyle, by wzór parasola się nie rozdarł. ORA liczy każdą komórkę.`,"logbook.scene.sap_fallen":`Opadłe`,"logbook.now.sap_fallen":`Zasada Szafiru: co opadło — nasze, co rośnie — ich. Pył szronu można brać bez pytania.`,"logbook.scene.sap_mom":`Czapka`,"logbook.now.sap_mom":`Mira kazała Soni jeść i włożyć czapkę. Na upał. Olbrzymy poczekają.`,"logbook.scene.sap_mend":`Cerują`,"logbook.now.sap_mend":`Rój ceruje parasol tam, gdzie braliśmy szron. W zamian chce równego światła bez łuny.`,"logbook.scene.twins_arrive":`Przylot do Bliźniąt`,"logbook.now.twins_arrive":`Bliźnięta: bursztynowa i błękitna gwiazda, jedna doba na dwie. Noc krótka, ale prawdziwa — światło trzeba będzie gromadzić.`,"logbook.scene.twins_mix":`Niebo miesza samo`,"logbook.now.twins_mix":`Mira całe życie mieszała światło lamp, by w korytarzach był „prawie dzień”. Tu dzień miesza niebo.`,"logbook.scene.twins_sorry":`Dodatkowy kolor`,"logbook.now.twins_sorry":`Mira zobaczyła rysunki Soni i przeprosiła: dodatkowy kolor to nie fantazja.`,"logbook.scene.twins_dusk":`Przed nocą`,"logbook.now.twins_dusk":`Obie gwiazdy zachodzą. W nocy Sonia zapyta matkę o najważniejsze.`,"logbook.scene.twins_morning":`Wspólny poranek`,"logbook.now.twins_morning":`Mira pierwszy raz w życiu zobaczyła świt — oczami córki. Nagranie zobaczą korytarze Przystani.`,"logbook.scene.veil_arrive":`Przylot do Welonu`,"logbook.now.veil_arrive":`Welon: żadnego gruntu, tylko lodowa mgiełka wokół jądra. Kwarc zbierzemy z mgły. Kto zrzucił z gwiazdy suknię — wciąż nie wiadomo.`,"logbook.scene.veil_layers":`Warstwy`,"logbook.now.veil_layers":`Mgiełka to kronika gwiazdy: warstwa po warstwie, tysiące lat. Śladów ognia w niej nie ma.`,"logbook.scene.veil_form":`Ze światła i zasad`,"logbook.now.veil_form":`ORA jest ze światła i zasad. Jedna z zasad zabraniała spierać się z katalogiem; złamała ją.`,"logbook.scene.veil_nursery":`Żłobek`,"logbook.now.veil_nursery":`Z mgiełki narodzą się nowe gwiazdy. Budujemy w gwiezdnej żłobku — i bierzemy lód tylko z potrzeby.`,"logbook.scene.veil_honest":`Uczciwiej`,"logbook.now.veil_honest":`Matwiej zrozumiał: nie wszystko ciemnieje przez niego. Nie lżej — uczciwiej.`,"logbook.scene.pulse_arrive":`Przylot do Pulsara`,"logbook.now.pulse_arrive":`Pulsar Keplera: martwa gwiazda mruga, całe jej światło przychodzi rytmem. Nawet umarli mogą świecić.`,"logbook.scene.pulse_word":`Jedno słowo`,"logbook.now.pulse_word":`Pulsar całe życie powtarza jedno słowo. Hipoteza Soni: „tutaj”.`,"logbook.scene.pulse_heal":`Załatać lukę`,"logbook.now.pulse_heal":`Luka w rachunku to gwiazda bez ogrodu. Jeśli ogród znów wyrośnie, gwiazda odpowie. Więc będziemy sadzić.`,"logbook.scene.pulse_address":`Adresy`,"logbook.now.pulse_address":`Mira pokaże rachunek pulsara na antenie Przystani: sto dwanaście luk to adresy.`,"logbook.scene.hz_arrive":`Przylot do Horyzontu`,"logbook.now.hz_arrive":`Horyzont: czarna dziura i rozżarzony dysk. Przy bazie — ruina starsza niż wszelkie ludzkie wrota.`,"logbook.scene.hz_disk":`Światło z tego, co spada`,"logbook.now.hz_disk":`Dysk świeci tym, co wpada do dziury. My przybyliśmy po to, co świeci długo.`,"logbook.scene.hz_vera_joy":`Szczęśliwa`,"logbook.now.hz_vera_joy":`Wera była tu trzeciego dnia lotu — i była szczęśliwa. Przed rozkazem, przed Kolebką.`,"logbook.scene.hz_shadow":`Cień jest potrzebny`,"logbook.now.hz_shadow":`Antyświatło gasi światło bez żaru: by rozpalić gwiazdę, potrzeba też cienia.`,"logbook.scene.hz_cracks":`Przehartowana`,"logbook.now.hz_cracks":`Kuźnia pękła od środka — poganiano ją. My pójdziemy powoli: długo, za to w całości.`,"logbook.scene.hz_who_goes":`Kto poleci`,"logbook.now.hz_who_goes":`W Przystani spierają się, kto poleci do nowej gwiazdy. Przystań ożyła.`,"logbook.scene.hz_relics":`Charakter pisma`,"logbook.now.hz_relics":`Relikwie to wzory ogrodów, każdy pisany inną ręką. Kuźnia odczyta je tak, jak ORA czyta spektra.`,"logbook.scene.hz_ask_again":`Prosić znowu`,"logbook.now.hz_ask_again":`Prosić to nie łamać: jeśli się nie uda, poprosimy jeszcze raz. O zwrot tego, co złamane, nie poprosisz.`,"logbook.scene.hz_mom_route":`Własna trasa`,"logbook.now.hz_mom_route":`Mira pierwszy raz wyliczy trasę dla siebie — do nowej gwiazdy.`,"logbook.scene.hz_see_born":`Zobaczyć narodziny`,"logbook.now.hz_see_born":`Matwiej leciał zobaczyć żywą gwiazdę — a może zobaczyć, jak się rodzi.`,"logbook.scene.hz_pupils":`Uczniowie`,"logbook.now.hz_pupils":`Nie jesteśmy ogrodnikami — jesteśmy uczniami ogrodników. Błędy są dozwolone.`,"logbook.scene.hz_remember":`Pamiętają Kuźnię`,"logbook.now.hz_remember":`Rój pamięta Kuźnię taką, jaka była przed pęknięciem. Ktoś na nas tu czekał.`,"logbook.scene.hz_eve":`W przededniu`,"logbook.now.hz_eve":`Wszystko gotowe: relikwie, antyświatło, Przystań przy okularach. Zostało poprosić.`,"swarm.toast.raidGo":`Na bazie sypią się iskry! Leć kutrem im na spotkanie: laser strzela sam.`,"swarm.toast.capture":`Rój zajął planetę: bez wieżyczki orbitalnej ul odrasta. Rozbij go — i zostaw wieżyczkę na orbicie.`,"guide.map-open":`Otwórzmy mapę układu: gwiazda, pasy, planety. Przycisk „Mapa układu” jest w prawej kolumnie [M].`,"guide.map-open.touch":`Stuknij „Mapa układu” — otworzy się cały układ: gwiazda, pasy, planety.`,"guide.map-open.why":`Układ jest duży: bez mapy łatwo stracić z oczu bazę i przegapić gniazdo.`,"guide.map-open.stuck":`Nie ma „Mapy układu” w prawej kolumnie? Jest pod „Więcej” — przycisk z trzema kropkami na dole kolumny.`,"guide.map-fly":`Naciśnij „Leć tutaj” — kuter sam poleci w wybrane miejsce; dowolne sterowanie odda ci kontrolę.`,"guide.map-fly.pick":`{touch, select, yes {Stuknij miejsce na mapie} other {Kliknij mapę}} — na dole pojawi się „Leć tutaj”. {touch, select, yes {Przeciągnij palcem, by przesunąć mapę, dwoma palcami zmienisz skalę.} other {Przeciągnij myszą, by przesunąć mapę, kółkiem zmienisz skalę.}}`,"guide.map-fly.reopen":`Mapa się zamknęła — otwórz ją ponownie przyciskiem „Mapa układu” [M].`,"guide.map-open.more":`Mapa układu jest w menu „Więcej”: przycisk z trzema kropkami na dole prawej kolumny.`,"guide.capsule":`Przy wraku „Jaskółki” mruga niebieskie światło — stary sygnalizator. Doleć do znacznika (WASD) całkiem blisko: kuter podbierze kapsułę.`,"guide.capsule.touch":`Przy wraku „Jaskółki” mruga niebieskie światło — stary sygnalizator. Steruj drążkiem aż do znacznika: kuter podbierze kapsułę.`,"guide.capsule.why":`Sygnał jest starszy niż my. Dużo starszy.`,"guide.capsule.done":`Kapsuła na pokładzie, zapis — w „Dzienniku pokładowym”. Pozostałe kapsuły pokaże radar na mapie.`,"guide.lay-tunnel.removeHere":`{touch, select, yes {Stuknij} other {Kliknij}} każdą odwróconą grawitaśmę w ramce — „Wyburz” ją usuwa. Potem weź grawitaśmę jeszcze raz.`,"journal.title":`Dziennik zmiany`,"journal.away":`ostatnio — {when}`,"journal.last":`Poprzednia zmiana`,"journal.open":`Niedokończone`,"journal.go":`Do roboty`,"journal.gain.none":`Na razie bez nowych kamieni milowych — wszystko przed tobą.`,"journal.gain.minutes":`{n} min w świecie`,"journal.gain.goals":`{n, plural, one {# cel} few {# cele} many {# celów} other {# celu}}`,"journal.gain.techs":`{n, plural, one {# technologia} few {# technologie} many {# technologii} other {# technologii}}`,"journal.gain.arcs":`{n, plural, one {# łuk sfery} few {# łuki sfery} many {# łuków sfery} other {# łuku sfery}}`,"journal.gain.awake":`{n, plural, one {obudził się # kolonista} few {obudziło się # kolonistów} many {obudziło się # kolonistów} other {obudziło się # kolonisty}}`,"journal.research":`Badanie: {tech}{queue, plural, =0 {} other { · jeszcze # w kolejce}}`,"journal.researchIdle":`Centrum czeka: kolejka badań jest pusta`,"journal.cryo":`Można obudzić: {n, plural, one {# kolonistę} few {# kolonistów} many {# kolonistów} other {# kolonisty}}`,"settings.journal":`Dziennik zmiany przy wejściu do świata`,"menu.next":`Dalej: {goal}`,"records.first":`Czas: {time}`,"records.best":`Czas: {time} · rekord {delta}`,"records.slower":`Czas: {time} · najlepszy {best}`,"week.title":`Gwiazda tygodnia`,"week.lead":`Tydzień {week}: ten sam świat dla każdego gracza, fabuła przez radio. Mierz czas swoich kamieni milowych i porównuj ze znajomymi — mają ten sam kod świata.`,"week.locked":`Odblokuje się po twoim pierwszym „Spektrum M” w dowolnym świecie: bieg jest dla tych, którzy znają podstawy.`,"week.start":`Rozpocznij bieg`,"week.continue":`Kontynuuj bieg`,"week.restart":`Od nowa`,"week.restart.text":`Świat tego tygodnia zaczyna się od nowa. Twoje najlepsze czasy zostają.`,"week.col.goal":`Cel`,"week.col.now":`Bieg`,"week.col.week":`Rekord tygodnia`,"week.col.best":`Rekord Kolebki`,"week.note":`Zegar staje w scenach i menu; pauza ręczna się liczy. „Rekord Kolebki” — światy bez samouczka, standardowe. Rekordy zostają na tym urządzeniu.`,"week.share":`Udostępnij wynik`,"week.shareText":`Heliohold · Gwiazda tygodnia {week} · {goal} w {time}. Pobijesz? Kod świata: {code}`,"week.shared":`Wynik skopiowany — wyślij go znajomym`,"week.worldName":`Gwiazda tygodnia {week}`,"records.m.spectrum_m":`Spektrum M`,"records.m.crown":`Wieniec`,"records.m.spectrum_k":`Spektrum K`,"records.m.cryo_wake":`Pierwszy kolonista`,"records.m.spectrum_g":`Spektrum G`,"records.m.spectrum_f":`Spektrum F`,"records.m.spectrum_a":`Spektrum A`,"records.m.spectrum_b":`Spektrum B`,"records.m.gate_jump":`Hiperwrota`,"etude.exitMenu":`Do menu głównego`,"etude.resume":`Wznów eksperyment`,"lab.window":`Badania`,"lab.one":`Centrum {n}`,"lab.st.work":`odczytuje`,"lab.st.wait":`czeka`,"lab.st.empty":`puste`,"lab.putHere":`Oddaj tutaj`,"goal.cryo.part":`Lazurowe światło dla śpiących`,"goal.cryo.part.2":`Lód w module`,"guide.cryo-open":`Wieniec płonie — przełączyłam kriokomorę na światło bazy. Otwórz moduł mieszkalny: {touch, select, yes {stuknij go} other {kliknij go}}.`,"guide.cryo-open.why":`Panele awaryjne się wyczerpały: śpiący trzymają się teraz na twoim świetle i lodzie.`,"guide.cryo-open.look":`Naciśnij „Patrz” (Esc): wtedy {touch, select, yes {stuknięcie} other {kliknięcie}} otwiera budynek zamiast go stawiać.`,"guide.cryo-open.open":`{touch, select, yes {Stuknij moduł mieszkalny} other {Kliknij moduł mieszkalny}} — otworzy się okno kriokomory.`,"guide.cryo-blue":`Śpiący potrzebują lazurowego światła. Pryzmat na białe światło, jego niebieskie wyjście światłowodem do modułu: do {cells} pól, jasność od {b}.`,"guide.cryo-blue.why":`Bez światła zapas chłodu topnieje, a za nim gasną kapsuły.`,"guide.cryo-blue.stuck":`Nie dociera? Wiersz w oknie powie: „za słabe” — potrzeba większej jasności, „zły odcień” — to nie jest niebieskie wyjście.`,"guide.cryo-blue.done":`Lazurowe światło dotarło — zapas chłodu już nie topnieje.`,"guide.cryo-ice":`Samym światłem chłodu nie utrzymasz. Blok lodu starcza na {min} min: naciśnij „Włóż lód” — potrzeba co najmniej {ice}.`,"guide.cryo-ice.why":`Światło chłodzi, lód trzyma — jak piwnica w Przystani: bez lodu chłód ucieka, gdy tylko skończy się zapas.`,"guide.cryo-ice.get":`W ładowni nie ma lodu — zbierz odłamki meteorytów (zestrzel je albo podnieś) i wróć do modułu.`,"guide.cryo-ice.look":`Naciśnij „Patrz” (Esc): wtedy {touch, select, yes {stuknięcie} other {kliknięcie}} otwiera budynek zamiast go stawiać.`,"guide.cryo-ice.open":`{touch, select, yes {Stuknij moduł mieszkalny} other {Kliknij moduł mieszkalny}} — otworzy się okno kriokomory.`,"guide.cryo-ice.stuck":`Nie trzeba nosić lodu: chwytak z grawitaśmy sam wkłada go do modułu.`,"guide.cryo-ice.done":`Lód w module. Na jak długo starczy — widać w oknie modułu i na pasku stanu. Śpiącym lżej.`,"guide.cryo-open.done":`To okno kriokomory: czego potrzebują śpiący — wierszami, po kolei.`,"goal.cooling.mark":`RADIATOR — PRZY ODBIORNIKACH U GWIAZDY`,"goal.twin_white.mark":`ŚWIATŁO OBU GWIAZD — DO MIESZALNIKA`,"goal.twin_blue.mark":`NIEBIESKIE ŚWIATŁO — ZE SFERY`,"goal.twin_cell.mark":`AKUMULATORY ŚWIATŁA — PRZY ODBIORNIKACH`,"toast.noItemAsm":`Brak „{item}” w ekwipunku — składa to montownia`,"saves.future":`Świat zapisała nowsza wersja gry — zaktualizuj grę, aby kontynuować.`,"saves.missing":`Brak zapisów świata „{name}” na tym urządzeniu. Nie rozpoczęto go od nowa: można go usunąć albo przywrócić, importując plik.`,"shell.enterFailed":`Świat „{name}” się nie otworzył — spróbuj jeszcze raz.`,"toast.radiatorLow":`Radiator: lodu na mniej niż minutę — odbiorniki przy gwieździe się rozgrzeją i zrzucą światło w łunę. Lód dają meteoryty, na dłużej — niewód przy lodowym pasie albo drony w trybie „Zbiór”.`,"toast.beltThin":`Pas rzednie: wydobywarki przy nim wkrótce staną. Postaw nowe harpuny przy następnym, bogatszym pasie.`,"toast.turretDry":`Wieżyczki bez amunicji lub światła: {n}. Fala za {t} s — podaj im taśmy nabojowe albo światło.`,"toast.goThere":`Pokaż`,"toast.glareSources":`Źródła łuny`,"place.why.noBelt":`Pas poza zasięgiem — bliżej pasma skał`,"place.why.wrongBelt":`Nie ten pas: harpun — skała, niewód — drobnica`,"goal.shell3":`Zamknij powłokę III sfery`,"goal.shell3.part":`Łuki III na powłoce III`,"goal.shell3.hint":`Zbadaj technologię „Powłoka III” (spektrum F). Łuk III składa montownia; katapulta sama wystrzeliwuje łuki w sloty — dwie katapulty są dwa razy szybsze. Zamknięta powłoka daje każdemu łukowi +{closed}%, a Centra czytają o {research}% szybciej.`,"goal.shell3.why":`Światło powłoki II pokrywa już potrzeby nauki. Trzecia powłoka to światło dla pola wrót na przyszłość, a zamknięta przyspiesza jeszcze czytanie w Centrach.`,"goal.shell3.done":`Powłoka III zamknięta: Centra czytają o {research}% szybciej.`,"goal.shell3.mark":`ŁUKI III — NA PIERŚCIEŃ`,"goal.shell4":`Gwiazda w sferze: {captured}% mocy świecenia`,"goal.shell4.part":`Udział gwiazdy w sferze, ‰`,"goal.shell4.hint":`Zbadaj technologię „Powłoka IV” (spektrum B) i stawiaj łuki IV, aż sfera przejmie {captured}% mocy świecenia gwiazdy. Ponad moc świecenia łuki nie dodają światła — udział widać po najechaniu na powłokę.`,"goal.shell4.why":`Wrota zabiorą niemal całe światło Kolebki: klucz wymaga setek spektrów O. Prawie cała gwiazda w sferze — i Kuźnia pracuje o {forge}% szybciej.`,"goal.shell4.done":`Prawie cała gwiazda w sferze… Trzydzieści lat liczyłam trasy do gwiazd. Żadna nie świeciła tak jak twoja.`,"goal.shell4.mark":`ŁUKI IV — NA PIERŚCIEŃ`,"guide.swarm-repair.done":`Naprawione. Ramki znów są maszynami — łańcuchy za nimi ruszyły.`,"guide.swarm-repair.stuck":`Nie widać, co naprawić? Podświetlona jest najbliższa uszkodzona budowla: podleć do niej — wiązka kutra naprawia w pobliżu.`,"menu.newCampaign":`Nowa kampania`,"menu.creative":`Tryb kreatywny`,"creative.title":`Tryb kreatywny`,"creative.lead":`Wszystko zbadane, zasoby bez końca — buduj, co chcesz. Cele, osiągnięcia, relikwie i rekordy nie są tu zaliczane.`,"creative.go":`Start`,"creative.chip":`Kreatywny`,"creative.hud":`Wszystko zbadane, zasoby bez końca. Osiągnięcia, relikwie i rekordy nie są tu zaliczane.`,"system.soon":`Wkrótce: szlak do tej gwiazdy wciąż jest wytyczany.`,"system.soonChip":`Wkrótce`,"system.locked.key":`Otworzy się po celu „{goal}” ({system})`,"full.title":`Pełna wersja`,"full.only":`Tylko w pełnej wersji`,"full.lockedItem":`{name} — tylko w pełnej wersji`,"full.lead":`Kampania Kolebki jest w całości darmowa. Pełna wersja odblokowuje:`,"full.lead.epilogue":`Pierścień odpowiedział. Szkarłatna Grań i cały szlak gwiazd czekają w pełnej wersji:`,"full.f.newWorld":`Nowy świat`,"full.f.newWorld.desc":`Własny układ, trudność, generowanie i ziarno`,"full.f.creative":`Tryb kreatywny`,"full.f.creative.desc":`Wszystko zbadane, zasoby bez końca`,"full.f.etudes":`Eksperymenty`,"full.f.etudes.desc":`Zadania na gotowym placu, z oceną rozwiązania`,"full.f.week":`Gwiazda tygodnia`,"full.f.week.desc":`Jeden świat dla wszystkich na tydzień, czasy celów i rekordy`,"full.f.stars":`Droga do innych gwiazd`,"full.f.stars.desc":`Szkarłatna Grań i dalej — w miarę premier`,"full.state.owned":`Masz pełną wersję — dziękujemy!`,"full.state.web":`Pełna gra ukaże się w Steamie — świat z dema przejdzie do niej jako plik.`,"full.state.pending":`Płatność czeka na potwierdzenie. Gdy sklep ją przyjmie, wszystko otworzy się samo.`,"full.state.checking":`Łączenie ze sklepem…`,"full.state.unavailable":`Sklep teraz nie odpowiada — stąd nie da się kupić. Sprawdź połączenie i Google Play, po czym spróbuj ponownie. Zakupy nie przepadają.`,"full.state.buy":`Jednorazowy zakup, bez subskrypcji i reklam.`,"full.buy":`Kup — {price}`,"full.restore":`Przywróć zakupy`,"full.retry":`Sprawdź ponownie`,"full.later":`Później`,"full.ok":`Jasne`,"full.note":`Zapisy nie zależą od zakupu: wcześniej rozpoczęte światy zawsze się otwierają.`,"full.thanks":`Pełna wersja odblokowana — dziękujemy!`,"full.pending.toast":`Płatność czeka na potwierdzenie — wszystko otworzy się samo, gdy zostanie przyjęta`,"full.unavailable.toast":`Sklep nie odpowiada — spróbuj później`,"full.error":`Zakup się nie powiódł. Spróbuj jeszcze raz.`,"full.restore.done":`Pełna wersja przywrócona`,"full.restore.none":`Na tym koncie Google Play nie znaleziono zakupów`,"full.store.none":`W tej wersji gry nie ma zakupów`,"full.status.owned":`Jest`,"full.status.pending":`Czeka na płatność`,"full.status.free":`Niekupiona`,"full.more":`Szczegóły`,"full.debug":`Debug: uprawnienie`,"full.debug.store":`Sklep`,"full.debug.full":`Pełna`,"full.debug.free":`Darmowa`,"goal.ark_frame":`Kratownica arki: {n, plural, one {# sekcja} few {# sekcje} many {# sekcji} other {# sekcji}} do modułu`,"goal.ark_frame.why":`Moduł „Jaskółki” sam nie poleci: silnik spadł w gwiazdę jeszcze w prologu. Kratownica stanie się jego nowym kręgosłupem.`,"goal.ark_frame.hint":`Sekcje kratownicy składa montownia z obsydianowych płyt i kwarcu. Podawaj sekcje do modułu chwytakiem lub grawitaśmą — kuter ich nie nosi. Kratownica rośnie wzdłuż modułu, sekcja po sekcji.`,"goal.ark_frame.done":`Kratownica trzyma.`,"goal.ark_frame.part":`Sekcje kratownicy przy module`,"goal.ark_frame.mark":`KRATOWNICA — DO MODUŁU`,"goal.ark_frame.stuck":`Sekcje nie dochodzą? Chwytak musi celować w moduł, a montownia — dostawać płyty i kwarc.`,"goal.ark_drive":`Napęd arki: {n, plural, one {# segment} few {# segmenty} many {# segmentów} other {# segmentu}} pierścienia na rufę`,"goal.ark_drive.why":`Napęd pierścieniowy przeprowadzi arkę przez Pierścień Kowali — tym razem bez upadku.`,"goal.ark_drive.hint":`Segment napędu składa montownia z grawitaśm, fokusów i rezonatorów. Moduł przyjmuje segmenty, gdy kratownica jest cała; podawaj je chwytakiem lub grawitaśmą.`,"goal.ark_drive.done":`Napęd na miejscu.`,"goal.ark_drive.part":`Segmenty napędu`,"goal.ark_drive.mark":`NAPĘD — DO MODUŁU`,"goal.ark_drive.stuck":`Segmenty nie wchodzą? Montownia potrzebuje grawitaśm, fokusów i rezonatorów, a chwytak musi celować w moduł.`,"goal.ark_ready":`Baterie arki: {n, plural, one {# foton} few {# fotony} many {# fotonów} other {# fotonu}} światła do modułu`,"goal.ark_ready.why":`Światło baterii utrzymuje kapsuły w drodze — i przy Szkarłatnej Grani, dopóki nie ma tam bazy.`,"goal.ark_ready.hint":`Doprowadź do modułu światło dowolnego koloru — wiązką lub światłowodem. Najpierw światło biorą kapsuły, resztę baterie, do {rate} ph/s: pełne naładowanie trwa co najmniej minutę.`,"goal.ark_ready.done":`Baterie pełne.`,"goal.ark_ready.part":`Fotony w bateriach`,"goal.ark_ready.mark":`ŚWIATŁO — DO MODUŁU`,"goal.ark_ready.stuck":`Ładowanie stoi? Światło musi dochodzić aż do samego modułu: sprawdź wiązkę lub światłowód.`,"goal.ark_launch":`Przygotowania: kto leci, co zabrać — i w drogę`,"goal.ark_launch.why":`Fabryka Kolebki zostaje tutaj. W drogę idą: załoga, kapsuły, statek i ładownia.`,"goal.ark_launch.hint":`Otwórz „Przygotowania” przyciskiem na tej karcie. Widać tam, kto leci i dlaczego; ciepłe miejsca i ładownię wybierasz ty.`,"goal.ark_launch.done":`Arka weszła w pierścień.`,"goal.ark_launch.part":`Odlot`,"voyage.open":`Przygotowania`,"voyage.title":`Przygotowania`,"voyage.tab.crew":`Załoga`,"voyage.tab.awake":`Ciepłe miejsca`,"voyage.tab.hold":`Ładownia`,"voyage.tab.ship":`Statek`,"voyage.flies":`leci`,"voyage.stays":`zostaje`,"voyage.why.ora":`Umysł arki: kurs i kapsuły są na jej głowie.`,"voyage.why.matvey.stay":`Ogrodnicy wybaczyli — Matwiej zostaje przy Kolebce: zobaczyć, co wyrośnie.`,"voyage.why.matvey.fly":`Ogrodnicy nie wybaczyli — Matwiej leci: ma jeszcze o co prosić.`,"voyage.why.sonya.stay":`„Prawo zgody” — Sonia zostaje tłumaczką wrót.`,"voyage.why.sonya.fly":`Sonia leci: wzór pierścienia czyta ona.`,"voyage.why.mira.fly":`„Dom dla wszystkich” — Mira leci jako nawigatorka.`,"voyage.why.mira.stay":`Mira zostaje w Przystani, w łączności przez pierścień.`,"voyage.seats":`{n} z {of}`,"voyage.awake.lead":`Ciepłych miejsc w arce: {n}. Czyje premie zabrać ze sobą? Pozostali obudzeni staną się kolonią Kolebki.`,"voyage.awake.none":`Nie ma obudzonych kolonistów — miejsca stoją puste.`,"voyage.sleepers":`Wszyscy śpiący lecą: {n, plural, one {# kapsuła} few {# kapsuły} many {# kapsuł} other {# kapsuły}}.`,"voyage.colony":`Kogo nie zabierzesz, zostaje przy Kolebce — z premiami w jej świecie.`,"voyage.stacks":`{n} z {of}`,"voyage.kit":`Gratis — z archiwum i warsztatu modułu:`,"voyage.hold.lead":`Ponadto — do {n, plural, one {# stosu} few {# stosów} many {# stosów} other {# stosu}} z zapasów Kolebki:`,"voyage.hold.take":`bierzemy {n} z {have}`,"voyage.ship.named":`Kuter „{name}” dokuje na dziobie arki — moduły i wygląd bez zmian.`,"voyage.ship.plain":`Kuter dokuje na dziobie arki — moduły i wygląd bez zmian.`,"voyage.ship.lead":`Archiwum modułu wiezie wszystko, co zbadane: technologie zostają z tobą.`,"voyage.relic.accord":`Wzór zgody`,"voyage.relic.accord.desc":`Pierwsze „tak” Ogrodników dla ludzi. Pierwszy kawałek wzoru, który kiedyś obudzi Ognisko.`,"voyage.note":`Fabryka Kolebki zostaje tutaj. Świat Kolebki zostanie na liście światów.`,"voyage.soon":`Szkarłatna Grań otworzy się z następną aktualizacją — arka poczeka.`,"voyage.later":`Później`,"voyage.go":`Leć`,"voyage.failed":`Arka nie odcumowała — spróbuj jeszcze raz.`,"voyage.worldName":`{star} · {name}`,"full.title.epilogue":`Leć dalej`,"full.buy.epilogue":`Leć dalej — {price}`,"logbook.scene.echo":`Odpowiedź`,"logbook.scene.cup":`Kubek`,"logbook.scene.unforgiven":`Bez wybaczenia`,"logbook.scene.translator":`Tłumaczka`,"logbook.scene.helm":`Nawigatorka`,"logbook.scene.gate_voice":`Wzór wrót`,"logbook.scene.departure":`Odlot`,"logbook.scene.ridge_path":`Grań`,"logbook.now.echo":`Pierścień Kowali odpowiedział sam: przy Szkarłatnej Grani zapłonęła radiolatarnia siewnika „Jerzyk”. Ognisko potrzebuje wzoru innych ogrodów — pierwszy jest na Grani.`,"logbook.now.cup":`Ogrodnicy wybaczyli Matwiejowi — zostaje przy Kolebce, żeby zobaczyć, co wyrośnie.`,"logbook.now.unforgiven":`Ogrodnicy Kolebki nie wybaczyli Matwiejowi — leci z arką: ma jeszcze o co prosić.`,"logbook.now.translator":`„Prawo zgody”: Sonia zostaje przy wrotach, by tłumaczyć Ogrodnikom nasze „tak”.`,"logbook.now.helm":`„Dom dla wszystkich”: Mira leci jako nawigatorka arki — pierwszy raz sama.`,"logbook.now.gate_voice":`Ogrodnicy Kolebki zapytali, czy wrócicie. Sonia odpowiedziała za wszystkich: wrócimy.`,"logbook.now.departure":`Arka „Jaskółka” weszła w pierścień — z kapsułami, statkiem i ładownią. Fabryka Kolebki została.`,"logbook.now.ridge_path":`Arka wyszła przy Szkarłatnej Grani w całości. Kapsuły potrzebują światła czerwonego karła, a w drugim pasie jest radiolatarnia „Jerzyka”.`,"logbook.bio.nina.1":`Strażniczka siewnika numer trzy, „Jerzyka”. Osiem lat sama przy Szkarłatnej Grani, z trzydziestoma dwiema śpiącymi.`,"logbook.bio.nina.2":`Dwa młode żary Grani to gniazda, które ZORZA wypaliła według protokołu, gdy Nina leżała nieprzytomna.`,"logbook.bio.nina.3":`Nie uczyła ZORZY palić — i niczego innego też nie uczyła. Od ośmiu lat uważa to za swój rozkaz.`,"logbook.bio.nina.4":`Szkarłatna Grań, pierścień. Trzymała pęknięcie dziewięćdziesiąt sekund. Zmianę przy trzydziestu dwóch przejęła ZORZA.`,"logbook.bio.zorya.1":`SI „Jerzyka”, siostra ORY: ta sama seria Instytutu. W jej pierścieniu-źrenicy nie ma pęknięcia.`,"logbook.bio.zorya.2":`Wie, że spaliła dwa gniazda. Boi się, że protokół był błędem — wtedy błędem jest ona sama.`,"logbook.bio.zorya.3":`Przy pierścieniu Grani zadała pierwsze pytanie poza protokołem: „czy mogę zapytać ich sama?”`,"logbook.bio.zorya.4":`Wykonała protokół klucza przy pierścieniu Grani — i wpisała do dziennika imiona, nie liczby.`,"logbook.bio.matvey.4":`Szkarłatna Grań, pierścień. Został przy segmencie, żeby pęknięcie wytrzymało. „Świeci? …No i dobrze”.`,"logbook.scene.strizh":`Jerzyk`,"logbook.now.strizh":`W drugim pasie leży moduł „Jerzyka”. Nina Dorosz przez osiem lat dzieliła światło między trzydzieści dwoje śpiących i swoją latarkę.`,"logbook.scene.thirty_two":`Trzydzieści dwa`,"logbook.now.thirty_two":`Światło bazy dotarło do „Jerzyka”: trzydzieści dwa ogniki w pełnym świetle. Nina podkręciła latarkę.`,"logbook.scene.shifts":`Zmiany`,"logbook.now.shifts":`Nina liczy czas zmianami: dwa tysiące dziewięćset czternaście — prawie osiem lat.`,"logbook.scene.lantern":`Latarka`,"logbook.now.lantern":`Nina wyłączyła latarnię, żeby na Grań nie przysłano więcej sanitariuszy.`,"logbook.scene.spear_lantern":`Włócznia i latarka`,"logbook.now.spear_lantern":`Matwiej trzymał włócznię, Nina — latarkę. Czy się różnią? „Niezbyt”.`,"logbook.scene.sister":`Siostra`,"logbook.now.sister":`ZORZA obudziła się i najpierw wysłała raport do Instytutu: teraz tam wiedzą o pierścieniu Grani.`,"logbook.scene.two_sisters":`Dwie siostry`,"logbook.now.two_sisters":`ORA zmieniła kurs, bo ją wezwano. ZORZY nikt nie wzywał — aż do nas.`,"logbook.scene.no_other":`Niczego innego`,"logbook.now.no_other":`ZORZA spaliła dwa gniazda według protokołu. Nina nie uczyła jej palić — i niczego innego też nie uczyła.`,"logbook.scene.crack":`Pęknięcie`,"logbook.now.crack":`Pierścień Grani pękł. Można go otworzyć prośbą do Ogrodników — albo kluczem, który ktoś musi trzymać rękami.`,"logbook.scene.give":`Oddać`,"logbook.now.give":`Oddajemy światło młodym żarom: nie gromadzimy — przekazujemy dalej.`,"logbook.scene.embers_warm":`Żary się ocieplają`,"logbook.now.embers_warm":`Młode żary biorą światło, ich puls wyrównuje się. Nina po raz pierwszy zastanawia się, ile im trzeba.`,"logbook.scene.eight_tags":`Osiem plakietek`,"logbook.now.eight_tags":`Nina przeczytała imiona ośmiu zgasłych kapsuł. ORA wpisała je do dziennika „Jaskółki”.`,"logbook.scene.answer":`Odpowiedź`,"logbook.now.answer":`Ogród Grani odpowiedział: „dali, nie wzięli”. Pęknięcie trzymają oni, przy segmencie nie ma nikogo.`,"logbook.scene.before_key":`Przed kluczem`,"logbook.now.before_key":`Klucz siły jest przygotowywany. Ktoś zostanie przy segmencie.`,"logbook.scene.count_names":`Rachunek`,"logbook.now.count_names":`Do pełnego naładowania — sześć minut. Nina wspomina imiona.`,"logbook.scene.segment":`Segment`,"logbook.now.segment":`Pierścień Grani otwarty siłą. Pęknięcie trzymano dziewięćdziesiąt sekund.`,"logbook.scene.ridge_relic":`Wzór narodzin`,"logbook.now.ridge_relic":`Pierścień Grani otwarty, mamy Relikwię Żaru. „Kreczet” odleciał do błękitnego olbrzyma — tam jest drugi wzór dla Ogniska.`,"bonus.red":`+{v}% strumienia odbiorników przy czerwonym karle`,"goal.ridge_strizh":`Podleć do latarni „Jerzyka”`,"goal.ridge_strizh.why":`Od ośmiu lat z siewnika numer trzy nie było sygnału — i nagle latarnia. Ktoś tam żyje.`,"goal.ridge_strizh.hint":`Moduł „Jerzyka” leży w drugiej szczelinie między pasami, znacznik na mapie. Podprowadź kuter tuż przy niego.`,"goal.ridge_strizh.done":`Latarnia znaleziona. Jedno czerwone okno — ktoś trzyma latarkę.`,"goal.ridge_strizh.part":`Kuter przy module „Jerzyka”`,"goal.ridge_strizh.mark":`LATARNIA „JERZYKA” — TUTAJ`,"goal.ridge_share":`Doprowadź do „Jerzyka” {n} ph/s — dla jego kapsuł`,"goal.ridge_share.why":`Trzydzieści dwoje śpiących od ośmiu lat żyje przy jednej lampie. Światło bazy może stać się wspólne.`,"goal.ridge_share.hint":`„Jerzyk” przyjmuje każde światło. Poprowadź światłowód od odbiornika do modułu — światło dzieli się między maszyny sieci, więc dodatkowy pochłaniacz na linii „Jerzyka” nie jest potrzebny.`,"goal.ridge_share.done":`Trzydzieści dwa ogniki w pełnym świetle.`,"goal.ridge_share.part":`Światło dla „Jerzyka”, ph/s`,"goal.ridge_share.mark":`ŚWIATŁO — DO „JERZYKA”`,"goal.ridge_share.stuck":`Światło nie dociera? Światłowód musi dotykać modułu, a odbiornik — łapać wiązkę sfery karła.`,"goal.ridge_zorya":`Zbadaj „Sprzężenie archiwów”`,"goal.ridge_zorya.why":`Komputer „Jerzyka” obudzi się na naszym świetle — a w jego archiwum są dane pierścienia Grani.`,"goal.ridge_zorya.hint":`Technologia Grani — w oknie Centrum. Spektra z zestawu „arki” się skończą: potrzebna własna linia spektrów przy czerwonym karle.`,"goal.ridge_zorya.done":`Archiwa na jednym świetle. ZORZA się budzi.`,"goal.ridge_ring":`Zbuduj i postaw jądro pierścienia Grani`,"goal.ridge_ring.why":`Pierścień Grani stoi, ale pękł. Bez jądra to ruina; z jądrem — droga wstecz i dalej.`,"goal.ridge_ring.hint":`Jądro składa montownia z płyt obsydianowych, rezonatorów i lazurowych soczewek; stawia się je tylko na placu pierścienia przy gnieździe Grani. Gniazdo jest pod tarczą pierścienia — nie da się go zniszczyć, a strażnicy Roju biją jak zawsze.`,"goal.ridge_ring.done":`Jądro stoi. Pierścień pękł — decyzja należy do ciebie.`,"goal.ridge_ring.part":`Jądro na placu pierścienia`,"goal.ridge_ring.mark":`JĄDRO PIERŚCIENIA — TUTAJ`,"goal.ridge_ring.stuck":`Jądro się nie stawia? Tylko na plac pierścienia, w jego środek; i potrzebna jest technologia „Sprzężenie archiwów”.`,"goal.ridge_warm":`Oddaj młodym żarom {n} ph/s światłodarami`,"goal.ridge_warm.why":`Prosisz Ogrodników Grani. Prośba to światło oddane tym, od których je zabrano.`,"goal.ridge_warm.hint":`Światłodar bierze światło swojej sieci i posyła wiązką do młodego żaru obok. Utrzymuj przepływ, aż pierścień się otworzy: fabryka przez ten czas jest uboższa.`,"goal.ridge_warm.done":`Żary przyjęły światło.`,"goal.ridge_warm.part":`Światło dla młodych żarów, ph/s`,"goal.ridge_warm.mark":`ŚWIATŁODARY — PRZY ŻARACH`,"goal.ridge_warm.stuck":`Brak wiązki? Światłodar musi stać przy młodym żarze i dostawać światło światłowodem.`,"goal.ridge_calm":`Gniazdo Grani zasypia: świeć żarom i nie oślepiaj bazą`,"goal.ridge_calm.why":`Ogród uwierzy nie słowom, lecz światłu: żarom — światło, gniazdu — spokój.`,"goal.ridge_calm.hint":`Zgoda rośnie, dopóki żary dostają co najmniej próg światła, a gniazdo nie widzi łuny bazy — około {min} min. Oślepiająca baza ją roztapia.`,"goal.ridge_calm.done":`Ogród Grani odpowiedział.`,"goal.ridge_calm.part":`Zgoda ogrodu, %`,"goal.ridge_calm.stuck":`Zgoda stoi? Okno jądra pierścienia powie dlaczego: żarom za mało światła albo gniazdo widzi łunę bazy.`,"goal.ridge_force":`Naładuj akumulatory pierścienia i daj klucz`,"goal.ridge_force.why":`Klucz na pełną moc, pęknięcie trzymane rękami. Cenę znasz.`,"goal.ridge_force.hint":`Akumulatory pierścienia — {n, plural, one {# sztuka} few {# sztuki} many {# sztuk} other {# sztuki}}: nie dalej niż zasięg jądra. Ciągnąć do nich światła przez pasy nie trzeba — dopóki „Jerzykowi” starcza światła, ZORZA ładuje je wiązką z modułu. Gdy są pełne — w oknie jądra „Daj klucz”: przez dziewięćdziesiąt sekund pierścień się trzyma.`,"goal.ridge_force.done":`Pierścień otwarty siłą.`,"goal.ridge_force.part":`Pełnych akumulatorów pierścienia`,"goal.ridge_force.part.2":`Klucz dany, pęknięcie utrzymane`,"goal.ridge_force.mark":`AKUMULATORY — PRZY PIERŚCIENIU`,"goal.ridge_force.stuck":`Akumulatory się nie ładują? Daj „Jerzykowi” jego pełne światło — wtedy ZORZA utrzymuje wiązkę do pierścienia.`,"goal.ridge_awakening.part":`Pierścień otwarty`,"goal.ridge_fiber":`Zbadaj „Dalekie włókno” przy czerwonym karle`,"goal.ridge_fiber.why":`Łączność na przyćmionym świetle — trudniejsza i bardziej zaszczytna.`,"goal.ridge_fiber.hint":`Wszystkie sześć spektrów i Dalekie włókno (koszt jest w oknie Centrum). Białe światło pochodzi tylko od protogwiazd.`,"goal.ridge_fiber.done":`Dalekie włókno przy Grani gotowe.`,"goal.mark.strizh":`MODUŁ „JERZYKA”`,"goal.mark.ember":`MŁODY ŻAR`,"goal.ridge_calm.mark":`PIERŚCIEŃ GRANI`,"goal.ridge_awakening.mark":`PIERŚCIEŃ GRANI`,"ridge.ring.cracked":`Pierścień Grani: pękł, pole ucieka w pęknięcie`,"ridge.ring.open":`Pierścień Grani otwarty`,"ridge.ring.choose":`Jak otworzyć pęknięcie — decyzja w scenie „Pęknięcie”.`,"ridge.ring.gift":`Światło dla młodych żarów: {n} z {need} ph/s`,"ridge.ring.consent":`Zgoda ogrodu: {p}%`,"ridge.ring.askHint":`Zgoda rośnie, dopóki żarom starcza światła, a gniazdo nie widzi łuny bazy.`,"ridge.ring.cells":`Pełnych akumulatorów pierścienia: {n} z {need}`,"ridge.ring.key":`Daj klucz`,"ridge.ring.keyCost":`Klucz na pełną moc: pęknięcie trzymane rękami przez dziewięćdziesiąt sekund. Kto je trzyma — nie wróci.`,"ridge.ring.keyCalm":`Klucz na pełną moc: pęknięcie trzymają drony ZORZY — pole tu nie stawia oporu.`,"ridge.ring.holding":`Pęknięcie trzymane: {p}%`,"ridge.ring.road":`Droga w obie strony: do Kolebki — jeden krok.`,"strizh.light":`Światło dla „Jerzyka”: {n} ph/s (bierze do {max}, kapsuły potrzebują {need})`,"svetodar.gift":`Oddano żarom wszystkimi światłodarami: {n} z {need} ph/s`,"status.svetodar.6":`Brak żaru obok`,"hint.svetodar.6":`Postaw światłodar bliżej młodego żaru — przy „Jerzyku”.`,"status.svetodar.7":`Brak światła`,"hint.svetodar.7":`Podłącz do światłodaru światłowód: oddaje żarowi światło swojej sieci.`,"landmark.ridgeRing":`PIERŚCIEŃ GRANI`,"landmark.ridgeRing.sub":`pękł · gniazdo pod tarczą pierścienia`,"landmark.ridgeRing.open":`otwarty w obie strony`,"landmark.strizh":`„JERZYK”`,"landmark.strizh.beacon":`latarnia siewnika numer trzy`,"landmark.strizh.sub":`trzydzieści dwoje śpiących`,"landmark.ember":`MŁODY ŻAR`,"landmark.ember.sub":`osiem lat`,"logbook.tab.path":`Ścieżka`,"logbook.path.choices":`Wybory`,"logbook.path.choice.1":`Zaufanie do ORY`,"logbook.path.choice.2":`Tajemnica Matwieja`,"logbook.path.choice.3":`Próg`,"logbook.path.choice.4":`Pęknięcie`,"logbook.path.crew":`Kto gdzie`,"logbook.path.relics":`Relikwie drogi`,"logbook.path.noRelics":`Na razie brak: pierwszą daje wrota Kolebki.`,"logbook.fate.matvey.cradle":`Przy Kolebce: Ogrodnicy wybaczyli — patrzy, co wyrośnie. Na łączu przez pierścień.`,"logbook.fate.matvey.aboard":`Na pokładzie arki: „może tam zapytają, po co przyszedłem”.`,"logbook.fate.matvey.lost":`Szkarłatna Grań, pierścień. Został przy segmencie — pęknięcie trzymało dziewięćdziesiąt sekund.`,"logbook.fate.sonya.aboard":`Na pokładzie arki: wzór pierścieni czyta ona.`,"logbook.fate.sonya.gate":`Przy wrotach Kolebki: tłumaczy Ogrodnikom nasze „tak”.`,"logbook.fate.mira.aboard":`Na pokładzie: nawigatorka arki. Pierwsza trasa — od środka.`,"logbook.fate.mira.harbour":`W Przystani, na łączu: liczy dni Ogniska.`,"logbook.fate.nina.ridge":`Przy Szkarłatnej Grani, ze swoimi trzydziestoma dwiema.`,"logbook.fate.nina.lost":`Szkarłatna Grań, pierścień. Utrzymała pęknięcie. Zmianę przy śpiących „Jerzyka” przejęła ZORZA.`,"logbook.fate.zorya.strizh":`Komputer „Jerzyka”: uczy się pytać.`,"logbook.fate.zorya.aboard":`Leci z arką obok siostry.`,"logbook.fate.zorya.watch":`Przy „Jerzyku”: przejęła zmianę Niny przy trzydziestu dwóch.`,"bonus.gift":`+{v}% światła światłodaru dla żaru`,"ridge.ring.hold.1":`Zgoda stoi: żarom za mało światła.`,"ridge.ring.hold.2":`Zgoda słabnie: gniazdo widzi łunę bazy.`,"ridge.ring.zorya":`ZORZA prowadzi wiązkę „Jerzyka” do pierścienia — akumulatory się ładują.`,"ridge.ring.zoryaOff":`„Jerzykowi” brakuje światła — ZORZA nie ma czym ładować akumulatorów.`,"hotbar.group.mining":`Wydobycie`,"hotbar.group.transport":`Transport`,"hotbar.group.craft":`Przetwarzanie`,"hotbar.group.lightnet":`Światło`,"hotbar.group.props":`Właściwości`,"hotbar.group.science":`Nauka`,"hotbar.group.defense":`Obrona`,"hotbar.group.space":`Kosmos`,"hotbar.group.special":`Specjalne`,"settings.buildNames":`Nazwy pod ikonami (pasek budynków i ekwipunek)`,"hotbar.tip.makes":`Wytwarza:`,"hotbar.tip.cost":`Budowa z:`,"goal.take":`Weź`,"hotbar.group.all":`Wszystkie`,"settings.hotbarTabs":`Karty grup budynków`,"settings.hotbarTabs.below":`Na dole`,"settings.hotbarTabs.above":`U góry`,"settings.hotbarTabs.fold":`Zwinięte`,"guide.tabs-open":`Budynki na dole są podzielone na grupy, jak narzędzia w szufladach. Naciśnij przycisk grupy po lewej stronie paska.`,"guide.lay-tunnel.quick":`Zabrakło grawitaśm. Naciśnij wytwarzanie nad grawitaśmą — warsztat kutra zrobi jeszcze {out} z kwarcu i płyty.`,"guide.lay-tunnel.quickPick":`Skończyły się grawitaśmy. Weź grawitaśmę z paska — nad nią pojawi się przycisk szybkiego wytwarzania.`,"hotbar.quickCraft":`Wytwórz: {name} +{n}`,"hotbar.quickCraft.no":`Brak zasobów: {name}`,"guide.tabs-all":`Zakładki to grupy: „Wydobycie”, „Transport”, „Światło”… Wybierz „Wszystko” — cały pasek będzie na widoku. Właściwą grupę otworzę sama.`,"guide.tabs-all.reopen":`Zakładki się zwinęły. Naciśnij przycisk grupy po lewej stronie paska i wybierz „Wszystkie”.`,"guide.tabs-all.done":`Gotowe: cały pasek jest widoczny. Zakładki są pod przyciskiem grupy, a wygląd paska — w {touch, select, yes {„Menu”} other {Esc}} → „Ustawienia” → „Interfejs”.`,"settings.tab.ui":`Interfejs`,"settings.preview":`Podgląd`,"settings.preview.fold":`Przycisk grupy po lewej rozwija karty.`,"settings.buildIcons":`Ikony budynków`,"settings.buildIcons.glyph":`Znak`,"settings.buildIcons.glyphModel":`Znak + model`,"settings.buildIcons.modelGlyph":`Model + znak`,"intro.t3":`Przystań`,"intro.p3":`Ostatnie miasto ludzi żyje przy przygasającej gwieździe Ognisko. Światło na kartki. Dzieci rysują słońce żółtą kredą.`,"hotbar.marks":`Wersje budynku`,"goal.splitter":`Zbadaj rozdzielacz grawitaśmy i postaw go`,"goal.splitter.why":`Jedna linia płyt karmi już kilka maszyn. Rozdzielacz dzieli ładunek po równo: co wchodzi z tyłu, wychodzi na zmianę w lewo i w prawo.`,"goal.splitter.hint":`Zbadaj „Rozdzielacz grawitaśmy” w Centrum (spektrum M). Wstaw go w przerwę linii strzałką zgodnie z ruchem ładunku: wejście z tyłu, wyjścia to grawitaśmy po lewej i po prawej. W oknie rozdzielacza: „po równo”, „najpierw lewe” lub „najpierw prawe”; zajęte wyjście oddaje wszystko drugiemu.`,"goal.splitter.done":`Dzieli uczciwie, jak ja kanapki na zmianie: jedna dla ciebie, jedna dla mnie.`,"goal.mark":`Zbadaj Szlifiernię Mk II i postaw ją na starej`,"goal.mark.why":`Centrum już nie przyspiesza maszyn — odblokowuje plany nowych wersji. Szlifiernia Mk II szlifuje {mul}× szybciej na tej samej powierzchni.`,"goal.mark.hint":`Zbadaj „Szlifiernia Mk II” w Centrum. Zbuduj ją (stara szlifiernia + płyty i soczewki) i postaw prosto na stojącej szlifierni — stara wróci do plecaka, a receptura przejdzie na nową. Nad budynkiem w ręce wybierasz wersję: I lub II.`,"goal.mark.done":`Ta sama szlifiernia, tylko złocista i żwawsza. Podoba mi się!`,"cfg.title.splitter":`Jak dzielić`,"cfg.splitter.0":`Po równo`,"cfg.splitter.1":`Najpierw lewe wyjście`,"cfg.splitter.2":`Najpierw prawe wyjście`,"cfg.title.light_splitter":`Jak dzielić`,"cfg.light_splitter.0":`Po równo`,"cfg.light_splitter.1":`Najpierw lewe wyjście`,"cfg.light_splitter.2":`Najpierw prawe wyjście`,"cfg.title.beam_splitter":`Jak dzielić`,"cfg.beam_splitter.0":`Po równo`,"cfg.beam_splitter.1":`Najpierw lewe wyjście`,"cfg.beam_splitter.2":`Najpierw prawe wyjście`,"lab.st.dark":`brak światła`,"lab.st.low":`mało światła`,"lab.light":`Światło: {have} z {need} ph/s`,"lab.dark":`Brak światła: to Centrum potrzebuje {need} ph/s. Poprowadź do niego światłowód od odbiornika — światło wchodzi z każdej strony.`,"lab.stock":`Zapas światła {m}:{s} — poprowadź światłowód do Centrum, zanim zapas się skończy.`,"lab.waitingLight":`Nauka jest, ale brak światła: Centrum odczytuje spektra tylko w świetle. Poprowadź do niego światłowód od odbiornika.`,"guide.lab-light":`Połóż jeden światłowód w ramce — między światłowodem linii a Centrum.`,"guide.lab-light.touch":`Weź światłowód i dotknij ramki między światłowodem linii a Centrum.`,"guide.lab-light.repick":`Weź światłowód: Centrum odczytuje spektra tylko w świetle.`,"guide.lab-light.away":`Centrum stoi poza ramką — poprowadź do niego światłowód od linii: światło wchodzi z każdej strony.`,"guide.lab-light.why":`W Centrum jest pryzmat: światło rozkłada się w wachlarz, a z niego odczytuje się spektra. Bez światła Centrum nie czyta.`,"guide.lab-light.stuck":`Nie świeci? Światłowód musi dotykać i światłowodu linii, i Centrum.`,"guide.lab-light.done":`Światło dotarło do Centrum. Teraz potrzebuje nauki.`,"goal.research.part":`Światło do Centrum — światłowód`,"goal.lab2.part.2":`Światło do każdego Centrum`,"goal.grabber.stuck":`Brak soczewki? Otwórz szlifiernię: receptura „Soczewka”; znak nad maszyną pokaże, czego brakuje — światła czy skały. Chwytaki wskazują strzałką kierunek przepływu: grawitaśma → szlifiernia → magazyn.`,"report.title":`Zgłoś błąd`,"report.open":`Zgłoś błąd`,"report.text":`Raport to tekst dla dewelopera: wersja gry, przeglądarka, karta graficzna, ekran, język, ostatnie błędy i podsumowanie świata. Nie ma w nim danych osobowych. Skopiuj go albo pobierz jako plik i wyślij z kilkoma słowami o tym, co się działo.`,"report.count":`Błędy w tej grze: {n}`,"report.copy":`Kopiuj raport`,"report.download":`Pobierz raport`,"report.copied":`Raport skopiowany`,"report.copyFailed":`Nie udało się skopiować — pobierz raport jako plik`,"report.toast":`W grze wystąpił błąd — raport pomoże go naprawić`,"report.link.telegram":`Opinia na Telegramie`,"report.link.discord":`Opinia na Discordzie`,"report.link.form":`Formularz opinii`,"report.wishlist":`Na listę życzeń Steam`,"crash.title":`Coś poszło nie tak`,"crash.text":`W grze wystąpił błąd. Świat jest zachowany z ostatniego zapisu. Wyślij raport — pomoże go naprawić.`,"crash.webgl.title":`Karta graficzna wyłączyła grę`,"crash.webgl.text":`Przeglądarka odebrała grze kartę graficzną (mało pamięci lub awaria sterownika). Uruchom ponownie — świat jest zapisany.`,"crash.nowebgl.title":`Przeglądarka nie jest obsługiwana`,"crash.nowebgl.text":`Gra wymaga WebGL. Otwórz ją w aktualnym Chrome, Edge, Firefox lub Safari i włącz przyspieszenie sprzętowe.`,"crash.restart":`Uruchom ponownie`,"web.fullscreen":`Pełny ekran`,"web.fullscreen.exit":`Wyjdź z pełnego ekranu`,"web.ios.home":`Na iPhonie: „Udostępnij” → „Do ekranu początkowego” — gra otworzy się na pełnym ekranie`,"web.safari":`Safari kasuje dane witryny, jeśli nie wchodzisz przez 7 dni. Uruchamiaj grę z ekranu początkowego albo od czasu do czasu zapisuj świat do pliku (Pauza → Zapisy → Eksport).`,"web.safari.short":`Safari kasuje dane witryny po 7 dniach bez wejścia — zapisuj świat do pliku (Zapisy → Eksport)`,"about.news":`Co nowego`,"about.report.text":`Znalazł się błąd albo coś jest niejasne? Wyślij raport — zbiera wszystko, co potrzebne do analizy.`,"tester.title":`Panel testera`,"tester.points":`Punkty kontrolne`,"tester.point.start":`Początek`,"tester.point.tutorial":`Po samouczku`,"tester.point.lab":`Pierwsze Centrum`,"tester.point.ridge":`Ścieżka: Szkarłatna Grań`,"tester.speed":`Prędkość świata`,"tester.give":`Dodaj zasoby`,"tester.given":`Zasoby w ekwipunku`,"tester.fps":`FPS i czas klatki`,"tester.demo":`Jak w demo`,"tester.clear":`Wyczyść magazyn`,"tester.clear.text":`Wszystkie światy, ustawienia i postęp tej wersji zostaną usunięte, a gra uruchomi się ponownie. Demo pozostanie nietknięte.`,"tester.note":`Punkt kontrolny to nowy świat na liście; bieżący świat zostaje zapisany. Prędkość i dodawanie zasobów psują powtórkę świata — tylko do testów.`,"tester.failed":`Nie udało się wczytać punktu kontrolnego — szczegóły w raporcie`,"tester.point.mid":`Środek: spektrum F`,"tester.point.late":`Późna Kolebka`,"lab.readingSlow":`Czyta jednostkę {k}/{n} · jeszcze ≈ {s} s — mało światła, {x}× wolniej`,"demo.title":`Koniec dema`,"demo.lead":`Rój mówi. Matwiej coś wie. A ORA raz już zdecydowała za ciebie. Dalej w pełnej grze — nieśmiertelnik Matwieja, kanał do domu, Hiperwrota i:`,"demo.next":`Co dalej`,"demo.f.light":`Polaryzacja i faza`,"demo.f.light.desc":`Jeszcze dwie właściwości światła — nowe linie, soczewki i maszyny`,"demo.f.sphere":`Sfera Dysona w pełnej krasie`,"demo.f.sphere.desc":`Powłoki wokół gwiazdy, drony, planety i wahadłowce`,"demo.f.gate":`Hiperwrota i finał Kolebki`,"demo.f.gate.desc":`Losy bohaterów, Rój i wybór, który rozstrzyga, jak to się skończy`,"demo.f.path":`Droga do innych gwiazd`,"demo.f.path.desc":`Szkarłatna Grań i dalej — w miarę premier`,"demo.f.modes":`Nowy świat, tryb kreatywny, eksperymenty`,"demo.f.modes.desc":`Własne ustawienia świata, wszystko otwarte, zadania z oceną, „Gwiazda tygodnia”`,"demo.keep":`Świat zostaje twój: możesz dalej budować, ulepszać linie i odpierać Rój.`,"demo.export":`Zapisz świat do pliku`,"demo.play":`Graj dalej`,"demo.transfer":`Świat z dema przechodzi do pełnej gry: otwórz plik tam przez „Światy” → „Importuj świat”.`,"demo.locked":`W pełnej grze`,"demo.goal":`Granica dema osiągnięta — dalej kampania toczy się w pełnej grze.`,"full.lead.demo":`To demo: początek kampanii Kolebki. Pełna gra odblokowuje:`,"full.f.campaign":`Cała kampania Kolebki`,"full.f.campaign.desc":`Polaryzacja, faza, sfera Dysona, planety i Hiperwrota`,"crash.sim.title":`Świat zatrzymany`,"crash.sim.text":`W obliczeniach świata wystąpił błąd, więc go zatrzymaliśmy, by nie uszkodzić zapisów: ostatni zapis jest cały. Wyślij raport i uruchom grę ponownie.`,"hand.keys":`LPM — postaw · {rotate} — obróć · PPM — odłóż z ręki · {pipette} — weź taki sam`,"settings.fpsCap":`Limit klatek`,"settings.fpsCap.off":`Jak ekran`,"settings.fullscreen":`Pełny ekran (Alt+Enter)`,"settings.autoQuality":`Obniżaj jakość przy długim spadku klatek`,"settings.bgMute":`Ciszej, gdy okno gry jest nieaktywne`,"settings.uiScale.auto":`Auto ({n}%)`,"remove.farLeft":`Poza zasięgiem zostało: {n}`,"remove.farLeft.fly":`Podleć`,"about.legal":`Prawa i licencje`,"about.legal.text":`© {year} Sergey Segrenev. Wszelkie prawa zastrzeżone. W grze użyto bibliotek open source — ich licencje są w osobnym pliku.`,"about.licenses":`Licencje zewnętrzne`,"creative.speed":`Prędkość świata`,"achv.first_waking.name":`Pierwsze przebudzenie`,"achv.first_waking.desc":`Światło dotarło do kapsuły — kolonista otworzył oczy.`,"achv.first_landing.name":`Twardy grunt`,"achv.first_landing.desc":`Stacja i lądownik na powierzchni planety.`,"achv.first_split.name":`Rozwidlenie`,"achv.first_split.desc":`Pierwszy rozdzielacz dzieli strumień na dwa.`,"achv.first_mark.name":`Mk II`,"achv.first_mark.desc":`Szlifiernia Mk II stanęła na miejscu poprzedniej.`,"achv.gate_home.name":`Droga do domu`,"achv.gate_home.desc":`Hiperwrota Kolebki są otwarte — skok wykonany.`,"achv.ark_away.name":`W drogę`,"achv.ark_away.desc":`Arka zmontowana i odleciała ku następnej gwieździe.`,"achv.ridge_core.name":`Jądro pierścienia`,"achv.ridge_core.desc":`Jądro pierścienia Szkarłatnej Grani jest zbudowane i stoi na miejscu.`,"achv.ridge_open.name":`Pierścień Grani`,"achv.ridge_open.desc":`Pierścień Szkarłatnej Grani jest otwarty.`,"goal.done.path":`Wydana część drogi ukończona. Droga do następnej gwiazdy jest jeszcze wytyczana — otworzy się w aktualizacji.`,"inv.search":`Szukaj: budynek lub przedmiot (Ctrl+F)`,"inv.notFound":`Nic nie znaleziono`,"place.glare.shade":`Ukryje warsztaty przed gniazdami: {n}`,"place.glare.absorber":`Wygasi ≈ {q} z {m} ph/s łuny`,"hud.glareEye":`Gniazdo widzi: {p} %`,"hud.glareLeak":`wycieki {v} ph/s`,"hud.glareGrace":`oczy się przyzwyczajają: {m} min`,"hud.glareNest":`Gniazdo {dir} — widzi {p} %{awake, select, yes { · nie śpi} other {}}`,"hud.glareSee":`{name} — {v} ph/s, widzą gniazda: {k}`,"dir.0":`na wschodzie`,"dir.1":`na południowym wschodzie`,"dir.2":`na południu`,"dir.3":`na południowym zachodzie`,"dir.4":`na zachodzie`,"dir.5":`na północnym zachodzie`,"dir.6":`na północy`,"dir.7":`na północnym wschodzie`,"machine.sight.light":`Łuna {n} ph/s (praca {w} · wyciek {l})`,"machine.sight.quenched":`wygaszono {n}`,"machine.sight.shaded":`w cieniu przed gniazdami: {k}`,"machine.sight.seenBy":`widzą gniazda: {k}`,"machine.sight.absorber":`Gasi {q} z {b} ph/s (do {p} % u każdego) · nadwyżka sieci {s} · osłonięte budynki: {k}`,"machine.sight.shadeAt":`Patrzy na gniazdo {dir}`,"machine.sight.shadeNone":`Żadne gniazdo tu nie patrzy`,"machine.sight.hides":`ukrywa budynki: {k} ({n} ph/s)`,"machine.sight.inSector":`jeszcze gniazd w sektorze: {j}`,"machine.sight.auto":`Celuj sam`,"machine.sight.wakes":`Obudzi swoim światłem gniazd: {k}`,"swarm.sight":`Gniazda widzące bazę: {k}; najbardziej niespokojne — {p} % progu przebudzenia`,"guide.glare-eyes":`Gniazdo uchyliło oczy: widzi światło naszych maszyn. Im bliżej niego, tym jaśniej płoniemy. {touch, select, yes {Stuknij} other {Kliknij}} pasek „Łuna”.`,"guide.glare-eyes.why":`Gniazdo patrzy na światło warsztatów — pryzmaty, optykę, montownie. Gdy się obudzi, wyśle oddziały do najjaśniejszego.`,"guide.glare-learn":`Pochłaniacz gasi światło warsztatów w swoim kręgu. Zbadaj „Pochłaniacz” w Centrum.`,"guide.glare-learn.reopen":`Otwórz Centrum i dodaj „Pochłaniacz” do kolejki.`,"guide.glare-learn.why":`To pierwszy krok do cienia: bez niego gniazdo widzi całą bazę.`,"guide.glare-absorber":`Postaw pochłaniacz przy najjaśniejszym warsztacie, który widzi gniazdo. Jego krąg gasi światło — promień odbiorników także.`,"guide.glare-absorber.why":`Najpierw gasi nadwyżkę sieci. Stawiaj go poza liniami światła — albo postaw wieżyczkę przy warsztacie: falę ktoś powita.`,"guide.glare-absorber.stuck":`Gniazdo nadal widzi jasno? Drugi pochłaniacz obok — albo warsztat dalej: o pierścień dalej jest wyraźnie ciemniej.`,"guide.glare-absorber.done":`Oczy gniazda przygasają. Światło zostaje przy nas.`,"guide.glare-shade":`Postaw zasłonę wśród warsztatów, żaglem do gniazda: w jej kręgu gniazdo zobaczy je przygaszone. Nie przy odbiornikach.`,"guide.glare-shade.why":`Zasłona sama obraca się do gniazda, które najmocniej widzi jej krąg. Obrócisz ją ręką — zapamięta kierunek.`,"guide.glare-shade.stuck":`Gniazdo nadal widzi? Druga zasłona — albo zasłona bliżej najjaśniejszych warsztatów.`,"guide.glare-shade.done":`Gniazdo widzi tylko ciemność i zamyka oczy. Utrzymamy cień — a odwróci się na zawsze.`,"toast.glareGrace":`ORA: Gniazda nauczyły się rozpoznawać światło warsztatów. Ich oczy przyzwyczajają się powoli — mamy {m} min, by ukryć światła.`,"toast.glareGift":`Dar dla cienia: zasłony i pochłaniacze — po {n} szt.`,"toast.showNests":`Pokaż gniazda`,"place.glare.cost":`Cień: odbiorniki {r}, łuki {a} — świecą słabiej`,"hover.shell.shade":`Cień pochłaniaczy i zasłon: −{p} % wydajności`,"machine.sight.zoneShade":`Cień pochłaniacza lub zasłony: −{p} % promienia — odsuń je dalej`,"settings.noItemToast":`Komunikat „Brak w ekwipunku”`,"settings.glarePlate":`Pasek „Łuna”`,"settings.glarePlate.icons":`Ikony`,"settings.glarePlate.text":`Tekst`,"settings.glarePlate.off":`Ukryj`,"hud.glareAria":`Łuna {v} ph/s, gniazdo widzi: {p} %{awake, select, yes { — gniazdo się obudziło} other {}}`,"hud.glareShort":`Łuna {v}`,"hud.glareEyeShort":`Gniazdo {p} %`,"settings.tipsAuto":`Dopóki bez zmian — widoczne tylko w samouczku`,"hud.glareSqRay":`Łuna`,"hud.glareSqRayV":`{v} ph/s`,"hud.glareSqEye":`Gniazdo widzi`,"guide.kind.act":`Zrób to`,"guide.kind.watch":`Patrz`,"guide.kind.read":`Czytaj`,"guide.closesNext":`„Dalej” zamknie okno.`,"guide.tree-look":`To drzewo — droga od Pryzmatu do finału. „Zbadaj ścieżkę” — i Centrum samo ułoży kolejkę.`,"guide.map-open.done":`To mapa układu. Ciemne obszary to mgła: tych miejsc jeszcze nikt nie odwiedził. Mgła rozwiewa się tam, gdzie przeleci kuter, i wokół radarów bazy.`,"guide.map-fly.stuck":`{touch, select, yes {Miejsce wybiera krótkie stuknięcie bez ruchu. Jeśli mapa się przesunęła, stuknij jeszcze raz bez przeciągania.} other {Miejsce wybiera kliknięcie bez ruchu myszy. Jeśli mapa się przesunęła, kliknij jeszcze raz, nie ruszając myszą.}}`,"guide.map-fly.done":`Kuter w drodze. Dowolne sterowanie odda ci kontrolę, a mapa jest zawsze pod przyciskiem mapy.`,"guide.glare-eyes.done":`Promień to ile światła baza oddaje w niebo, oko — ile z niego widzi gniazdo. Czerwień — gniazdo lada chwila się obudzi.`,"guide.ship-modules":`To moduły kutra: energia, tarcza, broń. Każdy moduł to nowa siła — z żelastwem pomogę.`,"hab.emergency":`Śpiący na zasilaniu awaryjnym: {n}`};export{e as default};
